INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "已婚女子,是丈夫的配偶。", "primary_collocate": null, "pronunciation": "qī zi", "ipa": "t͡ɕʰi˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "他的妻子在医院工作。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妻子今天回来得很晚。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生和妻子一起去旅行。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给妻子买了一束花。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子做的菜非常好吃。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妻子是我的老同学。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李明很爱他的妻子。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子在家等着他回来吃饭。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和妻子结婚十年了。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把礼物送给了妻子。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已婚女子，丈夫的配偶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：妻子 qī zi，指丈夫的配偶。"}, {"text": "旗子", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。"}, {"text": "起子", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起子（开瓶器）。"}, {"text": "棋子", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是棋子。"}, {"text": "机子", "is_correct": false, "explanation": "jī 与 qī 声母不同（j 与 q），口语中指机器。"}], "explanations": {"妻子": "正确：妻子 qī zi，指丈夫的配偶。", "旗子": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。", "起子": "qǐ（第三声）与 qī（第一声）声调不同，意思是起子（开瓶器）。", "棋子": "qí（第二声）与 qī（第一声）声调不同，意思是棋子。", "机子": "jī 与 qī 声母不同（j 与 q），口语中指机器。"}, "sentence_index": null, "correct_answer": "妻子"}, "level_3": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：“妻子”指他的配偶，能与“在医院工作”的主语搭配。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不能在医院工作，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“工作”的主语应是人或机构，不能用“汽车”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能在医院工作，与句意不符。"}], "explanations": {"妻子": "正确：“妻子”指他的配偶，能与“在医院工作”的主语搭配。", "猫": "语义：猫是动物，不能在医院工作，句意不通。", "汽车": "搭配：“工作”的主语应是人或机构，不能用“汽车”。", "桌子": "语义：桌子是家具，不能在医院工作，与句意不符。"}, "sentence_index": 0, "correct_answer": "妻子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的妻子是一位男士，他们结婚十年了。", "explanation": "这里应该用〈丈夫〉。“妻子”指女性配偶，不能用来指男性配偶。"}, {"text": "这位妻子还没有结婚。", "explanation": "这里应该用〈女朋友〉。“妻子”指已经结婚的女性，“还没有结婚”的人应说“女朋友”。"}, {"text": "他的妻子今年还在上小学一年级。", "explanation": "这里应该用〈女儿〉。“妻子”指成年已婚女性，上小学一年级的孩子应说“女儿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：“妻子”指他的配偶，是“很爱”的对象，与句意相符。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是哀悼逝者的仪式，不是“很爱”的对象，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是可以被“很爱”的对象，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不能说“很爱他的星期”，句意不通。"}], "explanations": {"妻子": "正确：“妻子”指他的配偶，是“很爱”的对象，与句意相符。", "葬礼": "语义：葬礼是哀悼逝者的仪式，不是“很爱”的对象，句意不通。", "考试": "语义：考试不是可以被“很爱”的对象，句意不通。", "星期": "语义：“星期”是时间单位，不能说“很爱他的星期”，句意不通。"}, "sentence_index": 6, "correct_answer": "妻子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家那只猫是我的妻子。", "explanation": "这里应该用〈宠物〉。“妻子”指人，不能指猫；猫应说“宠物”或“猫”。"}, {"text": "我的妻子只有三岁。", "explanation": "这里应该用〈孩子〉。“妻子”指成年的已婚女性，三岁的小孩应说“孩子”。"}, {"text": "我们班的妻子明天考试。", "explanation": "这里应该用〈同学〉。“妻子”是对丈夫而言的配偶，不能指班里的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
