INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情报是别人不知道、对你很有用的消息。", "primary_collocate": null, "pronunciation": "qíng bào", "ipa": "tɕʰiŋ˧˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司很会收集市场情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉了我一条有用的情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练先看了对手的情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要有好的情报，才不会吃亏。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个情报对我找工作帮助很大。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给了我一份旅游情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠着最新的情报，买到了便宜的票。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有关于那家店的情报？", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人还不知道，这个情报只有我有。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个情报告诉了妈妈。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "情报：别人不知道、对自己很有用的消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情报", "is_correct": true, "explanation": "正确：“收集市场情报”指搜集别人不知道、对公司有用的消息，句意通顺。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”与公司的市场工作无关，“很会收集市场脚印”说不通。"}, {"text": "邮票", "is_correct": false, "explanation": "搭配：“收集”能接“邮票”，但“市场”和“邮票”不搭，“收集市场邮票”说不通。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶与公司的市场工作无关，“很会收集市场树叶”说不通。"}], "explanations": {"情报": "正确：“收集市场情报”指搜集别人不知道、对公司有用的消息，句意通顺。", "脚印": "语义：“脚印”与公司的市场工作无关，“很会收集市场脚印”说不通。", "邮票": "搭配：“收集”能接“邮票”，但“市场”和“邮票”不搭，“收集市场邮票”说不通。", "树叶": "语义：树叶与公司的市场工作无关，“很会收集市场树叶”说不通。"}, "sentence_index": 0, "correct_answer": "情报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得到了一根很有用的情报，所以买到了便宜的票。", "explanation": "量词：“根”用于细长的东西，不能用来数“情报”，应说“一条情报”。"}, {"text": "他拿到了一把情报，很快就告诉了妈妈。", "explanation": "量词：“把”用于有柄的器具，不能用来数“情报”，应说“一条情报”。"}, {"text": "这家公司收到了一颗情报，马上采取了行动。", "explanation": "量词：“颗”用于粒状的东西，不能用来数“情报”，应说“一条情报”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情报", "is_correct": true, "explanation": "正确：“最新的情报”指刚得到的、别人不知道的消息，靠它买到便宜的票，句意通顺。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：靠饼干买到便宜的票说不通，饼干不是消息。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话没有实用价值，不能帮人买到便宜的票。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“最新的”不修饰“天气”，“最新的天气”说不通。"}], "explanations": {"情报": "正确：“最新的情报”指刚得到的、别人不知道的消息，靠它买到便宜的票，句意通顺。", "饼干": "语义：靠饼干买到便宜的票说不通，饼干不是消息。", "笑话": "语义：笑话没有实用价值，不能帮人买到便宜的票。", "天气": "搭配：“最新的”不修饰“天气”，“最新的天气”说不通。"}, "sentence_index": 6, "correct_answer": "情报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲了一个情报，大家都笑了。", "explanation": "这里应该用〈笑话〉。“情报”指别人不知道、有用的消息，不是用来讲的笑话。"}, {"text": "天冷了，他穿上了一件厚情报。", "explanation": "这里应该用〈衣服〉。“穿上”的对象应是衣服，“情报”是消息，不能穿在身上。"}, {"text": "他一边唱情报一边跳舞。", "explanation": "这里应该用〈歌词〉。“唱”的对象应是歌词，“情报”不能被唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给我看了一根重要的情报。", "corrected_sentence": "她给我看了一条重要的情报。", "error_description": "“情报”的量词用错：“根”用于细长的东西，“情报”应说“一条”，要把“一根”改为“一条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈从朋友那里得到了一根情报。", "corrected_sentence": "妈妈从朋友那里得到了一条情报。", "error_description": "量词用错：“根”用于细长的东西，不能用来数“情报”，应说“一条情报”，要把“一根”改为“一条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
