INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经过搜集而得到的、具有重要价值的秘密消息。", "primary_collocate": null, "pronunciation": "qíng bào", "ipa": "tɕʰiŋ˧˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "间谍偷走了国家的重要情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，情报比枪更重要。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在情报部门工作了二十年。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察得到了一份秘密情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人把军事情报卖给了别的国家。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份情报很重要，不能给任何人看。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵送来了敌人的情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把情报送到了总部。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责收集和分析各种情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在找敌人的情报。", "target_word": "情报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情報", "label": "繁体"}], "register": "书面", "sense_fingerprint": "情报：经过搜集得到的、有重要价值的秘密消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情报", "is_correct": true, "explanation": "正确：间谍偷走的是经过搜集、有重要价值的秘密消息，句意通顺。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是秘密消息，与“重要”和“秘密”的含义不符。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话没有重要价值，不是间谍会偷的东西。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“偷走”的对象不能是“天气”，“偷走国家的重要天气”说不通。"}], "explanations": {"情报": "正确：间谍偷走的是经过搜集、有重要价值的秘密消息，句意通顺。", "饼干": "语义：饼干不是秘密消息，与“重要”和“秘密”的含义不符。", "笑话": "语义：笑话没有重要价值，不是间谍会偷的东西。", "天气": "搭配：“偷走”的对象不能是“天气”，“偷走国家的重要天气”说不通。"}, "sentence_index": 0, "correct_answer": "情报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口渴了，喝了一杯情报。", "explanation": "这里应该用〈水〉。“喝”的对象应是饮料，“情报”是秘密消息，不能喝。"}, {"text": "她一边唱情报一边弹吉他。", "explanation": "这里应该用〈歌词〉。“唱”的对象应是歌词，“情报”不能被唱。"}, {"text": "天冷了，他穿上了一件厚情报。", "explanation": "这里应该用〈衣服〉。“穿上”的对象应是衣服，“情报”是秘密消息，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情报", "is_correct": true, "explanation": "正确：士兵送来的是敌人的秘密消息，句意通顺。"}, {"text": "作业", "is_correct": false, "explanation": "语义：士兵不会送来敌人的作业，“作业”与军事情报无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“送来”，与军事情报无关，“送来敌人的天气”说不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被“送来”，与军事情报无关，“送来敌人的影子”说不通。"}], "explanations": {"情报": "正确：士兵送来的是敌人的秘密消息，句意通顺。", "作业": "语义：士兵不会送来敌人的作业，“作业”与军事情报无关。", "天气": "语义：天气不能被“送来”，与军事情报无关，“送来敌人的天气”说不通。", "影子": "语义：影子不能被“送来”，与军事情报无关，“送来敌人的影子”说不通。"}, "sentence_index": 6, "correct_answer": "情报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找到了一根敌人的情报。", "explanation": "量词：“根”用于细长的东西，不能用来数“情报”，应说“一份情报”。"}, {"text": "他拿到了一把敌人的情报。", "explanation": "量词：“把”用于有柄的器具，不能用来数“情报”，应说“一份情报”。"}, {"text": "他得到了一台敌人的情报。", "explanation": "量词：“台”用于机器等，不能用来数“情报”，应说“一份情报”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一把重要情报。", "corrected_sentence": "他找到了一份重要情报。", "error_description": "量词用错：“把”用于有柄的器具，不能用来数“情报”，“情报”应用量词“份”，要把“一把”改为“一份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哨兵送来了一根敌人的情报。", "corrected_sentence": "哨兵送来了一份敌人的情报。", "error_description": "“情报”的量词用错：“根”用于细长的东西，“情报”应说“一份”，要把“一根”改为“一份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
