INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "实在就是真的,不是假的,也不骗人。", "primary_collocate": null, "pronunciation": "shí zai", "ipa": "ʂɻ̩˧˥ tsai̯", "syllable_count": 2, "sentences": [{"text": "这个卖水果的人很实在，不会骗人。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话很实在，不是骗人的。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖东西很实在，不会多收钱。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个实在的姑娘，有什么说什么。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要实在，不能骗来骗去。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李人很实在，借他的钱一定会还。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我很实在，从来不骗我。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王师傅干活实在，用的都是好材料。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个人不实在，说的话常常是假的。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西要找实在的商家，不要买到假货。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实实在在", "label": "重叠"}], "register": "中性", "sense_fingerprint": "实在:形容词,真的不假,不骗人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88253, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。实在（shí zai）：真的，不是假的，也不骗人。"}, {"text": "时代", "is_correct": false, "explanation": "时代（shí dài）与实在只差声母（z 与 d），意思是“时代”。"}, {"text": "时态", "is_correct": false, "explanation": "时态（shí tài）与实在只差声母（z 与 t），意思是“时态”。"}, {"text": "十载", "is_correct": false, "explanation": "十载（shí zǎi）与实在（shí zai）只差第二个字的声调（第三声与轻声），意思是“十年”。"}, {"text": "是在", "is_correct": false, "explanation": "是在（shì zài）与实在只差第一个字的声调（第四声与第二声），意思是“处于某处；表示强调”。"}], "explanations": {"实在": "正确答案。实在（shí zai）：真的，不是假的，也不骗人。", "时代": "时代（shí dài）与实在只差声母（z 与 d），意思是“时代”。", "时态": "时态（shí tài）与实在只差声母（z 与 t），意思是“时态”。", "十载": "十载（shí zǎi）与实在（shí zai）只差第二个字的声调（第三声与轻声），意思是“十年”。", "是在": "是在（shì zài）与实在只差第一个字的声调（第四声与第二声），意思是“处于某处；表示强调”。"}, "sentence_index": null, "correct_answer": "实在"}, "level_3": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。“很实在，不会骗人”说的是为人真诚，前后一致。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”指耍心眼，与“不会骗人”的意思相矛盾。"}, {"text": "奸诈", "is_correct": false, "explanation": "语义：“奸诈”指欺骗使坏，与“不会骗人”完全相反。"}, {"text": "虚伪", "is_correct": false, "explanation": "语义：“虚伪”指表里不一、不真诚，与“不会骗人”相矛盾。"}], "explanations": {"实在": "正确答案。“很实在，不会骗人”说的是为人真诚，前后一致。", "狡猾": "语义：“狡猾”指耍心眼，与“不会骗人”的意思相矛盾。", "奸诈": "语义：“奸诈”指欺骗使坏，与“不会骗人”完全相反。", "虚伪": "语义：“虚伪”指表里不一、不真诚，与“不会骗人”相矛盾。"}, "sentence_index": 0, "correct_answer": "实在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试前我很实在，一直睡不着。", "explanation": "这里应该用〈紧张〉。实在用于说人的为人或东西的可靠，不用来形容心理状态，说心里不安要用紧张。"}, {"text": "他的声音很实在，全班都听见了。", "explanation": "这里应该用〈响亮〉。实在不用来形容声音，说声音大要用响亮。"}, {"text": "我们需要实在的时间，不能拖延。", "explanation": "这里应该用〈确切〉。实在不用来修饰“时间”，说明具体的时刻要用确切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') 