INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。“很实在，从不骗我”指对人真诚，与后半句一致。"}, {"text": "狡诈", "is_correct": false, "explanation": "语义：“狡诈”指欺骗，与“从不骗我”矛盾。"}, {"text": "奸猾", "is_correct": false, "explanation": "语义：“奸猾”指狡猾奸诈，与“从不骗我”相矛盾。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多指身体或东西牢固，不用来形容对人的态度。"}], "explanations": {"实在": "正确答案。“很实在，从不骗我”指对人真诚，与后半句一致。", "狡诈": "语义：“狡诈”指欺骗，与“从不骗我”矛盾。", "奸猾": "语义：“奸猾”指狡猾奸诈，与“从不骗我”相矛盾。", "结实": "搭配：“结实”多指身体或东西牢固，不用来形容对人的态度。"}, "sentence_index": 6, "correct_answer": "实在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片沙漠非常实在，几十里看不到人。", "explanation": "这里应该用〈荒凉〉。实在用于说人的为人或东西的可靠，不用来形容地方的景象，说地方萧条无人要用荒凉。"}, {"text": "梅雨季节空气很实在，衣服总也干不了。", "explanation": "这里应该用〈潮湿〉。实在不用来形容空气，说空气湿润、水汽重要用潮湿。"}, {"text": "这幅画的色彩很实在，一下子就吸引了我。", "explanation": "这里应该用〈鲜艳〉。实在不用来形容颜色，说颜色明亮好看要用鲜艳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位大姐是个很实在人，从不缺斤少两。", "corrected_sentence": "那位大姐是个很实在的人，从不缺斤少两。", "error_description": "“很实在”修饰名词“人”时要加“的”，“很实在人”不成立，应说“很实在的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想找一个实在地装修师傅。", "corrected_sentence": "我想找一个实在的装修师傅。", "error_description": "形容词修饰名词时要用“的”，不用“地”；“地”用于动词前，“实在地装修师傅”不成立，应说“实在的装修师傅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
