INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88254, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真实;不虚假;诚恳不浮夸。", "primary_collocate": null, "pronunciation": "shí zai", "ipa": "ʂɻ̩˧˥ tsai̯", "syllable_count": 2, "sentences": [{"text": "他这个人很实在，从来不说假话。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说话实在，大家都愿意跟他做生意。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我的建议很实在。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西又好又便宜，价格很实在。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为人实在，朋友很多。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师讲课很实在，没有一句空话。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王做事很实在，从不偷懒。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢和实在的人交朋友。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话听起来很实在，我就相信了。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答很实在，没有骗人。", "target_word": "实在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实实在在", "label": "重叠"}], "register": "中性", "sense_fingerprint": "实在:形容词,真实诚恳,不虚假不浮夸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。实在（shí zai）：真实，不虚假；诚恳，不浮夸。"}, {"text": "时代", "is_correct": false, "explanation": "时代（shí dài）与实在只差声母（z 与 d），意思是“时代”。"}, {"text": "时态", "is_correct": false, "explanation": "时态（shí tài）与实在只差声母（z 与 t），意思是“时态”。"}, {"text": "十载", "is_correct": false, "explanation": "十载（shí zǎi）与实在（shí zai）只差第二个字的声调（第三声与轻声），意思是“十年”。"}, {"text": "是在", "is_correct": false, "explanation": "是在（shì zài）与实在只差第一个字的声调（第四声与第二声），意思是“处于某处；表示强调”。"}], "explanations": {"实在": "正确答案。实在（shí zai）：真实，不虚假；诚恳，不浮夸。", "时代": "时代（shí dài）与实在只差声母（z 与 d），意思是“时代”。", "时态": "时态（shí tài）与实在只差声母（z 与 t），意思是“时态”。", "十载": "十载（shí zǎi）与实在（shí zai）只差第二个字的声调（第三声与轻声），意思是“十年”。", "是在": "是在（shì zài）与实在只差第一个字的声调（第四声与第二声），意思是“处于某处；表示强调”。"}, "sentence_index": null, "correct_answer": "实在"}, "level_3": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。“很实在”指为人诚实可靠，与“从来不说假话”一致。"}, {"text": "虚伪", "is_correct": false, "explanation": "语义：“虚伪”指表里不一，与“从来不说假话”矛盾。"}, {"text": "虚假", "is_correct": false, "explanation": "语义：“虚假”指不真实，说这个人“很虚假”，就与“从来不说假话”相矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多指物体或文风，不用来形容人的为人，“很干燥”搭配不当。"}], "explanations": {"实在": "正确答案。“很实在”指为人诚实可靠，与“从来不说假话”一致。", "虚伪": "语义：“虚伪”指表里不一，与“从来不说假话”矛盾。", "虚假": "语义：“虚假”指不真实，说这个人“很虚假”，就与“从来不说假话”相矛盾。", "干燥": "搭配：“干燥”多指物体或文风，不用来形容人的为人，“很干燥”搭配不当。"}, "sentence_index": 0, "correct_answer": "实在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故发生后，他非常实在，马上报了警。", "explanation": "这里应该用〈冷静〉。实在指人的为人诚恳、办事踏实，不用来形容人在紧急时刻的镇定，这种情况要用冷静。"}, {"text": "会议上气氛非常实在，大家都不说话。", "explanation": "这里应该用〈严肃〉。实在用于说人的为人或东西的可靠，不用来形容场合的庄重气氛，说气氛庄重要用严肃。"}, {"text": "我今天的心情很实在，想哭就哭。", "explanation": "这里应该用〈低落〉。实在不用来形容心情，说心情不好要用低落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实在", "is_correct": true, "explanation": "正确答案。“很实在”指做事踏实可靠，与“从不偷懒”一致。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指做事松懈，与“从不偷懒”矛盾。"}, {"text": "拖沓", "is_correct": false, "explanation": "语义：“拖沓”指办事拖延，与“从不偷懒”不合。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多指身体或物品牢固，不说“做事很结实”。"}], "explanations": {"实在": "正确答案。“很实在”指做事踏实可靠，与“从不偷懒”一致。", "懒散": "语义：“懒散”指做事松懈，与“从不偷懒”矛盾。", "拖沓": "语义：“拖沓”指办事拖延，与“从不偷懒”不合。", "结实": "搭配：“结实”多指身体或物品牢固，不说“做事很结实”。"}, "sentence_index": 6, "correct_answer": "实在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的夜景非常实在，每年都吸引很多游客。", "explanation": "这里应该用〈漂亮〉。实在用于说人的品性或东西的可靠，不用来形容景色好看，说夜景美要用漂亮。"}, {"text": "深夜的山村非常实在，只能听见虫鸣。", "explanation": "这里应该用〈寂静〉。实在不用来形容环境的安静，说环境无声无息要用寂静。"}, {"text": "春节的街道上非常实在，到处都是人。", "explanation": "这里应该用〈热闹〉。实在不用来形容场面喧闹，说街上人多、气氛活跃要用热闹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个实在地朋友，从来不骗我。", "corrected_sentence": "他是一个实在的朋友，从来不骗我。", "error_description": "“实在”修饰名词时要用“的”，不用“地”；“地”用于动词前，“实在地朋友”不成立，应说“实在的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个很实在人，有事总会帮忙。", "corrected_sentence": "他是个很实在的人，有事总会帮忙。", "error_description": "“很实在”修饰名词“人”时要加“的”，“很实在人”不成立，应说“很实在的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
