INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88256, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示紧随其后；承接上文。", "primary_collocate": null, "pronunciation": "jiē zhe", "ipa": "tɕjɛ˥ ʈʂɤ", "syllable_count": 2, "sentences": [{"text": "他先说了名字，接着说了年龄。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一个人唱完了，接着轮到我。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先坐地铁，接着换公共汽车。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完报告，接着回答了大家的问题。", "target_word": "接着", "complexity_tier": "T3", "furigana": "Tā dú wán bàogào, jiēzhe huídá le dàjiā de wèntí.", "sentence_source": "generated"}, {"text": "音乐停了，接着是一片掌声。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了看窗外，接着关上了门。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完药，接着躺下休息。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面讲的是历史，接着讲地理。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王说完后，接着小李也发了言。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯突然灭了，接着传来一声大叫。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接着：副词，承接上文、紧随其后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4833d5f1-cf75-4236-a0b9-bf3c5753a5f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88256, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接着", "is_correct": true, "explanation": "正确。接着（jiē zhe）表示承接上文、紧随其后。"}, {"text": "结着", "is_correct": false, "explanation": "jié zhe（第二声）与 jiē zhe（第一声）声调不同，意思是“结”，如“结着果子”。"}, {"text": "借着", "is_correct": false, "explanation": "jiè zhe（第四声）与 jiē zhe（第一声）声调不同，意思是“凭借”，如“借着机会”。"}, {"text": "歇着", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），意思是“休息”。"}, {"text": "解着", "is_correct": false, "explanation": "jiě zhe（第三声）与 jiē zhe（第一声）声调不同，意思是“解开”，如“解着扣子”。"}], "explanations": {"接着": "正确。接着（jiē zhe）表示承接上文、紧随其后。", "结着": "jié zhe（第二声）与 jiē zhe（第一声）声调不同，意思是“结”，如“结着果子”。", "借着": "jiè zhe（第四声）与 jiē zhe（第一声）声调不同，意思是“凭借”，如“借着机会”。", "歇着": "xiē 与 jiē 声母不同（x 与 j），意思是“休息”。", "解着": "jiě zhe（第三声）与 jiē zhe（第一声）声调不同，意思是“解开”，如“解着扣子”。"}, "sentence_index": null, "correct_answer": "接着"}, "level_3": {"options": [{"text": "接着", "is_correct": true, "explanation": "接着表示紧随其后，“他先说了名字，接着说了年龄”前后顺承。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，此处只是前后顺承，不应转折。"}, {"text": "反倒", "is_correct": false, "explanation": "语义：“反倒”表示与预期相反，与顺承的叙述不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此，不能连接“说了名字”之后的下一个动作。"}], "explanations": {"接着": "接着表示紧随其后，“他先说了名字，接着说了年龄”前后顺承。", "却": "语义：“却”表示转折，此处只是前后顺承，不应转折。", "反倒": "语义：“反倒”表示与预期相反，与顺承的叙述不合。", "从来": "语义：“从来”表示一贯如此，不能连接“说了名字”之后的下一个动作。"}, "sentence_index": 0, "correct_answer": "接着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边读报告，接着听大家发言。", "explanation": "这里表示同时进行，应该用〈同时〉。“接着”只表示先后相继，不能表示同时。"}, {"text": "我还以为她出门了，接着她在办公室。", "explanation": "这里应该用〈原来〉。“原来”表示发现真相，“接着”不能表示“没想到”。"}, {"text": "虽然天很冷，接着我们还去游泳。", "explanation": "这里应该用〈却〉。“虽然”需要与“却”呼应，“接着”只表示先后，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接着", "is_correct": true, "explanation": "接着表示紧接着，“他吃完药，接着躺下休息”前后衔接自然。"}, {"text": "原本", "is_correct": false, "explanation": "语义：“原本”表示起初的状态，与承接前一动作不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此，不能用于吃药后的这一次动作。"}, {"text": "不断", "is_correct": false, "explanation": "搭配：“不断”修饰反复发生的动作，不能修饰一次性的“躺下”。"}], "explanations": {"接着": "接着表示紧接着，“他吃完药，接着躺下休息”前后衔接自然。", "原本": "语义：“原本”表示起初的状态，与承接前一动作不合。", "从来": "语义：“从来”表示一贯如此，不能用于吃药后的这一次动作。", "不断": "搭配：“不断”修饰反复发生的动作，不能修饰一次性的“躺下”。"}, "sentence_index": 6, "correct_answer": "接着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "离开家乡三年后，她接着搬到了上海。", "explanation": "这里应该用〈后来〉。“接着”表示紧接着，前后不能隔三年；隔了较长时间要用“后来”。"}, {"text": "因为他昨晚熬夜，接着今天很困。", "explanation": "这里应该用〈所以〉。“因为”已引出原因，“接着”只表示先后，不能表示结果。"}, {"text": "我们接着先讨论预算，再做决定。", "explanation": "这里表示开始，应该用〈首先〉。“接着”表示紧随前一动作，没有前文时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写完作业，接着的去玩。", "corrected_sentence": "他写完作业，接着去玩。", "error_description": "“接着”是副词，后面不能加“的”，应说“接着去玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他洗完澡，接着的吹干了头发。", "corrected_sentence": "他洗完澡，接着吹干了头发。", "error_description": "“接着”是副词，后面不能加“的”，应说“接着吹干了头发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
