INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88257, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "用某种菜肴或配料下饭、下酒，同时吃（喝）另一样东西。", "primary_collocate": null, "pronunciation": "jiù zhe", "ipa": "/tɕjoʊ̯˥˩ ʈʂə/", "syllable_count": 2, "sentences": [{"text": "他就着咸菜喝了一碗粥。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢就着茶吃点心。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷就着花生米喝酒。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就着热汤吃了两个馒头。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟就着牛奶吃面包。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们就着辣酱吃米饭。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就着豆腐乳吃了三个包子。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶就着小菜吃稀饭。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥就着啤酒吃烤肉。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就着泡菜吃面条。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "就着+下饭的菜或配料，一边吃这个一边吃那个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 咸 (Zipf 3.83), 一碗 (Zipf 3.81), 粥 (Zipf 3.83)']::text[], 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃的意思，咸菜是用来下饭的，“扔咸菜喝了一碗粥”说不通。"}, {"text": "就着", "is_correct": true, "explanation": "正确：“就着”表示用咸菜下饭，同时喝粥，符合句意。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带接受的人作宾语，“送咸菜喝粥”缺少送给的对象。"}, {"text": "掉", "is_correct": false, "explanation": "语义：“掉”表示脱落或丢失，咸菜不能“掉”进喝粥这个动作里，句意不通。"}], "explanations": {"扔": "语义：“扔”是丢弃的意思，咸菜是用来下饭的，“扔咸菜喝了一碗粥”说不通。", "就着": "正确：“就着”表示用咸菜下饭，同时喝粥，符合句意。", "送": "配价：“送”要带接受的人作宾语，“送咸菜喝粥”缺少送给的对象。", "掉": "语义：“掉”表示脱落或丢失，咸菜不能“掉”进喝粥这个动作里，句意不通。"}, "sentence_index": 0, "correct_answer": "就着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她就着心情吃了两个馒头。", "explanation": "这里不这么用。“就着”后面要接可以下饭的菜或配料，“心情”不是食物，不能下饭。"}, {"text": "我就着奶奶吃饭。", "explanation": "这里应该用〈陪着〉。就着表示用菜下饭，后面接的是食物，不能接人。"}, {"text": "他就着一场雨吃了两个馒头。", "explanation": "这里不这么用。“就着”表示用菜下饭，后面要接菜或配料，“一场雨”不能下饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砸", "is_correct": false, "explanation": "语义：“砸”是用力打击，豆腐乳不能被“砸”着吃包子，句意不通。"}, {"text": "赠", "is_correct": false, "explanation": "语域：“赠”是书面语，且要带送给的对象，口语句子里不能说“赠豆腐乳吃”。"}, {"text": "就着", "is_correct": true, "explanation": "正确：“就着”表示用豆腐乳下饭，同时吃包子，符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是跌落或扔下的意思，“摔豆腐乳吃包子”说不通。"}], "explanations": {"砸": "语义：“砸”是用力打击，豆腐乳不能被“砸”着吃包子，句意不通。", "赠": "语域：“赠”是书面语，且要带送给的对象，口语句子里不能说“赠豆腐乳吃”。", "就着": "正确：“就着”表示用豆腐乳下饭，同时吃包子，符合句意。", "摔": "语义：“摔”是跌落或扔下的意思，“摔豆腐乳吃包子”说不通。"}, "sentence_index": 6, "correct_answer": "就着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她就着地板吃了两个馒头。", "explanation": "这里不这么用。“就着”后面要接可以下饭的菜或配料，“地板”不能下饭，句子不成立。"}, {"text": "我就着沙发吃了一碗面。", "explanation": "这里不这么用。“就着”借助的是能下饭的食物，“沙发”不是食物，这个用法不成立。"}, {"text": "他就着书吃了三个包子。", "explanation": "这里不这么用。“就着”不能接“书”这类非食物的东西，表示下饭要接菜或配料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈就着着咸蛋吃稀饭。", "corrected_sentence": "妈妈就着咸蛋吃稀饭。", "error_description": "体标重复：“就着”是一个整体，“着”不能重复。“就着着咸蛋”错误，应改为“就着咸蛋吃稀饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸就着了咸菜吃馒头。", "corrected_sentence": "爸爸就着咸菜吃馒头。", "error_description": "“就着”后面直接接宾语，中间不能加“了”。“就着了咸菜”不成句，应去掉“了”，写成“就着咸菜吃馒头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
