INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88258, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "趁着；借助某种条件或物品，同时进行另一件事。", "primary_collocate": null, "pronunciation": "jiù zhe", "ipa": "/tɕjoʊ̯˥˩ ʈʂə/", "syllable_count": 2, "sentences": [{"text": "他就着灯光看书。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就着月光洗衣服。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就着窗外的光写信。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们就着路灯做作业。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸就着台灯看报纸。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们就着火光聊天。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就着手电筒的光找钥匙。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就着晨光画了一幅画。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们就着夕阳的光拍了照。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就着桌上的小灯修好了手表。", "target_word": "就着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "就着+光线等条件，借助它同时做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替别人，“替灯光看书”说不通，灯光不能代替人看书。"}, {"text": "沿着", "is_correct": false, "explanation": "搭配：“沿着”后面要接道路、路线，不接“灯光”，“沿着灯光看书”不成立。"}, {"text": "就着", "is_correct": true, "explanation": "正确：“就着”表示借助某种条件同时做另一件事，“就着灯光看书”符合句意。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示为了某人或某事，“为灯光看书”说不通，灯光不能成为看书的目的。"}], "explanations": {"替": "语义：“替”表示代替别人，“替灯光看书”说不通，灯光不能代替人看书。", "沿着": "搭配：“沿着”后面要接道路、路线，不接“灯光”，“沿着灯光看书”不成立。", "就着": "正确：“就着”表示借助某种条件同时做另一件事，“就着灯光看书”符合句意。", "为": "语义：“为”表示为了某人或某事，“为灯光看书”说不通，灯光不能成为看书的目的。"}, "sentence_index": 0, "correct_answer": "就着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我就着奶奶聊天，一直聊到深夜。", "explanation": "这里应该用〈陪着〉。就着借助的是灯光、食物这类具体条件，不能接人；陪人说话要用“陪着”。"}, {"text": "他就着年龄增长，记性越来越差。", "explanation": "这里应该用〈随着〉。就着借助眼前的灯光、食物等具体条件，不能表示事物随某种变化而发展；“随着年龄增长”要用“随着”。"}, {"text": "他就着努力考上了大学。", "explanation": "这里应该用〈凭借〉。就着只接灯光、食物这类具体条件，“努力”这样的抽象说法不能用“就着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向", "is_correct": false, "explanation": "语义：“向”表示朝某个方向，手电筒的光不是可以朝向去找钥匙的地方，句意不通。"}, {"text": "据", "is_correct": false, "explanation": "语域：“据”是书面语，表示依据，口语里说“找钥匙”不用“据”，句子不通。"}, {"text": "就着", "is_correct": true, "explanation": "正确：“就着”表示借助某种条件同时做另一件事，“就着手电筒的光找钥匙”符合句意。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替别人，“替手电筒的光找钥匙”说不通，光不能代替人找钥匙。"}], "explanations": {"向": "语义：“向”表示朝某个方向，手电筒的光不是可以朝向去找钥匙的地方，句意不通。", "据": "语域：“据”是书面语，表示依据，口语里说“找钥匙”不用“据”，句子不通。", "就着": "正确：“就着”表示借助某种条件同时做另一件事，“就着手电筒的光找钥匙”符合句意。", "替": "语义：“替”表示代替别人，“替手电筒的光找钥匙”说不通，光不能代替人找钥匙。"}, "sentence_index": 6, "correct_answer": "就着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他就着朋友的鼓励参加了比赛。", "explanation": "这里不这么用。“就着”后面接的是灯光、食物这类具体条件，“朋友的鼓励”是抽象的帮助，不能这样用。"}, {"text": "我们就着老师的帮忙修好了电脑。", "explanation": "这里不这么用。“就着”借助的是具体的条件，“老师的帮忙”是人的行为，不能作为“就着”的凭借。"}, {"text": "她就着经验解决了这道难题。", "explanation": "这里不这么用。“就着”不能接“经验”这样的抽象名词，它表示借助眼前的具体条件同时做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈就着的台灯织毛衣。", "corrected_sentence": "妈妈就着台灯织毛衣。", "error_description": "结构助词错误：“就着”是介词，后面应直接接名词，中间不能加“的”。应说“就着台灯织毛衣”，不说“就着的台灯织毛衣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹就着了台灯写字。", "corrected_sentence": "妹妹就着台灯写字。", "error_description": "体标错误：“就着”是固定的介词用法，后面不能加“了”。“就着了台灯写字”不成句，应去掉“了”，说“就着台灯写字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
