INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搜索是一点一点地找，想找出藏着的东西。", "primary_collocate": null, "pronunciation": "sōu suǒ", "ipa": "sou˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "警察在房子里仔细搜索，想找到那个小偷。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山上搜索了一整天。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察搜索了他的包，里面没有刀。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在草地上搜索，想找到藏着的骨头。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们搜索每一个房间，没有发现人。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边搜索那条不见了的船。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在屋里搜索了一遍，还是没找到钥匙。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援人员在倒了的楼里搜索有没有人。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员搜索每个人的行李。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起搜索了整个院子，才找到那只猫。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜索了", "label": "体标"}, {"form": "搜索着", "label": "体标"}, {"form": "搜索过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一点一点仔细地找，想找出藏着的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搜索", "is_correct": true, "explanation": "搜索：一点一点仔细地找，想找出藏着的人，符合句中的情境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与“想找到那个小偷”的目的矛盾。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”指搬运东西，不能用来形容在房子里找人。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”指用火焚烧，不能用“仔细”修饰在房子里找人的动作。"}], "explanations": {"搜索": "搜索：一点一点仔细地找，想找出藏着的人，符合句中的情境。", "欣赏": "语义：欣赏指赏识美好的事物，与“想找到那个小偷”的目的矛盾。", "搬": "搭配：“搬”指搬运东西，不能用来形容在房子里找人。", "烧": "搭配：“烧”指用火焚烧，不能用“仔细”修饰在房子里找人的动作。"}, "sentence_index": 0, "correct_answer": "搜索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家仔细搜索了细胞的变化。", "explanation": "这里应该用〈观察〉。搜索指仔细寻找藏着的人或东西，观察细胞的变化要用观察，不能说搜索。"}, {"text": "我把这份文件搜索到了纸上。", "explanation": "这里应该用〈打印〉。搜索是仔细寻找，不能用来说把文件印到纸上。"}, {"text": "我搜索到了她的温暖。", "explanation": "这里应该用〈感受〉。搜索是找，不能用来说感受到别人的温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搜索", "is_correct": true, "explanation": "搜索：在屋里一点一点仔细地找，符合“还是没找到钥匙”的句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与“还是没找到钥匙”的寻找过程无关，不合句意。"}, {"text": "摆", "is_correct": false, "explanation": "搭配：“摆”指摆放东西，不能用来说在屋里找钥匙的过程。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”指烹饪食物，不能用于屋子和钥匙。"}], "explanations": {"搜索": "搜索：在屋里一点一点仔细地找，符合“还是没找到钥匙”的句意。", "唱": "语义：唱歌与“还是没找到钥匙”的寻找过程无关，不合句意。", "摆": "搭配：“摆”指摆放东西，不能用来说在屋里找钥匙的过程。", "煮": "搭配：“煮”指烹饪食物，不能用于屋子和钥匙。"}, "sentence_index": 6, "correct_answer": "搜索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起搜索了这道菜，味道很好。", "explanation": "这里应该用〈品尝〉。搜索指仔细寻找藏着的人或东西，不能用来说吃菜的感受。"}, {"text": "他在厨房里搜索着这顿饭。", "explanation": "这里应该用〈享受〉。搜索是找，不能用来形容吃饭时的享受。"}, {"text": "我把孩子的玩具搜索到了床底下。", "explanation": "这里应该用〈放〉。搜索是仔细寻找，不能用来说把玩具放到床底下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把整个仓库搜索。", "corrected_sentence": "警察把整个仓库搜索了一遍。", "error_description": "“把”字句中的动词后通常要带补语或其他成分（如“一遍”），不能只说“把整个仓库搜索”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗在草地上搜索了着，尾巴一直摇个不停。", "corrected_sentence": "小狗在草地上搜索着，尾巴一直摇个不停。", "error_description": "“了”和“着”不能同时用在同一个动词后；表示动作正在进行只用“着”，应说“搜索着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
