INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在网上或用电脑、手机查找信息。", "primary_collocate": null, "pronunciation": "sōu suǒ", "ipa": "sou˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "我在网上搜索了很多旅游的信息。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里搜索你想看的电影。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机搜索附近的饭店。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们上网搜索这个词的意思。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我搜索了半天，也没找到那篇文章。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以搜索一下这位歌手的名字。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都在网上搜索便宜的机票。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站能搜索很多旧电影。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识这个字，就在手机上搜索了一下。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开手机，输入名字就能搜索到她的照片。", "target_word": "搜索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜索了", "label": "体标"}, {"form": "搜索着", "label": "体标"}, {"form": "搜索过", "label": "体标"}, {"form": "搜索引擎", "label": "复合"}], "register": "中性", "sense_fingerprint": "在网上或手机上查找信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搜索", "is_correct": true, "explanation": "搜索：在网上查找信息，符合句中“旅游的信息”的情境。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”多指种植，不能与“网上”和“旅游的信息”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”指清洗东西，不能用来说在网上处理信息。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与“搜”找信息的意思相反。"}], "explanations": {"搜索": "搜索：在网上查找信息，符合句中“旅游的信息”的情境。", "种": "搭配：“种”多指种植，不能与“网上”和“旅游的信息”搭配。", "洗": "搭配：“洗”指清洗东西，不能用来说在网上处理信息。", "扔": "语义：扔是丢弃，与“搜”找信息的意思相反。"}, "sentence_index": 0, "correct_answer": "搜索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家热烈搜索新同学。", "explanation": "这里应该用〈欢迎〉。搜索是仔细寻找，不能用来说热烈地迎接新同学。"}, {"text": "我把包裹搜索到了朋友那里。", "explanation": "这里应该用〈寄〉。搜索是找，不能用来说把包裹送到朋友那里。"}, {"text": "她每天早上精心搜索自己。", "explanation": "这里应该用〈打扮〉。搜索是找，不能用来说精心修饰自己的外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搜索", "is_correct": true, "explanation": "搜索：在网上查找信息，符合“每天在网上找便宜机票”的情境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”指吃东西，不能与“便宜的机票”搭配。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”指骑乘交通工具或动物，不能用于机票。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮指烹饪食物，与“在网上”和机票的情境不合。"}], "explanations": {"搜索": "搜索：在网上查找信息，符合“每天在网上找便宜机票”的情境。", "吃": "搭配：“吃”指吃东西，不能与“便宜的机票”搭配。", "骑": "搭配：“骑”指骑乘交通工具或动物，不能用于机票。", "煮": "语义：煮指烹饪食物，与“在网上”和机票的情境不合。"}, "sentence_index": 6, "correct_answer": "搜索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这张照片搜索到了网上。", "explanation": "这里应该用〈上传〉。搜索指查找信息，不能用来说把照片放到网上。"}, {"text": "他把文件搜索到了电脑里。", "explanation": "这里应该用〈保存〉。搜索是找，不能用来说把文件存进电脑。"}, {"text": "老师把这段话搜索到了黑板上。", "explanation": "这里应该用〈写〉。搜索指查找，不能用来说把字写在黑板上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在网上很搜索了不少景点的资料。", "corrected_sentence": "我在网上搜索了不少景点的资料。", "error_description": "“很”是程度副词，一般修饰形容词，不能放在动作动词“搜索”前面；应说“在网上搜索了……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在网上搜索了过两家酒店的价格。", "corrected_sentence": "我昨天在网上搜索了两家酒店的价格。", "error_description": "“了”和“过”不能同时用在同一个动词后，只保留“了”，应说“搜索了两家酒店的价格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
