INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依法取得执业资格,接受委托为当事人提供法律服务的专业人员。", "primary_collocate": null, "pronunciation": "lǜ shī", "ipa": "ly˥˩ ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "律师接受了这家公司的委托。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位律师为当事人写了一封信。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司请来的律师。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师在会议上讲了合同的问题。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做律师已经十年了。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师要先看合同，再给意见。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的律师正在检查这份合同。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想打官司，你要先找律师。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师说，这个合同有两个问题。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位律师为客户提供法律服务。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "律師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "律师|名词|依法执业、接受委托提供法律服务的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律师", "is_correct": true, "explanation": "正确：「律师」是依法执业、接受委托的专业人员，与「接受了委托」相符。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「接受委托」需要能接受的人或机构作主语，「桌子」不能。"}, {"text": "教室", "is_correct": false, "explanation": "语义：「教室」是场所，不是接受委托的人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是物品，不能接受委托。"}], "explanations": {"律师": "正确：「律师」是依法执业、接受委托的专业人员，与「接受了委托」相符。", "桌子": "配价：「接受委托」需要能接受的人或机构作主语，「桌子」不能。", "教室": "语义：「教室」是场所，不是接受委托的人。", "窗户": "语义：「窗户」是物品，不能接受委托。"}, "sentence_index": 0, "correct_answer": "律师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "律师依法提起了公诉。", "explanation": "这里应该用〈检察官〉。提起公诉是检察机关的职权，律师不能提起公诉。"}, {"text": "律师判了这起官司，当事人很满意。", "explanation": "这里应该用〈法官〉。律师替当事人辩护，不负责判案。"}, {"text": "律师给病人开了三天的药。", "explanation": "这里应该用〈医生〉。律师不开药，给病人开药的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "律师", "is_correct": true, "explanation": "正确：「公司的律师」指公司聘请的法律人员，正在检查合同，句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作与检查合同无关，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房」是场所，不能检查合同。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：「检查」需要人作主语，「钢琴」不能。"}], "explanations": {"律师": "正确：「公司的律师」指公司聘请的法律人员，正在检查合同，句意相符。", "厨师": "语义：厨师的工作与检查合同无关，句子不通。", "厨房": "语义：「厨房」是场所，不能检查合同。", "钢琴": "配价：「检查」需要人作主语，「钢琴」不能。"}, "sentence_index": 6, "correct_answer": "律师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "律师每天在饭店里炒菜。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作，律师不做饭。"}, {"text": "律师带队训练了一个星期。", "explanation": "这里应该用〈教练〉。律师不带队训练运动员，带队训练的是教练。"}, {"text": "律师在路口指挥交通。", "explanation": "这里应该用〈警察〉。律师不指挥交通，指挥交通的是警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们请了三位律师们来处理这件事。", "corrected_sentence": "我们请了三位律师来处理这件事。", "error_description": "「律师们」不能与数词连用。「三位」后应直接用「律师」，写成「三位律师们」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他请了一只律师，帮公司看合同。", "corrected_sentence": "他请了一位律师，帮公司看合同。", "error_description": "“一只律师”错误，“只”用于动物等，指人的“律师”应用“位”（或“个”）。应改为“一位律师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
