INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有请是客气地叫一个人出来或者进来。", "primary_collocate": null, "pronunciation": "yǒu qǐng", "ipa": "joʊ˨˩˦ t͡ɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "观众朋友们，有请今天的主持人。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接下来，有请市长上台讲话。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有请下一位客人进来。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外的客人等了很久，经理说：“有请。”", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎大家，有请这对新人出场。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在有请张老师为我们唱一首歌。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室里，秘书对外面的人说：“有请。”", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位来宾，有请校长讲几句话。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下面有请第一位选手上场。", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人敲门，老板笑着说：“有请！”", "target_word": "有请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌", "sense_fingerprint": "客气地请人出场或进来的礼貌说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有请", "is_correct": true, "explanation": "有请：客气地请人出场，符合主持人请嘉宾上台的语境。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”只表示看到，不能用来请主持人出场。"}, {"text": "瞅", "is_correct": false, "explanation": "语域：“瞅”口语且随便，不适合对观众致辞的正式场合。"}, {"text": "采访", "is_correct": false, "explanation": "语义：“采访”是向人提问、了解情况，不是请人出场。"}], "explanations": {"有请": "有请：客气地请人出场，符合主持人请嘉宾上台的语境。", "看见": "语义：“看见”只表示看到，不能用来请主持人出场。", "瞅": "语域：“瞅”口语且随便，不适合对观众致辞的正式场合。", "采访": "语义：“采访”是向人提问、了解情况，不是请人出场。"}, "sentence_index": 0, "correct_answer": "有请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我想有请朋友们来家里吃饭。", "explanation": "这里应该用〈请〉。有请是正式的客套话，只用于请人出场或进入；请朋友来家里吃饭要用请。"}, {"text": "我有请你明天帮我买菜。", "explanation": "这里应该用〈请〉。有请多用于请人出场或进入，请人帮忙买菜要说请。"}, {"text": "我在厨房有请弟弟来帮忙。", "explanation": "这里应该用〈叫〉。有请过于正式，在厨房叫弟弟过来帮忙应说叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有请", "is_correct": true, "explanation": "有请：秘书请外面的客人进来，符合客套的语境。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”是让人离开，与请人进入的意思相反。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”是让人离开，与请人进来的意思相反，语气也很粗鲁。"}, {"text": "等", "is_correct": false, "explanation": "语义：“等”表示让人稍候，不是请人进入。"}], "explanations": {"有请": "有请：秘书请外面的客人进来，符合客套的语境。", "出去": "语义：“出去”是让人离开，与请人进入的意思相反。", "走开": "语义：“走开”是让人离开，与请人进来的意思相反，语气也很粗鲁。", "等": "语义：“等”表示让人稍候，不是请人进入。"}, "sentence_index": 6, "correct_answer": "有请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员走过来，对我们说：“有请点菜。”", "explanation": "这里应该用〈请〉。有请只用于请人出场或进入，服务员请客人点菜要说请。"}, {"text": "周末我们在家有请亲戚，大家很开心。", "explanation": "这里应该用〈招待〉。有请是请人出场的客套话，在家款待亲戚要用招待。"}, {"text": "妈妈站在窗口有请孩子回家。", "explanation": "这里应该用〈叫〉。有请是请人出场或进入的客套话，妈妈在窗口叫孩子回家应说叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "观众朋友们，有请了今天的主持人上台。", "corrected_sentence": "观众朋友们，有请今天的主持人上台。", "error_description": "错误：“有请了”多了一个“了”。“有请”是客套的请人出场用语，后面不加“了”。正确：“有请今天的主持人上台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家安静，有请了校长上台。", "corrected_sentence": "请大家安静，有请校长上台。", "error_description": "错误：“有请了”多了一个“了”。“有请”是固定的客套说法，后面不加“了”。正确：“有请校长上台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
