INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "战斗就是两边的人拿着东西,互相打,想打赢对方。", "primary_collocate": null, "pronunciation": "zhàn dòu", "ipa": "ʈʂan˥˩ tou˥˩", "syllable_count": 2, "sentences": [{"text": "两队士兵在山上战斗了一整天。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了保护家人，勇敢地战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们拿着枪，在河边战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个骑士拿着长剑，在城门前战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们已经战斗了三天三夜。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雨中战斗，没有人后退。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护城市，大家一起战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，我们必须战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里，我们和怪物战斗了很久。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵说，他曾经在这里战斗过。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战斗了", "label": "完成体"}, {"form": "战斗过", "label": "经历体"}, {"form": "战斗着", "label": "进行体"}], "register": "通用", "sense_fingerprint": "双方拿着武器互相打，想打赢对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：战斗指双方持械对打，符合“两队士兵”的句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：山上没有水，士兵不能在山上游泳。"}, {"text": "进入", "is_correct": false, "explanation": "配价：“进入”后要带处所宾语，不能直接跟“一整天”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性的事件，不能持续一整天。"}], "explanations": {"战斗": "正确：战斗指双方持械对打，符合“两队士兵”的句意。", "游泳": "语义：山上没有水，士兵不能在山上游泳。", "进入": "配价：“进入”后要带处所宾语，不能直接跟“一整天”。", "出生": "语义：出生是一次性的事件，不能持续一整天。"}, "sentence_index": 0, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个孩子在公园里跑步比赛，战斗得很激烈。", "explanation": "这里应该用〈比赛〉。战斗指双方拿着东西互相打，跑步比赛不是对打，不能用战斗。"}, {"text": "他坐在沙发上战斗了一下午，看完了一本书。", "explanation": "这里不能用“战斗”。战斗指双方对打、想打赢对方，安静地看书不是对抗，应说〈看书〉。"}, {"text": "两个小朋友在教室里战斗了一下午，都在认真地画画。", "explanation": "这里应该用〈画画〉。战斗指双方拿着东西互相打，认真画画不是对打，不能用战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：为了保护城市，大家一起与敌人对抗，战斗合乎句意。"}, {"text": "投降", "is_correct": false, "explanation": "语义：投降与“为了保护城市”的目的正相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：为了保护城市，大家不会一起去睡觉。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“为了保护城市”后接的行动应是防守或抗击，“散步”不能与之搭配。"}], "explanations": {"战斗": "正确：为了保护城市，大家一起与敌人对抗，战斗合乎句意。", "投降": "语义：投降与“为了保护城市”的目的正相反。", "睡觉": "语义：为了保护城市，大家不会一起去睡觉。", "散步": "搭配：“为了保护城市”后接的行动应是防守或抗击，“散步”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人在屋里战斗了很久，一直在互相夸奖。", "explanation": "这里不能用“战斗”。战斗指双方拿着东西互相打，互相夸奖不是对打。"}, {"text": "我们在图书馆里战斗，安静地看书。", "explanation": "这里不能用“战斗”。战斗指双方对打、想打赢对方，安静看书是另一种活动，不是对抗。"}, {"text": "他们在咖啡馆里战斗，聊得很开心。", "explanation": "这里应该用〈聊天〉。战斗指武力对打，聊天不能说战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在城墙下战斗了过一个晚上。", "corrected_sentence": "他们在城墙下战斗了一个晚上。", "error_description": "错误：动词后的“了”和“过”不能同时使用。正确：“他们在城墙下战斗了一个晚上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们在河边战斗的很激烈。", "corrected_sentence": "士兵们在河边战斗得很激烈。", "error_description": "错误：战斗后的补语标记应用结构助词“得”，不能用“的”。正确：“士兵们在河边战斗得很激烈。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
