INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "朝是（房屋、门窗等）正面对着某个方向。", "primary_collocate": null, "pronunciation": "cháo", "ipa": "ʈʂʰɑʊ̯˧˥", "syllable_count": 1, "sentences": [{"text": "我家的窗户朝南。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这间房子朝东，早上很亮。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的教室朝北，冬天很冷。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间朝南，冬天不冷。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他家的阳台朝海，风景很好。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的大门朝西。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这套房子朝南，所以很亮。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的房间朝东，早上有太阳。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐厅的窗户朝着公园。", "target_word": "朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子朝西，下午太阳很大。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝着", "label": "带体标形式"}, {"form": "朝向", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动词：房屋、门窗等朝+方位词，表示正面对着某个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '314b788a-db43-4be2-9cd0-4c586b32fd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确答案：朝，指房屋、门窗等正面对着某个方向。"}, {"text": "勺", "is_correct": false, "explanation": "sháo 与 cháo 的声母不同（sh 与 ch），意思是勺子。"}, {"text": "着", "is_correct": false, "explanation": "zháo 与 cháo 的声母不同（zh 与 ch），意思是着急。"}, {"text": "长", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），意思是长短的长。"}, {"text": "抄", "is_correct": false, "explanation": "chāo（第一声）与 cháo 的声调不同，意思是抄写。"}], "explanations": {"朝": "正确答案：朝，指房屋、门窗等正面对着某个方向。", "勺": "sháo 与 cháo 的声母不同（sh 与 ch），意思是勺子。", "着": "zháo 与 cháo 的声母不同（zh 与 ch），意思是着急。", "长": "cháng 与 cháo 的韵母不同（ang 与 ao），意思是长短的长。", "抄": "chāo（第一声）与 cháo 的声调不同，意思是抄写。"}, "sentence_index": null, "correct_answer": "朝"}, "level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确：“朝南”表示窗户面向南方，符合语境。"}, {"text": "开", "is_correct": false, "explanation": "语义：“开”是打开，“开南”不能表示窗户的朝向。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”是关闭，与窗户的朝向无关。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”要接具体的物体，“挂南”不能成立。"}], "explanations": {"朝": "正确：“朝南”表示窗户面向南方，符合语境。", "开": "语义：“开”是打开，“开南”不能表示窗户的朝向。", "关": "语义：“关”是关闭，与窗户的朝向无关。", "挂": "配价：“挂”要接具体的物体，“挂南”不能成立。"}, "sentence_index": 0, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家朝学校很近，走路五分钟就到。", "explanation": "这里应该用〈离〉。“离”表示两地之间的距离，“朝”只表示动作的方向，不能表示距离。"}, {"text": "他朝我很好，常常帮我补习功课。", "explanation": "这里应该用〈对〉。“对”可以表示对待，如“对我很好”，“朝”不能表示对人的态度。"}, {"text": "他朝早上八点一直工作到下午五点。", "explanation": "这里应该用〈从〉。“从……到……”表示时间的起点和终点，“朝”只表示方向，不能引出时间起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确答案：朝，指房屋、门窗等正面对着某个方向。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo（第三声）与 cháo 的声调不同，意思是翻炒。"}, {"text": "超", "is_correct": false, "explanation": "chāo（第一声）与 cháo 的声调不同，意思是超过。"}, {"text": "槽", "is_correct": false, "explanation": "cáo 与 cháo 的声母不同（c 与 ch），意思是水槽。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 cháo 的韵母不同（ai 与 ao），意思是柴火。"}], "explanations": {"朝": "正确答案：朝，指房屋、门窗等正面对着某个方向。", "炒": "chǎo（第三声）与 cháo 的声调不同，意思是翻炒。", "超": "chāo（第一声）与 cháo 的声调不同，意思是超过。", "槽": "cáo 与 cháo 的声母不同（c 与 ch），意思是水槽。", "柴": "chái 与 cháo 的韵母不同（ai 与 ao），意思是柴火。"}, "sentence_index": null, "correct_answer": "朝"}, "level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确：“朝南”表示房子面向南方，符合语境。"}, {"text": "住", "is_correct": false, "explanation": "语义：“住”是居住，不表示方位。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是购买，不能用来表示朝向。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”不和“南”搭配来表示朝向。"}], "explanations": {"朝": "正确：“朝南”表示房子面向南方，符合语境。", "住": "语义：“住”是居住，不表示方位。", "买": "语义：“买”是购买，不能用来表示朝向。", "装": "搭配：“装”不和“南”搭配来表示朝向。"}, "sentence_index": 6, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈朝我做了午饭，我很感动。", "explanation": "这里应该用〈为〉。“为”表示为了某人做某事，“朝”不能这样用，应说“为我做午饭”。"}, {"text": "她朝我卖了一本旧书，价格很便宜。", "explanation": "这里应该用〈给〉。“卖给”引出买的人，“朝”不能引出买者，应说“卖给我”。"}, {"text": "她朝大家擦了黑板。", "explanation": "这里应该用〈替〉。“替”表示替别人做事，“朝”不能这样用，应说“替大家擦黑板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座房子朝了北，冬天有点冷。", "corrected_sentence": "这座房子朝北，冬天有点冷。", "error_description": "错误在“了”：“朝北”表示房屋的朝向，是稳定的状态，不能加“了”，应说“朝北”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的阳台西朝，傍晚很暖和。", "corrected_sentence": "我们的阳台朝西，傍晚很暖和。", "error_description": "错误在语序：方位词“西”应放在“朝”后面，应说“朝西”，不能说“西朝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
