INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "舍弃原有的权利、主张或打算,不再继续。", "primary_collocate": null, "pronunciation": "fàng qì", "ipa": "fɑŋ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他放弃了去国外工作的打算。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为生病，她放弃了比赛。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要放弃自己的想法。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了留在大城市的机会。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李放弃了考研究生的计划。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司放弃了原来的方案。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能放弃自己的权利。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，还是放弃了这笔钱。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家放弃了爬山的计划。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放弃过出国的机会，现在有点后悔。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放弃了", "label": "体标"}, {"form": "放弃过", "label": "体标"}], "register": "中性", "sense_fingerprint": "舍弃原有的权利、想法或计划，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指舍弃打算，与“去国外工作的打算”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“打算”搭配，句子读不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能与“打算”搭配，句子读不通。"}, {"text": "爬", "is_correct": false, "explanation": "语义：“爬”的对象是高处或地面，与“打算”不相合。"}], "explanations": {"放弃": "正确：“放弃”指舍弃打算，与“去国外工作的打算”相合。", "吃": "语义：“吃”不能与“打算”搭配，句子读不通。", "喝": "语义：“喝”不能与“打算”搭配，句子读不通。", "爬": "语义：“爬”的对象是高处或地面，与“打算”不相合。"}, "sentence_index": 0, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把门口的旧椅子放弃了。", "explanation": "这里应该用〈扔掉〉。放弃指舍弃权利、想法或计划，不能用来说丢掉具体的物件。"}, {"text": "妈妈把发霉的饼干放弃了。", "explanation": "这里应该用〈丢〉。放弃用于权利、想法或计划，不能用来说丢弃食物。"}, {"text": "他放弃了春天，去了南方。", "explanation": "这里是把放弃用成了“离开”的意思，但放弃指舍弃权利、主张或打算，不能用于一个季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指舍弃权利，与“我们不能…自己的权利”的语境相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用在“权利”上。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能与“权利”搭配，句子读不通。"}, {"text": "炒", "is_correct": false, "explanation": "语义：“炒”的对象是食物，不能用在“权利”上。"}], "explanations": {"放弃": "正确：“放弃”指舍弃权利，与“我们不能…自己的权利”的语境相合。", "煮": "语义：“煮”的对象是食物，不能用在“权利”上。", "唱": "语义：“唱”不能与“权利”搭配，句子读不通。", "炒": "语义：“炒”的对象是食物，不能用在“权利”上。"}, "sentence_index": 6, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧车放弃了，换了辆新车。", "explanation": "这里应该用〈卖掉〉。放弃指舍弃权利或计划，不用于卖东西。"}, {"text": "哥哥放弃了那只打碎的花瓶，准备去买新的。", "explanation": "这里应该用〈处理掉〉。放弃指舍弃权利、主张或打算，不用于处理打碎的花瓶。"}, {"text": "姐姐放弃了那张旧床垫，准备换一张新的。", "explanation": "这里应该用〈换掉〉。放弃指舍弃权利、主张或打算，不用于更换家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为家里有事，把放弃了这次出差。", "corrected_sentence": "他因为家里有事，放弃了这次出差。", "error_description": "把字句错误：“放弃”后直接带宾语，前面不能加“把”。应改为“放弃了这次出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划很难，但我不会放弃了。", "corrected_sentence": "这个计划很难，但我不会放弃。", "error_description": "时态错误：“不会放弃”是表示将来或意愿的否定，后面不能加“了”。应改为“我不会放弃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
