INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校里的整个场地。", "primary_collocate": null, "pronunciation": "xiào yuán", "ipa": "ɕjɑʊ̯˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们的校园很大。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园里有一个小湖。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常在校园里跑步。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个校园一共有五个门。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学今天参观了校园。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园里不能骑快车。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园的每个地方都很干净。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从校园的东门走进去。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在校园里走了一个小时。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的校园在山上。", "target_word": "校园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "校園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校围墙以内的整片场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "校园", "is_correct": true, "explanation": "正确答案。“校园”指学校里的整个场地。"}, {"text": "教员", "is_correct": false, "explanation": "jiào（第四声）与 xiào（第四声）声母不同（j 与 x），意思是教员，不是学校的场地。"}, {"text": "小院", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是小的院子。"}, {"text": "小园", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小的园子。"}, {"text": "笑语", "is_correct": false, "explanation": "xiàoyǔ 与 xiàoyuán 前一音节相同，后面读音不同，意思是说笑的话。"}], "explanations": {"校园": "正确答案。“校园”指学校里的整个场地。", "教员": "jiào（第四声）与 xiào（第四声）声母不同（j 与 x），意思是教员，不是学校的场地。", "小院": "xiǎo（第三声）与 xiào（第四声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是小的院子。", "小园": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小的园子。", "笑语": "xiàoyǔ 与 xiàoyuán 前一音节相同，后面读音不同，意思是说笑的话。"}, "sentence_index": null, "correct_answer": "校园"}, "level_3": {"options": [{"text": "校园", "is_correct": true, "explanation": "正确。“校园”指学校里的整个场地，与“很大”搭配，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”说“长”或“短”，不说“很大”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是有大小的场所，“我们的语言很大”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”说“长”，不说“很大”。"}], "explanations": {"校园": "正确。“校园”指学校里的整个场地，与“很大”搭配，符合句意。", "时间": "搭配：“时间”说“长”或“短”，不说“很大”。", "语言": "语义：“语言”不是有大小的场所，“我们的语言很大”说不通。", "寿命": "搭配：“寿命”说“长”，不说“很大”。"}, "sentence_index": 0, "correct_answer": "校园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有一间很大的校园。", "explanation": "这里应该用〈座〉。“间”用于房间、房屋，不能用来数“校园”这样的大片场地。"}, {"text": "我把作业放在校园上。", "explanation": "这里应该用〈桌子〉。“校园”是大片场地，不能像桌子那样放东西。"}, {"text": "这个村子有一只校园。", "explanation": "这里应该用〈座〉。“只”多用于动物或成对器物中的一个，不能用来数“校园”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校园", "is_correct": true, "explanation": "正确。“校园”指学校里的整个场地，符合“每个地方都很干净”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以整体“干净”的场所，“天气的每个地方都很干净”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不说“干净”，不能说“心情的每个地方都很干净”。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“收入”不说“干净”，句子不成立。"}], "explanations": {"校园": "正确。“校园”指学校里的整个场地，符合“每个地方都很干净”的语境。", "天气": "语义：“天气”不是可以整体“干净”的场所，“天气的每个地方都很干净”说不通。", "心情": "搭配：“心情”不说“干净”，不能说“心情的每个地方都很干净”。", "收入": "搭配：“收入”不说“干净”，句子不成立。"}, "sentence_index": 6, "correct_answer": "校园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校是一栋很大的校园。", "explanation": "这里应该用〈座〉。“栋”数的是单栋建筑，“校园”是大片场地，不能用“栋”来数。"}, {"text": "我们学校的校园一共有三层。", "explanation": "这里应该用〈校舍〉。“层”指楼房的楼层，“校园”是场地，没有楼层。"}, {"text": "这所学校的校园一共有两本。", "explanation": "这里应该用〈片〉。“本”用于书册，不能用来数“校园”这样的大片场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校有一扇很大的校园。", "corrected_sentence": "这所学校有一座很大的校园。", "error_description": "量词用错了。“扇”用于门窗，不能用来数“校园”这样的大片场地，应当用“座”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学有一本很美的校园。", "corrected_sentence": "这所大学有一座很美的校园。", "error_description": "量词用错了。“本”用于书册，不能用来数“校园”这样的大片场地，应当用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
