INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88273, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事实根据是真的发生过的事，我们说话时靠它来证明。", "primary_collocate": null, "pronunciation": "shì shí gēn jù", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ kən˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "他说的话没有事实根据，大家都不信。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章要有事实根据，不能随便说。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样说有什么事实根据吗？", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我这个消息有没有事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察要找到事实根据，才能说他有错。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事没有事实根据，只是人们编的。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你拿出事实根据，来证明你说的话。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我不对，可是她没有事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写的每句话都要有事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法很有事实根据，所以我们都同意。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "事實根據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "真实发生过、可用来证明说法的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实根据", "is_correct": true, "explanation": "正确：事实根据指可以用来证明说法的真实情况，与“没有……，大家都不信”的语境相符。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部神情，不能用来说明话的可信程度，“没有脸色”的话说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的视觉特征，与说话是否可信无关，“话没有颜色”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是买卖的标准，不能用来衡量说话的可靠性，“话没有价格”说不通。"}], "explanations": {"事实根据": "正确：事实根据指可以用来证明说法的真实情况，与“没有……，大家都不信”的语境相符。", "脸色": "体貌：脸色指面部神情，不能用来说明话的可信程度，“没有脸色”的话说不通。", "颜色": "语义：颜色是事物的视觉特征，与说话是否可信无关，“话没有颜色”不成立。", "价格": "语义：价格是买卖的标准，不能用来衡量说话的可靠性，“话没有价格”说不通。"}, "sentence_index": 0, "correct_answer": "事实根据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份事实根据是医生开的，可以请假。", "explanation": "这里应该用〈证明〉。事实根据指判断依据的真实情况，不是医生开具的书面证件。"}, {"text": "我们学校的事实根据在城东，离我家很近。", "explanation": "这里应该用〈地方〉。事实根据指作为判断依据的真实情况，不指地方；“在城东”说的是位置。"}, {"text": "他提出了一朵事实根据，证明自己没有说谎。", "explanation": "这里量词用错了。〈朵〉用于花朵，事实根据是抽象名词，应该用〈个〉或〈份〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实根据", "is_correct": true, "explanation": "正确：事实根据是可以拿出来证明说话内容的真实依据，与“拿出……来证明”的搭配相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以拿出来作证明的材料，“拿出天气来证明”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官感受，不能拿出来证明说话的内容，句子不成立。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌是外形特征，不能拿出来作为证明说话内容的依据。"}], "explanations": {"事实根据": "正确：事实根据是可以拿出来证明说话内容的真实依据，与“拿出……来证明”的搭配相符。", "天气": "语义：天气不是可以拿出来作证明的材料，“拿出天气来证明”说不通。", "味道": "语义：味道是感官感受，不能拿出来证明说话的内容，句子不成立。", "相貌": "体貌：相貌是外形特征，不能拿出来作为证明说话内容的依据。"}, "sentence_index": 6, "correct_answer": "事实根据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位事实根据在法庭上作了证，说出了真相。", "explanation": "这里应该用〈证人〉。事实根据指作为依据的真实情况，不是人，不能用“位”计量，也不能“作证”。"}, {"text": "他把事实根据挂在墙上，每天都看。", "explanation": "这里应该用〈照片〉。事实根据是判断依据的真实情况，不是可以挂在墙上的实物。"}, {"text": "这份报告里有一座事实根据，很有说服力。", "explanation": "这里量词用错了。〈座〉用于山、楼房等大型物体，事实根据应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们找到了一把事实根据，可以证明他的话是真的。", "corrected_sentence": "我们找到了一个事实根据，可以证明他的话是真的。", "error_description": "错误：量词“把”；正确：“个”。“把”用于有柄的器具，事实根据是抽象名词，应该用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的话有一座事实根据，我们可以相信。", "corrected_sentence": "他的话有一个事实根据，我们可以相信。", "error_description": "错误：量词“座”；正确：“个”。“座”用于山、楼等大型物体，不能用来计量事实根据。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
