INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "作为判断或结论依据的真实情况。", "primary_collocate": null, "pronunciation": "shì shí gēn jù", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ kən˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "法官做决定，必须先看事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的结论有充分的事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个判断缺少事实根据，不能让人放心。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要有事实根据，才能说你生病了。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的批评完全没有事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定这件事时，掌握了很多事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有事实根据的话，我们不应该相信。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家做出结论前，先去找事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里的每个结论都有事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你做这个判断的事实根据。", "target_word": "事实根据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "事實根據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "判断或结论所依靠的真实情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实根据", "is_correct": true, "explanation": "正确：事实根据指作为判断依据的真实情况，与“法官做决定必须先看”的语境相符。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步与法官做决定的依据无关，“先看脚步”与语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高与法官做决定的依据无关，不能作为“先看”的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能作为判断案件的依据，“先看颜色”与做决定的语境不符。"}], "explanations": {"事实根据": "正确：事实根据指作为判断依据的真实情况，与“法官做决定必须先看”的语境相符。", "脚步": "语义：脚步与法官做决定的依据无关，“先看脚步”与语境不符。", "身高": "语义：身高与法官做决定的依据无关，不能作为“先看”的对象。", "颜色": "语义：颜色不能作为判断案件的依据，“先看颜色”与做决定的语境不符。"}, "sentence_index": 0, "correct_answer": "事实根据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给我做了事实根据，没有问题。", "explanation": "这里应该用〈检查〉。“做”后面接的是动作类名词，事实根据是判断依据，不能与“做”搭配。"}, {"text": "他拿出了一把事实根据，说明自己没错。", "explanation": "这里量词用错了。〈把〉用于有柄的器具，事实根据是抽象名词，应该用〈个〉或〈份〉。"}, {"text": "她今天穿了一件很漂亮的事实根据。", "explanation": "这里应该用〈衣服〉。事实根据指判断依据的真实情况，不指衣物，不能用“穿”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实根据", "is_correct": true, "explanation": "正确：事实根据是可以证明判断的真实依据，与“没有……的话，我们不应该相信”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能作为判断话语是否可信的依据，“没有体重的话”说不通。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌是外形特征，与话语是否可信无关，“没有相貌的话”不成立。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是气味特征，不能用来说明话语的可靠程度，句子语义不通。"}], "explanations": {"事实根据": "正确：事实根据是可以证明判断的真实依据，与“没有……的话，我们不应该相信”的语境相符。", "体重": "语义：体重不能作为判断话语是否可信的依据，“没有体重的话”说不通。", "相貌": "体貌：相貌是外形特征，与话语是否可信无关，“没有相貌的话”不成立。", "香味": "语义：香味是气味特征，不能用来说明话语的可靠程度，句子语义不通。"}, "sentence_index": 6, "correct_answer": "事实根据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的事实根据是三。", "explanation": "这里应该用〈答案〉。事实根据是判断的依据，不是题目的计算结果。"}, {"text": "他每天早上都喝一杯事实根据，身体很好。", "explanation": "这里应该用〈牛奶〉。事实根据指判断依据的真实情况，不是可以喝的东西。"}, {"text": "他说出了一颗事实根据，让大家都很惊讶。", "explanation": "这里量词用错了。〈颗〉用于小而圆的东西，事实根据是抽象名词，应该用〈个〉或〈份〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官做决定前，必须先找到一颗事实根据。", "corrected_sentence": "法官做决定前，必须先找到事实根据。", "error_description": "错误：多了量词“颗”；正确：去掉“一颗”。“颗”用于小而圆的东西，事实根据是抽象名词，不用这个量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有一头事实根据，我们不能相信你。", "corrected_sentence": "没有事实根据，我们不能相信你。", "error_description": "错误：多了量词“头”；正确：去掉“一头”。“头”用于牛羊等动物，事实根据不用这个量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
