INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88275, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "日来就是这几天以来。", "primary_collocate": null, "pronunciation": "rì lái", "ipa": "ʐɻ̩˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "日来天气很冷，大家都穿上了厚衣服。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来他一直很忙，没有时间休息。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来下了几场雨，路上很湿。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来我身体不太好，常常咳嗽。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来公司的客人很多，大家都很累。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来天天加班，我回家很晚。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来他心情不错，总是笑着。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来我读了不少书，学到很多东西。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来物价涨了一点，买菜贵了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来孩子们都在家里复习，没有出去玩。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日來", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "日来:副词,这几天以来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88275, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。日来（rì lái）：副词，指近几天以来。"}, {"text": "历来", "is_correct": false, "explanation": "历来（lì lái）与日来只差声母（r 与 l），意思是“一向，向来”。"}, {"text": "寄来", "is_correct": false, "explanation": "寄来（jì lái）与日来只差声母（r 与 j），意思是“寄到这里”。"}, {"text": "递来", "is_correct": false, "explanation": "递来（dì lái）与日来只差声母（r 与 d），意思是“传递过来”。"}, {"text": "日历", "is_correct": false, "explanation": "日历（rì lì）与日来的韵母和声调都不同（ai 与 i，第二声与第四声），意思是“日历”。"}], "explanations": {"日来": "正确答案。日来（rì lái）：副词，指近几天以来。", "历来": "历来（lì lái）与日来只差声母（r 与 l），意思是“一向，向来”。", "寄来": "寄来（jì lái）与日来只差声母（r 与 j），意思是“寄到这里”。", "递来": "递来（dì lái）与日来只差声母（r 与 d），意思是“传递过来”。", "日历": "日历（rì lì）与日来的韵母和声调都不同（ai 与 i，第二声与第四声），意思是“日历”。"}, "sentence_index": null, "correct_answer": "日来"}, "level_3": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。“日来天气很冷”说的是这几天以来的情况，与副词义一致。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“这几天以来”的持续意义不合。"}, {"text": "特意", "is_correct": false, "explanation": "搭配：“特意”修饰有意的行为，不能修饰“天气很冷”。"}, {"text": "却", "is_correct": false, "explanation": "语法：“却”是转折副词，不能用在句首，句中也没有转折关系，“却天气很冷”不成立。"}], "explanations": {"日来": "正确答案。“日来天气很冷”说的是这几天以来的情况，与副词义一致。", "立刻": "语义：“立刻”表示马上发生，与“这几天以来”的持续意义不合。", "特意": "搭配：“特意”修饰有意的行为，不能修饰“天气很冷”。", "却": "语法：“却”是转折副词，不能用在句首，句中也没有转折关系，“却天气很冷”不成立。"}, "sentence_index": 0, "correct_answer": "日来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日来你会明白我的苦心。", "explanation": "这里应该用〈日后〉。日后指将来，日来指过去到现在的近几天，不能用于说将来的事。"}, {"text": "日来去年我去过北京，很喜欢那里。", "explanation": "这里应该用〈以前〉。日来只指近几天，不能用来说一年前的经历，说较早的事要用以前。"}, {"text": "我日来一定要去北京出差。", "explanation": "这里应该用〈以后〉。日来只指过去到现在的几天，不能用来表示打算或将来的计划，说将来的安排要用以后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。“日来他心情不错，总是笑着”说的是近几天的状态，与“总是笑着”一致。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”指突然发生，与“总是笑着”的持续状态矛盾。"}, {"text": "特地", "is_correct": false, "explanation": "搭配：“特地”修饰有意的行为，不能修饰“心情不错”。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上发生，与“总是笑着”的持续状态不合。"}], "explanations": {"日来": "正确答案。“日来他心情不错，总是笑着”说的是近几天的状态，与“总是笑着”一致。", "猛然": "语义：“猛然”指突然发生，与“总是笑着”的持续状态矛盾。", "特地": "搭配：“特地”修饰有意的行为，不能修饰“心情不错”。", "立即": "语义：“立即”表示马上发生，与“总是笑着”的持续状态不合。"}, "sentence_index": 6, "correct_answer": "日来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他日来在这里当过兵。", "explanation": "这里应该用〈早年〉。日来只指近几天，不能用来说很久以前的经历，说早年的事要用早年。"}, {"text": "日来我小时候很胆小。", "explanation": "这里应该用〈小时候〉。日来只指近几天，不能用来说童年的性格，说童年要用小时候。"}, {"text": "日来他在这里出生。", "explanation": "这里应该用〈多年前〉。日来只指近几天，不能用来说出生这样久远的事，说很久以前要用多年前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很日来城里风很大，树叶都落了。", "corrected_sentence": "日来城里风很大，树叶都落了。", "error_description": "“日来”是副词，前面不能加“很”等程度词；“很日来”不成立，应说“日来城里风很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日来天气将变冷了，大家都换上了棉衣。", "corrected_sentence": "日来天气变冷了，大家都换上了棉衣。", "error_description": "“日来”指过去几天到现在，不能和表示将来的“将”连用，应去掉“将”，说“日来天气变冷了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
