INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88276, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "近几天以来。", "primary_collocate": null, "pronunciation": "rì lái", "ipa": "ʐɻ̩˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "日来我睡得不好，白天没有精神。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来他一直在写报告，今天终于写完了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来城里很热闹，到处都是游客。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来雨下个不停，河水涨高了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来妈妈总是很高兴，因为哥哥要回家了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来学校很安静，同学们都在准备考试。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来老张在医院照顾父亲，很少回家。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来我在学做饭，已经会做三个菜了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来没有看到他，听说他出差了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日来小河的水很少，鱼也不多了。", "target_word": "日来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日來", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "日来:副词,近几天以来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。日来（rì lái）：副词，指近几天以来。"}, {"text": "历来", "is_correct": false, "explanation": "历来（lì lái）与日来只差声母（r 与 l），意思是“一向，向来”。"}, {"text": "寄来", "is_correct": false, "explanation": "寄来（jì lái）与日来只差声母（r 与 j），意思是“寄到这里”。"}, {"text": "递来", "is_correct": false, "explanation": "递来（dì lái）与日来只差声母（r 与 d），意思是“传递过来”。"}, {"text": "日历", "is_correct": false, "explanation": "日历（rì lì）与日来的韵母和声调都不同（ai 与 i，第二声与第四声），意思是“日历”。"}], "explanations": {"日来": "正确答案。日来（rì lái）：副词，指近几天以来。", "历来": "历来（lì lái）与日来只差声母（r 与 l），意思是“一向，向来”。", "寄来": "寄来（jì lái）与日来只差声母（r 与 j），意思是“寄到这里”。", "递来": "递来（dì lái）与日来只差声母（r 与 d），意思是“传递过来”。", "日历": "日历（rì lì）与日来的韵母和声调都不同（ai 与 i，第二声与第四声），意思是“日历”。"}, "sentence_index": null, "correct_answer": "日来"}, "level_3": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。“日来我睡得不好”说的是近几天的状况，与副词义一致。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“近几天睡得不好”的持续状况不合。"}, {"text": "特意", "is_correct": false, "explanation": "搭配：“特意”修饰有意的行为，不能说“特意睡得不好”。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”指突然发生，与“白天没有精神”的持续影响不合。"}], "explanations": {"日来": "正确答案。“日来我睡得不好”说的是近几天的状况，与副词义一致。", "立刻": "语义：“立刻”表示马上发生，与“近几天睡得不好”的持续状况不合。", "特意": "搭配：“特意”修饰有意的行为，不能说“特意睡得不好”。", "猛然": "语义：“猛然”指突然发生，与“白天没有精神”的持续影响不合。"}, "sentence_index": 0, "correct_answer": "日来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日来我上小学的时候很调皮。", "explanation": "这里应该用〈小时候〉。日来只指近几天，不能用来说上小学时的事，说童年要用小时候。"}, {"text": "日来十年前他就离开了这座城市。", "explanation": "这里应该用〈从前〉。日来只指近几天，不能用来说十年前的事，说很久以前的事要用从前。"}, {"text": "日来明天会下大雨。", "explanation": "这里应该用〈今后〉。日来只指过去到现在的几天，不能用来预测明天的天气，说将来的情况要用今后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日来", "is_correct": true, "explanation": "正确答案。“日来老张在医院照顾父亲，很少回家”说的是近几天的情况，与副词义一致。"}, {"text": "却", "is_correct": false, "explanation": "语法：“却”是转折副词，不能用在句首，句中也没有转折关系，“却老张在医院照顾父亲”不成立。"}, {"text": "特地", "is_correct": false, "explanation": "搭配：“特地”修饰有意的行为，不能修饰“照顾父亲”这一状态。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上发生，与“很少回家”的持续情况不合。"}], "explanations": {"日来": "正确答案。“日来老张在医院照顾父亲，很少回家”说的是近几天的情况，与副词义一致。", "却": "语法：“却”是转折副词，不能用在句首，句中也没有转折关系，“却老张在医院照顾父亲”不成立。", "特地": "搭配：“特地”修饰有意的行为，不能修饰“照顾父亲”这一状态。", "立即": "语义：“立即”表示马上发生，与“很少回家”的持续情况不合。"}, "sentence_index": 6, "correct_answer": "日来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日来他出生在这个村子。", "explanation": "这里应该用〈早先〉。日来只指近几天，不能用来说出生这样久远的事，说从前的情况要用早先。"}, {"text": "日来这里会建一座大桥。", "explanation": "这里应该用〈日后〉。日来指过去到现在，不表示将来的计划，说将来要用日后。"}, {"text": "我日来在那里生活过，那是三十年前的事。", "explanation": "这里应该用〈多年前〉。日来只指近几天，与“三十年前”的说法矛盾，说很久以前的事要用多年前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很日来我的咳嗽好了一些，可以正常上班了。", "corrected_sentence": "日来我的咳嗽好了一些，可以正常上班了。", "error_description": "“日来”是副词，前面不能加“很”等程度词；“很日来我的咳嗽”不成立，应说“日来我的咳嗽好了一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日来的城里交通好了不少，地铁也修通了。", "corrected_sentence": "日来城里交通好了不少，地铁也修通了。", "error_description": "“日来”是副词，不能像形容词一样加“的”修饰名词，应说“日来城里交通好了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
