INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交叉是两条线或两条路碰在一起，像一个叉。", "primary_collocate": null, "pronunciation": "jiāo chā", "ipa": "tɕjɑʊ˥ ʈʂʰɑ˥", "syllable_count": 2, "sentences": [{"text": "这两条路在前面交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看图，这两条线在中间交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路和公路在那座桥下交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师画了两条线，让它们交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路交叉的地方要小心车。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条小路在树林里交叉，我不知道走哪条。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根绳子交叉着放在桌子上。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两根筷子交叉放在盘子上。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几条街在广场交叉，人特别多。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的两条红线在北京交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交叉着", "label": "体标"}, {"form": "交叉过", "label": "体标"}], "register": "通用", "sense_fingerprint": "两条线或路碰在一起成叉形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交叉", "is_correct": true, "explanation": "这里应该用〈交叉〉。两条路在前面相碰，形成叉形。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人的活动，道路不能散步。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”用于活动、展览，不能说道路举办。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架需要有人争执，道路不能吵架。"}], "explanations": {"交叉": "这里应该用〈交叉〉。两条路在前面相碰，形成叉形。", "散步": "语义：散步是人的活动，道路不能散步。", "举办": "搭配：“举办”用于活动、展览，不能说道路举办。", "吵架": "语义：吵架需要有人争执，道路不能吵架。"}, "sentence_index": 0, "correct_answer": "交叉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙交叉给了房东。", "explanation": "这里应该用〈交给〉。交叉指线路或道路互相穿过，形成叉形，不表示把东西递给别人；把钥匙交给房东要用〈交给〉。"}, {"text": "他去找房东交叉房租的问题。", "explanation": "这里应该用〈交涉〉。交叉指线路或道路互相穿过，不表示与人协商；为房租问题同房东协商要用〈交涉〉。"}, {"text": "我们交叉了这片树林。", "explanation": "这里应该用〈穿过〉。交叉要求两条线或两条路互相穿过，形成叉形；一个人走过一片树林要用〈穿过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交叉", "is_correct": true, "explanation": "这里应该用〈交叉〉。两根绳子互相穿过，摆成叉形。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是人的动作，绳子不能唱歌。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠只用于人，绳子不会失眠。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”针对计划、申请，不能用于绳子。"}], "explanations": {"交叉": "这里应该用〈交叉〉。两根绳子互相穿过，摆成叉形。", "唱歌": "语义：唱歌是人的动作，绳子不能唱歌。", "失眠": "语义：失眠只用于人，绳子不会失眠。", "批准": "搭配：“批准”针对计划、申请，不能用于绳子。"}, "sentence_index": 6, "correct_answer": "交叉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那辆车交叉马路时，司机很紧张。", "explanation": "这里应该用〈横穿〉。交叉指两条线或两条路互相穿过，形成叉形；一辆车从一侧穿过马路要用〈横穿〉。"}, {"text": "他顺利交叉了考试。", "explanation": "这里应该用〈通过〉。交叉不表示顺利过关；通过考试要用〈通过〉。"}, {"text": "我每天下班都交叉那家书店。", "explanation": "这里应该用〈路过〉。交叉指两条线或两条路互相穿过，形成叉形；一个人顺路经过某处要用〈路过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两条小路在山谷口被交叉。", "corrected_sentence": "这两条小路在山谷口交叉。", "error_description": "“交叉”是不及物动词，表示线路互相穿过，不能用“被”构成被动句；应说“这两条小路在山谷口交叉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种颜色的线很交叉着。", "corrected_sentence": "这两种颜色的线交叉着。", "error_description": "“交叉”是动词，前面不能直接加程度副词“很”；去掉“很”，说“这两种颜色的线交叉着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
