INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "几条线或路互相穿过；也指两种事物互相穿插。", "primary_collocate": null, "pronunciation": "jiāo chā", "ipa": "tɕjɑʊ˥ ʈʂʰɑ˥", "syllable_count": 2, "sentences": [{"text": "这两条铁路在城南交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几条公路在山脚下交叉，路口很大。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两门课的内容有些交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的工作常常交叉，需要多沟通。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个小组的任务交叉着，大家要互相帮忙。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个项目的时间交叉，我忙不过来。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁一号线和二号线在市中心交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个学科有交叉的地方。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几条小路交叉在一起，我走错了方向。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的兴趣和工作有一些交叉。", "target_word": "交叉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交叉着", "label": "体标"}, {"form": "交叉过", "label": "体标"}], "register": "通用", "sense_fingerprint": "线路穿过；事物互相穿插、重叠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交叉", "is_correct": true, "explanation": "这里应该用〈交叉〉。两条铁路在城南相互穿过，形成交叉。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”用于活动、展览，不能说铁路举办。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览需要人作主体，铁路不能去游览。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病只用于人或动物，铁路不会生病。"}], "explanations": {"交叉": "这里应该用〈交叉〉。两条铁路在城南相互穿过，形成交叉。", "举办": "搭配：“举办”用于活动、展览，不能说铁路举办。", "游览": "语义：游览需要人作主体，铁路不能去游览。", "生病": "语义：生病只用于人或动物，铁路不会生病。"}, "sentence_index": 0, "correct_answer": "交叉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们交叉了电话号码，以后可以常联系。", "explanation": "这里应该用〈交换〉。交叉指线路或事物互相穿插，不表示双方互相给予；交换电话号码要用〈交换〉。"}, {"text": "两位老师经常交叉教学经验，大家都很受益。", "explanation": "这里应该用〈交流〉。交叉指线路或事物互相穿插，不表示相互沟通；交流教学经验要用〈交流〉。"}, {"text": "这份工作已经交叉给小王了。", "explanation": "这里应该用〈交接〉。交叉指线路或事物互相穿插，不表示把工作移交给别人；工作移交要用〈交接〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交叉", "is_correct": true, "explanation": "这里应该用〈交叉〉。地铁线路在市中心相互穿过，形成交叉。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是人的动作，地铁线路不能睡觉。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”通常搭配节目、视频，不能说地铁线路播放。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚只用于人，地铁线路不能结婚。"}], "explanations": {"交叉": "这里应该用〈交叉〉。地铁线路在市中心相互穿过，形成交叉。", "睡觉": "语义：睡觉是人的动作，地铁线路不能睡觉。", "播放": "搭配：“播放”通常搭配节目、视频，不能说地铁线路播放。", "结婚": "语义：结婚只用于人，地铁线路不能结婚。"}, "sentence_index": 6, "correct_answer": "交叉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本书交叉给我，让我先看看。", "explanation": "这里应该用〈借〉。交叉指线路或事物互相穿插，不表示把东西借给别人；把书借给别人要用〈借〉。"}, {"text": "我们明天交叉一下作业，再一起讨论。", "explanation": "这里应该用〈交换〉。交叉指事物互相穿插，不表示双方互相交付；交换作业要用〈交换〉。"}, {"text": "他交叉了三次手机，都不太满意。", "explanation": "这里应该用〈换〉。交叉指事物互相穿插，不表示更换；更换手机要用〈换〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两条小路在村口被交叉。", "corrected_sentence": "这两条小路在村口交叉。", "error_description": "“交叉”是不及物动词，表示线路互相穿过，不能用“被”构成被动句；应说“这两条小路在村口交叉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个部门的职责很交叉。", "corrected_sentence": "两个部门的职责有些交叉。", "error_description": "“很”是程度副词，不能直接修饰动词“交叉”；表示程度轻应把“很”改为“有些”，说“两个部门的职责有些交叉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
