INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每日是每一天。", "primary_collocate": null, "pronunciation": "měi rì", "ipa": "meɪ˨˩ ɻʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "每日的作业不多，很快就能写完。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每日三餐，她都自己做。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的每日生活很有规律。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每日的新闻我都会看一看。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我每日的任务。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每日的天气都写在本子上。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每日的早餐是粥和鸡蛋。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每日一小时的练习很重要。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每日的工作让他很累。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每日的花费记下来了。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "每日：每一天（作名词性修饰语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每日", "is_correct": true, "explanation": "正确：“每日”表示每一天，修饰“作业”，与“作业不多，很快就能写完”相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会有作业，与“作业不多，很快就能写完”矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“作业”需要能做作业的拥有者，“小猫”不符合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱没有作业，与语境矛盾。"}], "explanations": {"每日": "正确：“每日”表示每一天，修饰“作业”，与“作业不多，很快就能写完”相符。", "窗户": "语义：窗户不会有作业，与“作业不多，很快就能写完”矛盾。", "小猫": "配价：“作业”需要能做作业的拥有者，“小猫”不符合。", "冰箱": "语义：冰箱没有作业，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "每日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对新人的每日婚礼很热闹。", "explanation": "这里应该用〈一生〉。婚礼一生通常只举办一次，“每日”指每一天，不能用来修饰“婚礼”。"}, {"text": "每日的春节都很热闹。", "explanation": "这里应该用〈每年〉。春节一年一次，“每日”指每一天，不能修饰“春节”。"}, {"text": "每日的例会都在周一召开。", "explanation": "这里应该用〈每周〉。例会按周召开，“每日”指每天，与“周一”的安排矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每日", "is_correct": true, "explanation": "正确：“每日”表示每一天，修饰“早餐”，符合习惯。"}, {"text": "每月", "is_correct": false, "explanation": "语义：早餐是每天吃的，不能按月计算，与“早餐是粥和鸡蛋”的日常语境矛盾。"}, {"text": "每年", "is_correct": false, "explanation": "语义：早餐不按年计算，与语境矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“早餐”的拥有者需要能吃饭，“窗户”不符合。"}], "explanations": {"每日": "正确：“每日”表示每一天，修饰“早餐”，符合习惯。", "每月": "语义：早餐是每天吃的，不能按月计算，与“早餐是粥和鸡蛋”的日常语境矛盾。", "每年": "语义：早餐不按年计算，与语境矛盾。", "窗户": "配价：“早餐”的拥有者需要能吃饭，“窗户”不符合。"}, "sentence_index": 6, "correct_answer": "每日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每日的开学典礼都在九月举行。", "explanation": "这里应该用〈每学期〉。开学典礼一学期一次，“每日”指每一天，不能修饰“开学典礼”。"}, {"text": "我每日的生日聚会都很热闹。", "explanation": "这里应该用〈每年〉。生日一年只有一次，“每日”指每一天，不能修饰“生日聚会”。"}, {"text": "每日的年终奖都发得很多。", "explanation": "这里应该用〈每年〉。年终奖一年发一次，“每日”指每一天，不能修饰“年终奖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每日地新闻很有意思。", "corrected_sentence": "每日的新闻很有意思。", "error_description": "结构助词错误：「每日地新闻」应为「每日的新闻」。“每日”修饰名词「新闻」时要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每日地报纸我都会看。", "corrected_sentence": "每日的报纸我都会看。", "error_description": "结构助词错误：「每日地报纸」应为「每日的报纸」。“每日”修饰名词「报纸」时要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
