INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88284, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每天。", "primary_collocate": null, "pronunciation": "měi rì", "ipa": "meɪ˨˩ ɻʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他每日早上六点起床。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每日坐地铁去上班。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你每日要多喝水。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每日八点开门。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每日跑步半小时。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每日给奶奶打电话。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每日写一页日记。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每日都来得很早。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每日在公园散步。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹每日练习写汉字。", "target_word": "每日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "每日：每天（作状语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每日", "is_correct": true, "explanation": "正确：“每日”表示每天，修饰“早上六点起床”的习惯性动作，符合语境。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示正在进行，不能与“早上六点”这一具体时点搭配。"}, {"text": "非常", "is_correct": false, "explanation": "程度副词，不能直接修饰“起床”作状语，此处不成立。"}, {"text": "十分", "is_correct": false, "explanation": "程度副词，不能修饰动作“起床”，与“早上六点起床”搭配不通。"}], "explanations": {"每日": "正确：“每日”表示每天，修饰“早上六点起床”的习惯性动作，符合语境。", "正在": "搭配：“正在”表示正在进行，不能与“早上六点”这一具体时点搭配。", "非常": "程度副词，不能直接修饰“起床”作状语，此处不成立。", "十分": "程度副词，不能修饰动作“起床”，与“早上六点起床”搭配不通。"}, "sentence_index": 0, "correct_answer": "每日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校每日招一次新生。", "explanation": "这里应该用〈每年〉。招生一年一次，“每日”指每天，不能用于此处。"}, {"text": "学校每日组织一次春游。", "explanation": "这里应该用〈每学期〉。春游一学期一次，“每日”指每天，与活动的周期不符。"}, {"text": "每日节日，全家都会团聚。", "explanation": "这里应该用〈每逢〉。“每逢节日”指每次遇到节日，“每日”不能与“节日”这样的特定日子搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每日", "is_correct": true, "explanation": "正确：“每日”表示每天，与“写一页日记”的日常习惯相符。"}, {"text": "非常", "is_correct": false, "explanation": "程度副词，不能直接修饰动作“写”作状语，此处不成立。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“每日”的每天重复不符。"}, {"text": "比较", "is_correct": false, "explanation": "程度副词，不能直接修饰“写”作状语，此处不成立。"}], "explanations": {"每日": "正确：“每日”表示每天，与“写一页日记”的日常习惯相符。", "非常": "程度副词，不能直接修饰动作“写”作状语，此处不成立。", "已经": "语义：“已经”表示动作已经完成，与“每日”的每天重复不符。", "比较": "程度副词，不能直接修饰“写”作状语，此处不成立。"}, "sentence_index": 6, "correct_answer": "每日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每日春天，树叶就变绿了。", "explanation": "这里应该用〈每到〉。“每到春天”指每次到春天，“每日”指每天，不能用于一年一次的季节。"}, {"text": "这场比赛每日都在夏天举行。", "explanation": "这里应该用〈每年〉。比赛每年举办一次，“每日”指每天，与“每年”的周期不符。"}, {"text": "这本月刊每日出版一次。", "explanation": "这里应该用〈每月〉。月刊每月出版一次，“每日”指每天，与出版周期不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每日的做早饭。", "corrected_sentence": "妈妈每日做早饭。", "error_description": "“每日”作状语，其后不能加“的”直接修饰动词，“每日的做早饭”应删去「的」，即“每日做早饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹每日的练习写汉字十分钟。", "corrected_sentence": "妹妹每日练习写汉字十分钟。", "error_description": "“每日”作状语，其后不能加“的”，“每日的练习”应删去「的」，即“妹妹每日练习写汉字十分钟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
