INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "他乡是指不是自己家乡的别的地方。", "primary_collocate": null, "pronunciation": "tā xiāng", "ipa": "tʰa˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他乡的菜和我家乡的味道不一样。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次来到他乡，她觉得很新鲜。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在他乡也要照顾好自己。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乡的人说话和我们不太一样。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在他乡买了一所小房子。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去他乡看看不同的风景。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他乡读书的学生每年只回家一次。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乡的路他不熟，常常走错。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把他乡的故事讲给奶奶听。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他乡，他认识了很多新朋友。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "他鄉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "不是自己家乡的别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：他乡 tā xiāng，指不是自己家乡的别的地方。"}, {"text": "他想", "is_correct": false, "explanation": "他想 tā xiǎng：第二音节声调不同（乡 xiāng 第一声，想 xiǎng 第三声），意思是“他认为”或“他想要”。"}, {"text": "他像", "is_correct": false, "explanation": "他像 tā xiàng：第二音节声调不同（像 xiàng 第四声），意思是“他的样子与……相似”。"}, {"text": "他先", "is_correct": false, "explanation": "他先 tā xiān：第二音节韵尾不同（xiāng 为 -ng，xiān 为 -n），意思是“他在前面”或“他首先”。"}], "explanations": {"他乡": "正确：他乡 tā xiāng，指不是自己家乡的别的地方。", "他想": "他想 tā xiǎng：第二音节声调不同（乡 xiāng 第一声，想 xiǎng 第三声），意思是“他认为”或“他想要”。", "他像": "他像 tā xiàng：第二音节声调不同（像 xiàng 第四声），意思是“他的样子与……相似”。", "他先": "他先 tā xiān：第二音节韵尾不同（xiāng 为 -ng，xiān 为 -n），意思是“他在前面”或“他首先”。"}, "sentence_index": null, "correct_answer": "他乡"}, "level_3": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：“……的菜”要求菜的来源，他乡指家乡之外的别处，与“我家乡的味道”形成对比。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是愿望，没有菜，“梦想的菜”不成立。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“……的菜”要求食物的产地或来源，“时间”不能作菜的来源。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是叙述内容，不能做出菜，与句中比较味道的语境不合。"}], "explanations": {"他乡": "正确：“……的菜”要求菜的来源，他乡指家乡之外的别处，与“我家乡的味道”形成对比。", "梦想": "语义：梦想是愿望，没有菜，“梦想的菜”不成立。", "时间": "搭配：“……的菜”要求食物的产地或来源，“时间”不能作菜的来源。", "故事": "语义：故事是叙述内容，不能做出菜，与句中比较味道的语境不合。"}, "sentence_index": 0, "correct_answer": "他乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上遇到一个他乡。", "explanation": "这里应该用〈同乡〉。他乡指地方，不能指人，所以不能说“遇到一个他乡”。"}, {"text": "我小时候常在这片稻田里放牛，这里就是我的他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，自己小时候放牛的稻田所在地就是家乡，不能称作他乡。"}, {"text": "他从小在这条小河边玩耍长大，这里是他的他乡。", "explanation": "这里应该用〈故乡〉。他从小在这里长大，这里是他的故乡，他乡指离开家乡后所在的别处，不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：“在……读书”需要处所词，他乡指离开家乡的别处，符合“学生每年只回家一次”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不是读书的地方，“在颜色读书”不成立。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“在……读书”要求处所，“年龄”不能作读书的场所。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不能作读书的地方，与句中的学生身份不合。"}], "explanations": {"他乡": "正确：“在……读书”需要处所词，他乡指离开家乡的别处，符合“学生每年只回家一次”的语境。", "颜色": "语义：颜色是事物的属性，不是读书的地方，“在颜色读书”不成立。", "年龄": "搭配：“在……读书”要求处所，“年龄”不能作读书的场所。", "工资": "语义：工资是收入，不能作读书的地方，与句中的学生身份不合。"}, "sentence_index": 6, "correct_answer": "他乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每年寒假，我都回他乡过年。", "explanation": "这里应该用〈老家〉。他乡指离开家乡后的别处，寒假回去过年的是老家。"}, {"text": "他从小在村里长大，每天帮家里干活，村子是他的他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，他从小在村里长大，村子就是家乡，不能称为他乡。"}, {"text": "这是我出生长大的他乡。", "explanation": "这里应该用〈地方〉。他乡指离开家乡后所在的别处，不能指自己出生长大的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他他乡的生活很辛苦。", "corrected_sentence": "他在他乡的生活很辛苦。", "error_description": "错误：“他他乡的生活”，正确：“他在他乡的生活”。“他乡”表示地点，前面需要介词“在”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "是他乡的日子里，他很想家。", "corrected_sentence": "在他乡的日子里，他很想家。", "error_description": "错误：“是他乡的日子里”，正确：“在他乡的日子里”。“是”是判断动词，不能引出地点；表示在某处时要用介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
