INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "离开家乡后所在的别处，异乡。", "primary_collocate": null, "pronunciation": "tā xiāng", "ipa": "tʰa˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他在他乡工作了十年。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人在他乡生活，很想家。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乡的月亮不如家乡的圆。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家，到他乡去打工。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，在他乡的人都想回家。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在他乡遇到了老同乡。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然身在他乡，他每天都给妈妈打电话。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在他乡住过很多年。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乡的冬天比家乡冷多了。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在他乡过着忙碌的生活。", "target_word": "他乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "他鄉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "离开家乡后所在的别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：他乡 tā xiāng，指离开家乡后所在的别处。"}, {"text": "他想", "is_correct": false, "explanation": "他想 tā xiǎng：第二音节声调不同（乡 xiāng 第一声，想 xiǎng 第三声），意思是“他认为”或“他想要”。"}, {"text": "他像", "is_correct": false, "explanation": "他像 tā xiàng：第二音节声调不同（像 xiàng 第四声），意思是“他的样子与……相似”。"}, {"text": "他先", "is_correct": false, "explanation": "他先 tā xiān：第二音节韵尾不同（xiāng 为 -ng，xiān 为 -n），意思是“他在前面”或“他首先”。"}], "explanations": {"他乡": "正确：他乡 tā xiāng，指离开家乡后所在的别处。", "他想": "他想 tā xiǎng：第二音节声调不同（乡 xiāng 第一声，想 xiǎng 第三声），意思是“他认为”或“他想要”。", "他像": "他像 tā xiàng：第二音节声调不同（像 xiàng 第四声），意思是“他的样子与……相似”。", "他先": "他先 tā xiān：第二音节韵尾不同（xiāng 为 -ng，xiān 为 -n），意思是“他在前面”或“他首先”。"}, "sentence_index": null, "correct_answer": "他乡"}, "level_3": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：“在……工作”需要处所词，他乡指离开家乡的别处。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是愿望，不是可以工作的场所，“在梦想工作”不成立。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在……工作”要求处所宾语，“时间”不能作工作的场所。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是内心状态，不是地点，无法与“在”构成工作的处所。"}], "explanations": {"他乡": "正确：“在……工作”需要处所词，他乡指离开家乡的别处。", "梦想": "语义：梦想是愿望，不是可以工作的场所，“在梦想工作”不成立。", "时间": "搭配：“在……工作”要求处所宾语，“时间”不能作工作的场所。", "心情": "语义：心情是内心状态，不是地点，无法与“在”构成工作的处所。"}, "sentence_index": 0, "correct_answer": "他乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我出生在这个村子，从来没离开过，这个村子是我的他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，自己出生并一直生活的村子是家乡，不能称作他乡。"}, {"text": "我从小住在这个村子，这里就是我的他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，自己从小生活的村子就是家乡，不能称作他乡。"}, {"text": "每年春节我都回他乡探望爸妈，他们一直住在我的老家。", "explanation": "这里应该用〈老家〉。爸妈一直住在老家，春节回去探望的地方就是老家，不能称作他乡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他乡", "is_correct": true, "explanation": "正确：“身在”后接处所，他乡表示离开家乡的别处，与“虽然”的让步关系相合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“身在”后要接处所词，“年龄”不是处所，“身在年龄”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不是可以身处的地方。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不能作身处的场所，与句中打电话的情境无关。"}], "explanations": {"他乡": "正确：“身在”后接处所，他乡表示离开家乡的别处，与“虽然”的让步关系相合。", "年龄": "搭配：“身在”后要接处所词，“年龄”不是处所，“身在年龄”不成立。", "颜色": "语义：颜色是事物的属性，不是可以身处的地方。", "工资": "语义：工资是收入，不能作身处的场所，与句中打电话的情境无关。"}, "sentence_index": 6, "correct_answer": "他乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在这个小镇出生长大，每天下班都急着回他乡吃饭。", "explanation": "这里应该用〈家〉。他乡指离开家乡后所在的别处，出生长大的小镇是家乡，下班回去吃饭的地方不能称作他乡。"}, {"text": "他从没离开过这座小城，这里对他来说是他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，从未离开过的小城是家乡，不能称为他乡。"}, {"text": "我在北京出生长大，北京是我的他乡。", "explanation": "这里应该用〈家乡〉。他乡指离开家乡后所在的别处，在北京出生长大的人，北京就是家乡，不能称为他乡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很多年都生活到他乡。", "corrected_sentence": "他很多年都生活在他乡。", "error_description": "错误：“生活到他乡”，正确：“生活在他乡”。“到”表示动作抵达某处，不能与表示持续停留的“生活”搭配；“生活”后接处所要用介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷从他乡生活了很多年。", "corrected_sentence": "爷爷在他乡生活了很多年。", "error_description": "错误：“从他乡生活”，正确：“在他乡生活”。“从”表示起点，“生活”表示在某处持续停留，处所前要用介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
