INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法院中负责审理案件和作出判决的人员。", "primary_collocate": null, "pronunciation": "fǎ guān", "ipa": "fa˨˩˦ kuan˥", "syllable_count": 2, "sentences": [{"text": "法官今天审理了一件旧案子。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官根据法律作出了判决。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位法官已经审理过上百件案件。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要先看证据，再作判决。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在法院当法官，每天都很忙。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官认真听了律师的意见。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻的法官第一次审理大案。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官宣布了最后的判决结果。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官必须公正，不能偏向任何一方。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官把判决书交给了双方。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女法官", "label": "复合"}, {"form": "大法官", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院里审理案件、作出判决的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adf9579b-4126-4d8c-b7a3-be431450724f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法官", "is_correct": true, "explanation": "正确：审理案件的是法官，与“审理案子”相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不负责审理案件。"}, {"text": "花店", "is_correct": false, "explanation": "语义：花店是商店，不能审理案子。"}, {"text": "园丁", "is_correct": false, "explanation": "搭配：“审理案子”需要司法人员作主语，“园丁”不搭配这一动词。"}], "explanations": {"法官": "正确：审理案件的是法官，与“审理案子”相符。", "司机": "语义：司机不负责审理案件。", "花店": "语义：花店是商店，不能审理案子。", "园丁": "搭配：“审理案子”需要司法人员作主语，“园丁”不搭配这一动词。"}, "sentence_index": 0, "correct_answer": "法官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官在路口拦下了一辆车，检查证件。", "explanation": "这里应该用〈警察〉。拦车检查证件是警察的工作，法官在法院审理案件，不做路面执法。"}, {"text": "法官替被告辩护，请求法院放人。", "explanation": "这里应该用〈律师〉。替被告辩护是律师的职责，法官不替任何一方说话。"}, {"text": "法官在法庭上宣读了起诉书。", "explanation": "这里应该用〈检察官〉。宣读起诉书是检察官的职责，法官负责作出判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法官", "is_correct": true, "explanation": "正确：年轻的司法人员第一次审理大案，只有“法官”符合。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“年轻的”与“老人”矛盾。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不负责审理大案。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“审理大案”的主语应是司法人员，“厨师”不搭配这一动词。"}], "explanations": {"法官": "正确：年轻的司法人员第一次审理大案，只有“法官”符合。", "老人": "语义：“年轻的”与“老人”矛盾。", "歌手": "语义：歌手不负责审理大案。", "厨师": "搭配：“审理大案”的主语应是司法人员，“厨师”不搭配这一动词。"}, "sentence_index": 6, "correct_answer": "法官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法官在学校教数学，给学生布置了作业。", "explanation": "这里应该用〈老师〉。在学校教课、布置作业的是老师，法官在法院审理案件。"}, {"text": "法官在厨房做了一顿饭，味道很好。", "explanation": "这里应该用〈厨师〉。做饭的是厨师，法官在法院审理案件，不做饭。"}, {"text": "我姐姐在法官上班，每天都很累。", "explanation": "这里应该用〈法院〉。“在……上班”的地点要用法院，法官是审判案件的人，不是工作的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只法官听完了双方的陈述，然后作出了判决。", "corrected_sentence": "那位法官听完了双方的陈述，然后作出了判决。", "error_description": "量词错误：指人的“法官”应用“位”，不用“只”（“只”多用于动物）。应改为“那位法官听完了双方的陈述，然后作出了判决”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条法官宣布休庭。", "corrected_sentence": "那位法官宣布休庭。", "error_description": "量词错误：“法官”指人，应用“位”，不能用“条”（“条”多用于鱼、河、路等长条形的东西）。应改为“那位法官宣布休庭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
