INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88293, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "处理公务、上班工作用的房间。", "primary_collocate": null, "pronunciation": "bàn gōng shì", "ipa": "/pan˥˩ kʊŋ˥ ʂɻ̩˥˩/", "syllable_count": 3, "sentences": [{"text": "爸爸每天坐在办公室里工作。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里有一张大桌子。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的办公室在三楼。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在办公室里接电话。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的窗户很大。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去办公室找爸爸。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在办公室里写报告。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里坐着三个人。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，办公室里没有人了。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在办公室里喝了一杯茶。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "校长办公室", "label": "复合"}, {"form": "辦公室", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办公室：人们上班时坐着工作的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办公室", "is_correct": true, "explanation": "正确：办公室是上班时坐着工作的房间，与“坐在…里工作”搭配。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是运动的露天场地，不能“坐在操场里工作”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是放食物的电器，人不能“坐在冰箱里工作”。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是游泳的地方，不能在里面坐着工作。"}], "explanations": {"办公室": "正确：办公室是上班时坐着工作的房间，与“坐在…里工作”搭配。", "操场": "语义：操场是运动的露天场地，不能“坐在操场里工作”。", "冰箱": "语义：冰箱是放食物的电器，人不能“坐在冰箱里工作”。", "游泳池": "语义：游泳池是游泳的地方，不能在里面坐着工作。"}, "sentence_index": 0, "correct_answer": "办公室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的办公室有二十层。", "explanation": "这里应该用〈办公楼〉。办公室是房间，层数指整栋楼，要说“办公楼有二十层”。"}, {"text": "学生们在办公室里踢足球。", "explanation": "这里应该用〈操场〉。踢足球要在操场进行，办公室是处理日常事务的房间，不能用来运动。"}, {"text": "他每天早上在办公室里刷牙。", "explanation": "这里应该用〈浴室〉。刷牙要在浴室或卫生间进行，办公室是处理日常事务的房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办公室", "is_correct": true, "explanation": "正确：办公室是工作的房间，“在办公室里写报告”很自然。"}, {"text": "浴室", "is_correct": false, "explanation": "语义：浴室是洗澡的地方，不能在里面写报告。"}, {"text": "体育场", "is_correct": false, "explanation": "语义：体育场是运动的场地，不适合写报告。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是游泳的地方，不能在里面写报告。"}], "explanations": {"办公室": "正确：办公室是工作的房间，“在办公室里写报告”很自然。", "浴室": "语义：浴室是洗澡的地方，不能在里面写报告。", "体育场": "语义：体育场是运动的场地，不适合写报告。", "游泳池": "语义：游泳池是游泳的地方，不能在里面写报告。"}, "sentence_index": 6, "correct_answer": "办公室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在办公室里种水稻。", "explanation": "这里应该用〈稻田〉。种水稻要在稻田里，办公室是上班工作的房间。"}, {"text": "我们在办公室里游泳。", "explanation": "这里应该用〈游泳池〉。游泳要在游泳池进行，办公室是处理日常事务的房间。"}, {"text": "观众在办公室里看演出。", "explanation": "这里应该用〈剧院〉。看演出要在剧院进行，办公室是处理日常事务的房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只办公室很大。", "corrected_sentence": "那间办公室很大。", "error_description": "量词错误：办公室的量词是“间”，不说“那只办公室”。应说“那间办公室很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
