INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、企业等单位中处理日常事务的房间。", "primary_collocate": null, "pronunciation": "bàn gōng shì", "ipa": "/pan˥˩ kʊŋ˥ ʂɻ̩˥˩/", "syllable_count": 3, "sentences": [{"text": "学校的办公室下午三点关门。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把表格交到办公室。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的办公室搬到了新楼。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的门开着，里面没有人。", "target_word": "办公室", "complexity_tier": "T3", "furigana": "bàn gōng shì de mén kāi zhe lǐ miàn méi yǒu rén", "sentence_source": "generated"}, {"text": "王老师去了办公室。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的灯一直亮着，没有人关。", "target_word": "办公室", "complexity_tier": "T3", "furigana": "bàn gōng shì de dēng yì zhí liàng zhe méi yǒu rén guān", "sentence_source": "generated"}, {"text": "办公室的电话一直在响。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的空调坏了，很热。", "target_word": "办公室", "complexity_tier": "T3", "furigana": "bàn gōng shì de kōng tiáo huài le hěn rè", "sentence_source": "generated"}, {"text": "厂里的办公室在大门旁边。", "target_word": "办公室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的墙上挂着一张地图。", "target_word": "办公室", "complexity_tier": "T3", "furigana": "bàn gōng shì de qiáng shàng guà zhe yì zhāng dì tú", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "校长办公室", "label": "复合"}, {"form": "辦公室", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办公室：机关、学校、企业等单位处理日常事务的部门或房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办公室", "is_correct": true, "explanation": "正确：办公室是单位处理日常事务的房间，可以在下午三点关门。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字的用具，不是房间，不会“关门”。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是放书本的家具，不会“关门”。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不会“关门”。"}], "explanations": {"办公室": "正确：办公室是单位处理日常事务的房间，可以在下午三点关门。", "黑板": "语义：黑板是写字的用具，不是房间，不会“关门”。", "课桌": "语义：课桌是放书本的家具，不会“关门”。", "书架": "语义：书架是放书的家具，不会“关门”。"}, "sentence_index": 0, "correct_answer": "办公室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在办公室里洗衣服。", "explanation": "这里应该用〈洗衣房〉。洗衣服要在洗衣房进行，办公室是机关或企业中处理日常事务的房间。"}, {"text": "孩子们在办公室里游泳。", "explanation": "这里应该用〈游泳池〉。游泳要在游泳池进行，办公室是机关或企业中处理日常事务的房间。"}, {"text": "工人们在办公室里操作机器。", "explanation": "这里应该用〈车间〉。操作机器要在车间进行，办公室是处理日常事务的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办公室", "is_correct": true, "explanation": "正确：办公室是有电话的工作房间，“办公室的电话一直在响”很自然。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花草的地方，不会有一直响的电话。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野是露天的土地，不会有一直响的电话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是房间，不会有电话响。"}], "explanations": {"办公室": "正确：办公室是有电话的工作房间，“办公室的电话一直在响”很自然。", "花园": "语义：花园是种花草的地方，不会有一直响的电话。", "田野": "语义：田野是露天的土地，不会有一直响的电话。", "石头": "语义：石头不是房间，不会有电话响。"}, "sentence_index": 6, "correct_answer": "办公室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在办公室里做手术。", "explanation": "这里应该用〈手术室〉。做手术要在手术室进行，办公室是处理日常事务的房间。"}, {"text": "学生在办公室里做实验。", "explanation": "这里应该用〈实验室〉。做实验要在实验室进行，办公室用于处理日常事务。"}, {"text": "妈妈在办公室里做饭。", "explanation": "这里应该用〈厨房〉。做饭要在厨房进行，办公室不是做饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司的一只办公室在三楼。", "corrected_sentence": "我们公司的一间办公室在三楼。", "error_description": "量词错误：办公室的量词是“间”，不说“一只办公室”。应说“一间办公室在三楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班以后，我办公室里待了一会儿。", "corrected_sentence": "下班以后，我在办公室里待了一会儿。", "error_description": "漏字：“办公室”前面要加“在”，应说“在办公室里待”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
