INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "令爱是对别人的女儿的客气叫法。", "primary_collocate": null, "pronunciation": "lìng ài", "ipa": "liŋ˥˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "赵先生，令爱在哪家医院工作？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恭喜您，令爱昨天得了第一名。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周太太，请问令爱喜欢吃什么？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想送一本书给令爱，不知道她喜欢吗？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听同事说，令爱很会唱歌。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙先生，令爱现在住在哪个城市？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "令爱学习这么努力，将来一定有出息。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问令爱会说汉语吗？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吴老师，令爱明天有空来我家玩吗？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您好，我是令爱的同学。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "令愛", "label": "繁体"}], "register": "敬辞", "sense_fingerprint": "客气地称呼别人的女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "令爱", "is_correct": true, "explanation": "正确：令爱是敬称对方的女儿，与“赵先生，……在哪家医院工作”的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能在医院工作。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能作为“工作”的主语。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“工作”需要人作主语，手机不能在医院工作。"}], "explanations": {"令爱": "正确：令爱是敬称对方的女儿，与“赵先生，……在哪家医院工作”的语境相符。", "桌子": "语义：桌子是家具，不能在医院工作。", "花园": "语义：花园是场所，不能作为“工作”的主语。", "手机": "配价：“工作”需要人作主语，手机不能在医院工作。"}, "sentence_index": 0, "correct_answer": "令爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赵先生的令爱是个男生，我们一起打篮球。", "explanation": "这里应该用〈令郎〉。令爱只用于称对方的女儿，不能指男生。"}, {"text": "我的令爱在学校很优秀。", "explanation": "这里应该用〈小女〉。令爱是敬称对方女儿的词，称自己的女儿要用〈小女〉。"}, {"text": "赵先生，您家有一条令爱，真可爱。", "explanation": "这里量词用错了。〈条〉用于细长的东西，令爱指人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "令爱", "is_correct": true, "explanation": "正确：令爱指对方的女儿，主语可以“学习”并“有出息”，与句子语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会学习，“天气学习这么努力”说不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头没有学习能力，不能作为“努力学习”的主语。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“学习”要求人作主语，电脑不能“学习得很努力”。"}], "explanations": {"令爱": "正确：令爱指对方的女儿，主语可以“学习”并“有出息”，与句子语境相符。", "天气": "语义：天气不会学习，“天气学习这么努力”说不通。", "木头": "语义：木头没有学习能力，不能作为“努力学习”的主语。", "电脑": "配价：“学习”要求人作主语，电脑不能“学习得很努力”。"}, "sentence_index": 6, "correct_answer": "令爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "您好，令爱是我的母亲，我来看您。", "explanation": "这里应该用〈令堂〉。令爱指对方的女儿，不能用来指母亲。"}, {"text": "您好，我是一把令爱的同学。", "explanation": "这里量词用错了。〈把〉用于有柄的器具，令爱指人，应该用〈位〉。"}, {"text": "您好，您家的一头令爱是我的同学。", "explanation": "这里量词用错了。〈头〉用于牛羊等动物，令爱指人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赵先生，听说您有一条令爱在医院工作？", "corrected_sentence": "赵先生，听说您有一位令爱在医院工作？", "error_description": "错误：量词“条”；正确：“位”。“条”用于细长的东西，令爱指人，应该用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周老师的一把令爱很懂礼貌，大家都喜欢她。", "corrected_sentence": "周老师的令爱很懂礼貌，大家都喜欢她。", "error_description": "错误：多了量词“把”；正确：去掉。令爱指人，不用量词“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
