INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "敬辞，称对方的女儿。", "primary_collocate": null, "pronunciation": "lìng ài", "ipa": "liŋ˥˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "王先生，令爱今年几岁了？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说令爱考上了大学，真为你高兴。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李太太，令爱的钢琴弹得真好。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请代我向令爱问好。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老师，令爱是不是也在这所学校学习？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "令爱聪明又有礼貌，您一定很骄傲。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刘先生，令爱什么时候结婚？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在公园见到令爱，她正在画画。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末请带令爱来我家吃饭。", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈经理，令爱的病好些了吗？", "target_word": "令爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "令愛", "label": "繁体"}], "register": "敬辞", "sense_fingerprint": "敬称对方的女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "令爱", "is_correct": true, "explanation": "正确：令爱是敬称对方的女儿，问“几岁”符合人物的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有年龄，不能问“几岁”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“几岁”一般用于人或动物，问手机应说“用了几年”。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，没有年龄可问，句子语义不通。"}], "explanations": {"令爱": "正确：令爱是敬称对方的女儿，问“几岁”符合人物的语境。", "天气": "语义：天气没有年龄，不能问“几岁”。", "手机": "搭配：“几岁”一般用于人或动物，问手机应说“用了几年”。", "数学": "语义：数学是学科，没有年龄可问，句子语义不通。"}, "sentence_index": 0, "correct_answer": "令爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王先生的令爱是个男孩，今年五岁。", "explanation": "这里应该用〈令郎〉。令爱是敬称对方的女儿，不能用来称男孩。"}, {"text": "我的令爱今年五岁，很可爱。", "explanation": "这里应该用〈小女〉。令爱是敬称对方女儿的词，称自己的女儿要用〈小女〉。"}, {"text": "王先生，您家有一只令爱，真可爱。", "explanation": "这里量词用错了。〈只〉用于动物，令爱指人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "令爱", "is_correct": true, "explanation": "正确：令爱是对方的女儿，可以结婚，与“刘先生，……什么时候结婚”的语境相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不会结婚，与“什么时候结婚”不符。"}, {"text": "公司", "is_correct": false, "explanation": "配价：“结婚”的主语必须是人，公司不能结婚。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物品，不能结婚，句子语义不通。"}], "explanations": {"令爱": "正确：令爱是对方的女儿，可以结婚，与“刘先生，……什么时候结婚”的语境相符。", "窗户": "语义：窗户是物件，不会结婚，与“什么时候结婚”不符。", "公司": "配价：“结婚”的主语必须是人，公司不能结婚。", "钥匙": "语义：钥匙是物品，不能结婚，句子语义不通。"}, "sentence_index": 6, "correct_answer": "令爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陈经理，令爱是您的妈妈，我很尊敬她。", "explanation": "这里应该用〈令堂〉。令爱指对方的女儿，不能用来指母亲。"}, {"text": "陈经理，您家有一把令爱，真可爱。", "explanation": "这里量词用错了。〈把〉用于有柄的器具，令爱指人，应该用〈位〉。"}, {"text": "陈经理，您家的一头令爱很可爱。", "explanation": "这里量词用错了。〈头〉用于牛羊等动物，令爱指人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王先生，您家有一条令爱，真可爱。", "corrected_sentence": "王先生，您家有一位令爱，真可爱。", "error_description": "错误：量词“条”；正确：“位”。“条”用于细长的东西，令爱指人，应该用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "陈经理，听说您有一只令爱在国外读书？", "corrected_sentence": "陈经理，听说您有一位令爱在国外读书？", "error_description": "错误：量词“只”；正确：“位”。“只”用于动物，令爱指人，应该用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
