INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88297, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "永不是一直都不会，永远没有。", "primary_collocate": null, "pronunciation": "yǒng bù", "ipa": "joŋ˨˩˦ pu˥˩", "syllable_count": 2, "sentences": [{"text": "他说过，永不会忘记这里的朋友。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的牛奶永不加水。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友的承诺永不改变。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我永不会把这件事告诉别人。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座湖的泉水永不枯竭。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发誓永不再喝酒。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师永不会放弃任何一个学生。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘密永不会有人知道。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸答应我们，永不再抽烟。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应老师，永不再迟到。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "永不：一直都不会，表示某种情况永远不出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永不", "is_correct": true, "explanation": "正确：永不表示永远不会，与“说过”的承诺相符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指过去的时间，与“会忘记”表示的将来意思不符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“会忘记”的将来意思矛盾。"}, {"text": "压根儿", "is_correct": false, "explanation": "语法：“压根儿”后面要接“不”或“没”，“压根儿会忘记”不成立。"}], "explanations": {"永不": "正确：永不表示永远不会，与“说过”的承诺相符。", "刚才": "语义：“刚才”指过去的时间，与“会忘记”表示的将来意思不符。", "已经": "语义：“已经”表示已经发生，与“会忘记”的将来意思矛盾。", "压根儿": "语法：“压根儿”后面要接“不”或“没”，“压根儿会忘记”不成立。"}, "sentence_index": 0, "correct_answer": "永不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天永不来学校。", "explanation": "这里应该用〈没有〉。永不表示永远不会，不能用于昨天发生的一次性事情。"}, {"text": "这段时间我永不去健身房。", "explanation": "这里应该用〈暂时不〉。永不表示永远不，与“这段时间”的暂时性矛盾。"}, {"text": "明天可能永不下雨。", "explanation": "这里应该用〈可能不〉。永不语气绝对，与表示推测的“可能”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永不", "is_correct": true, "explanation": "正确：永不表示永远不会，符合老师对学生的承诺。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与“会”表示的将来意思矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与“会放弃”的将来意思不符。"}, {"text": "一个劲儿", "is_correct": false, "explanation": "语义：“一个劲儿”表示不停地做，不能和“会放弃”连用，句子不通。"}], "explanations": {"永不": "正确：永不表示永远不会，符合老师对学生的承诺。", "刚刚": "语义：“刚刚”指刚发生的事，与“会”表示的将来意思矛盾。", "曾经": "语义：“曾经”指过去，与“会放弃”的将来意思不符。", "一个劲儿": "语义：“一个劲儿”表示不停地做，不能和“会放弃”连用，句子不通。"}, "sentence_index": 6, "correct_answer": "永不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偶尔永不来上课。", "explanation": "这里应该用〈不〉，说偶尔不来上课。永不是长期、绝对的否定，与表示不定频率的偶尔矛盾。"}, {"text": "他一会儿永不说话。", "explanation": "这里应该用〈不〉，说一会儿不说话。永不是长期的绝对否定，与表示短暂时间的一会儿矛盾。"}, {"text": "他差点永不回家了。", "explanation": "这里应该用〈不〉，构成差点不回家了。永不是绝对的否定，与表示几乎发生的差点矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们永不不放弃自己的梦想。", "corrected_sentence": "我们永不放弃自己的梦想。", "error_description": "错误：“永不”本身已含否定意思，前面又加“不”形成双重否定，应去掉多余的“不”，说“永不放弃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我永不把告诉别人这个秘密。", "corrected_sentence": "我永不告诉别人这个秘密。", "error_description": "错误：“把”字句须“把+宾语+动词”，这里“把”后没有宾语，应去掉“把”，说“永不告诉别人这个秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
