INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88298, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "永远不；始终不。", "primary_collocate": null, "pronunciation": "yǒng bù", "ipa": "joŋ˨˩˦ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我们永不放弃，一直走到最后。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她永不后悔自己的选择。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家永不向困难低头。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发誓永不说谎。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你永不忘记今天的话。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们永不分开，一起过了一辈子。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务永不让人失望。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间永不互相骗。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他永不改变主意，谁说也没用。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司永不裁员，员工都很放心。", "target_word": "永不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "永不：永远不、始终不，表示坚定的决心或态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永不", "is_correct": true, "explanation": "正确：永不表示坚决不会，与“一直走到最后”的决心相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常，与“一直走到最后”的坚定态度矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不在意，与“一直走到最后”的坚持相矛盾。"}, {"text": "压根儿", "is_correct": false, "explanation": "语域：“压根儿”是口语，用在这种决心的表达里不自然。"}], "explanations": {"永不": "正确：永不表示坚决不会，与“一直走到最后”的决心相符。", "偶尔": "语义：“偶尔”表示不常，与“一直走到最后”的坚定态度矛盾。", "随便": "语义：“随便”表示不在意，与“一直走到最后”的坚持相矛盾。", "压根儿": "语域：“压根儿”是口语，用在这种决心的表达里不自然。"}, "sentence_index": 0, "correct_answer": "永不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年永不说谎，所以大家都信他。", "explanation": "这里应该用〈没有〉。永不表示长期或永远的态度，不能用于去年某段时间。"}, {"text": "这次实验我们永不改变方案。", "explanation": "这里应该用〈暂时不〉。永不表示永远不，与“这次实验”的暂时性安排矛盾。"}, {"text": "这个消息可能永不是真的。", "explanation": "这里应该用〈可能不〉。永不语气绝对，与表示推测的“可能”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永不", "is_correct": true, "explanation": "正确：永不表示永远不会，与服务承诺的坚定态度相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙，不能修饰“让人失望”，与语境不符。"}, {"text": "尽快", "is_correct": false, "explanation": "语义：“尽快”表示尽早，与“让人失望”的结果搭配不当。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”用于叮嘱、祈使句，不能用在陈述句“服务……让人失望”里。"}], "explanations": {"永不": "正确：永不表示永远不会，与服务承诺的坚定态度相符。", "赶紧": "语义：“赶紧”表示急忙，不能修饰“让人失望”，与语境不符。", "尽快": "语义：“尽快”表示尽早，与“让人失望”的结果搭配不当。", "千万": "语法：“千万”用于叮嘱、祈使句，不能用在陈述句“服务……让人失望”里。"}, "sentence_index": 6, "correct_answer": "永不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司有时永不裁员。", "explanation": "这里应该用〈不〉，说有时不裁员。永不表示绝对、始终不，与表示不定时间的有时矛盾。"}, {"text": "这家公司刚刚永不裁员。", "explanation": "这里应该用〈不再〉，说不再裁员。永不是长期的绝对承诺，刚刚发生的变化应说不再。"}, {"text": "这家公司差点永不裁员了。", "explanation": "这里应该用〈不〉，说差点不裁员了。永不是绝对的否定，与表示几乎发生的差点矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她永不后悔了自己的决定。", "corrected_sentence": "她永不后悔自己的决定。", "error_description": "错误：“永不”表示永远不会，不能与表示完成的“了”同用，应去掉“了”，说“永不后悔自己的决定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们永不不把客户的信息泄露出去。", "corrected_sentence": "我们永不把客户的信息泄露出去。", "error_description": "错误：“永不”本身已含否定，前面又加“不”，形成双重否定，应去掉多余的“不”，说“永不把客户的信息泄露出去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
