INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88299, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "登记是把名字和事情写在本子上，让别人知道。", "primary_collocate": null, "pronunciation": "dēng jì", "ipa": "təŋ⁵⁵ tɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "他把自己的名字登记在表上。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想参加比赛的同学请来登记。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经登记好了，明天就能去。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有人在登记来的客人。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去学校登记了孩子的名字。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人来图书馆都要登记。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登记的时候，请写清楚电话。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家酒店要求客人登记护照。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把东西登记一下，别忘了。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去前台登记了自己的名字和电话。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登记了", "label": "体标"}, {"form": "登记过", "label": "体标"}, {"form": "登记登记", "label": "重叠"}], "register": "中性", "sense_fingerprint": "登记：把名字和事情写在本子上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把名字和事情写在本子上，让别人知道。正确答案。"}, {"text": "等级", "is_correct": false, "explanation": "děngjí（第三声、第二声）与 dēngjì（第一声、第四声）声调不同，意思是等级。"}, {"text": "登基", "is_correct": false, "explanation": "dēngjī（第一声、第一声）与 dēngjì 第二个音节声调不同（jī 与 jì），意思是帝王即位。"}, {"text": "登机", "is_correct": false, "explanation": "dēngjī 第二个音节 jī（第一声）与 jì（第四声）声调不同，意思是上飞机。"}], "explanations": {"登记": "登记：把名字和事情写在本子上，让别人知道。正确答案。", "等级": "děngjí（第三声、第二声）与 dēngjì（第一声、第四声）声调不同，意思是等级。", "登基": "dēngjī（第一声、第一声）与 dēngjì 第二个音节声调不同（jī 与 jì），意思是帝王即位。", "登机": "dēngjī 第二个音节 jī（第一声）与 jì（第四声）声调不同，意思是上飞机。"}, "sentence_index": null, "correct_answer": "登记"}, "level_3": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把名字写在表上，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是加热，名字不能被烧在表上。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“在表上”搭配，也不能用于名字。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，句中的名字与此不相关。"}], "explanations": {"登记": "登记：把名字写在表上，符合句意。", "烧": "语义：“烧”是加热，名字不能被烧在表上。", "唱": "搭配：“唱”不能与“在表上”搭配，也不能用于名字。", "煮": "语义：“煮”是加热食物，句中的名字与此不相关。"}, "sentence_index": 0, "correct_answer": "登记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这个单词登记在脑子里。", "explanation": "这里应该用〈记住〉。登记是把事项写在本子上让别人知道，记在脑子里要用〈记住〉。"}, {"text": "妈妈在厨房里登记了一桌好菜。", "explanation": "这里应该用〈做〉。登记指把事项写在本子上让别人知道，做菜要用〈做〉。"}, {"text": "他登记了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉（讲笑话）。登记指写下事项让别人知道，不能用于讲笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把信息写下来，符合“……的时候，请写清楚电话”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与登记的情境无关，句中要求写清楚电话，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“写清楚电话”的要求不相关，句意不通。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死了，与“写清楚电话”的办事情境无关，句意不通。"}], "explanations": {"登记": "登记：把信息写下来，符合“……的时候，请写清楚电话”的语境。", "吃": "语义：“吃”与登记的情境无关，句中要求写清楚电话，句意不通。", "睡觉": "语义：“睡觉”与“写清楚电话”的要求不相关，句意不通。", "去世": "语义：“去世”指人死了，与“写清楚电话”的办事情境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "登记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇小说终于登记在杂志上了。", "explanation": "这里应该用〈发表〉。登记指把事项写在本子上让别人知道，作品公开刊出要用〈发表〉。"}, {"text": "他一生气就登记脾气。", "explanation": "这里应该用〈发〉（发脾气）。登记指写下事项让别人知道，不能用来表示发泄情绪。"}, {"text": "她登记了一副眼镜。", "explanation": "这里应该用〈戴〉（戴眼镜）。登记指写下事项让别人知道，不能用来表示佩戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天去前台登记过。", "corrected_sentence": "我明天去前台登记。", "error_description": "错误：“登记过”。正确：“登记”。“明天”指未来，动作尚未发生，不能用“过”表示已经发生的经历或动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把课程登记了好。", "corrected_sentence": "我已经把课程登记好了。", "error_description": "错误：“登记了好”。正确：“登记好了”。结果补语“好”应紧跟动词“登记”，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
