INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过来是从那边走到我这边来。", "primary_collocate": null, "pronunciation": "guò lái", "ipa": "kuɔ˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "你从那边过来，我在这边等你。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥那边的人慢慢过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他马上就过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路那边有一个人正在过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们什么时候过来？", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这边，你过来吧。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你过来的时候，请给我买杯水。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的孩子都过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河那边的老人慢慢地过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从学校过来，要二十分钟。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过来了", "label": "体标"}, {"form": "过来过", "label": "体标"}, {"form": "過來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "过来|动词|从那边走到我这边来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来”指朝说话人这边移动，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”必须带受事宾语，“从那边扔”不成句。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“我在这边等你”的语境矛盾。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”不能表示移动，句意不通。"}], "explanations": {"过来": "正确：“过来”指朝说话人这边移动，符合句意。", "扔": "配价：“扔”必须带受事宾语，“从那边扔”不成句。", "睡觉": "语义：“睡觉”与“我在这边等你”的语境矛盾。", "生气": "语义：“生气”不能表示移动，句意不通。"}, "sentence_index": 0, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我要过来郊外玩。", "explanation": "这里应该用〈去〉。去郊外是离开说话人所在的地方，“过来”只表示朝说话人所在处移动。"}, {"text": "我一听就明白过来了。", "explanation": "这里的“过来”是“醒悟、明白”的义项，不指朝说话人方向移动。"}, {"text": "这件事我想了很久才想过来。", "explanation": "这里的“过来”是“想通、领悟”的义项，不指位置移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“你过来的时候”指对方来到说话人处，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭的时候”与“请给我买水”的语境不合。"}, {"text": "滚", "is_correct": false, "explanation": "语域：“滚”是粗鲁的说法，不适合用于请人帮忙的句子。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔的时候”与请人买水的语境矛盾。"}], "explanations": {"过来": "正确：“你过来的时候”指对方来到说话人处，符合句意。", "哭": "语义：“哭的时候”与“请给我买水”的语境不合。", "滚": "语域：“滚”是粗鲁的说法，不适合用于请人帮忙的句子。", "摔": "语义：“摔的时候”与请人买水的语境矛盾。"}, "sentence_index": 6, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么难的题，他一下子想不过来。", "explanation": "这里的“过来”构成可能补语“想不过来”，表示想不清、想不完，不指朝说话人方向移动。"}, {"text": "那个孩子的情绪终于缓过来了。", "explanation": "这里的“过来”是“恢复平静、缓和”的义项，不指朝说话人方向移动。"}, {"text": "这个词翻译过来，就是“朋友”的意思。", "explanation": "这里的“过来”是“转换、译成”的义项，不指朝说话人方向移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天过来过。", "corrected_sentence": "他明天过来。", "error_description": "错误：“明天过来过”；正确：“明天过来”。“过”表示过去的经历，不能和“明天”这样的将来时间一起用，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你过来地时候，我正在做饭。", "corrected_sentence": "你过来的时候，我正在做饭。", "error_description": "错误：「过来地时候」；正确：「过来的时候」。「地」用于修饰动词或形容词作状语，「时候」是名词，前面的修饰语须用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
