INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处向说话人所在的位置移动。", "primary_collocate": null, "pronunciation": "guò lái", "ipa": "kuɔ˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "你快过来，我给你看一个东西。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你过来一下，我有话要说。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫我过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从那边过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见我，就过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能过来帮我拿一下吗？", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在门口叫我：“过来吃饭！”", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别站在那里，过来坐吧。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想过来看看我们的新家。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人过来，不要带别人。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过来了", "label": "体标"}, {"form": "过来过", "label": "体标"}, {"form": "過來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "过来|动词|从别处向说话人所在的位置移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来”表示朝说话人所在处移动，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“给你看东西”的语境不合，句意不通。"}, {"text": "滚", "is_correct": false, "explanation": "语域：“滚”是粗鲁的驱赶语，与请对方过来看东西的语气不合。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”必须带受事宾语，“你快扔”不成句。"}], "explanations": {"过来": "正确：“过来”表示朝说话人所在处移动，符合句意。", "哭": "语义：“哭”与“给你看东西”的语境不合，句意不通。", "滚": "语域：“滚”是粗鲁的驱赶语，与请对方过来看东西的语气不合。", "扔": "配价：“扔”必须带受事宾语，“你快扔”不成句。"}, "sentence_index": 0, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昏迷了两天，终于醒过来了。", "explanation": "这里的“过来”是“恢复到正常状态”的义项，不指朝说话人方向移动。"}, {"text": "他一听就反应过来了。", "explanation": "这里的“过来”是“醒悟、明白”的义项，不指朝说话人方向移动。"}, {"text": "他把头转过来，看了我一眼。", "explanation": "这里的“过来”是“转动、改变朝向”的义项，不指朝说话人方向移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来吃饭”是叫对方到说话人处吃饭，符合句意。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”是让人离开，与叫人吃饭的语境矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”与叫人吃饭的语境不合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能直接与“吃饭”组成动词短语，“喝吃饭”不成句。"}], "explanations": {"过来": "正确：“过来吃饭”是叫对方到说话人处吃饭，符合句意。", "走开": "语义：“走开”是让人离开，与叫人吃饭的语境矛盾。", "发呆": "语义：“发呆”与叫人吃饭的语境不合。", "喝": "搭配：“喝”不能直接与“吃饭”组成动词短语，“喝吃饭”不成句。"}, "sentence_index": 6, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这篇英文翻译过来，发给了大家。", "explanation": "这里的“过来”是“转换、译成”的义项，不指朝说话人方向移动。"}, {"text": "他的病终于好过来了。", "explanation": "这里的“过来”是“恢复、好转”的义项，不指朝说话人方向移动。"}, {"text": "这么多人，我一下子记不过来。", "explanation": "这里的“过来”是“记得全、顾得上”的义项，不指位置移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你过来过一下，我在这儿。", "corrected_sentence": "请你过来一下，我在这儿。", "error_description": "错误：“过来过一下”；正确：“过来一下”。请求别人做事时不能用表示经历的“过”，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快过来过，我在这儿等你。", "corrected_sentence": "快过来，我在这儿等你。", "error_description": "错误：“过来过”；正确：“过来”。“快”后是祈使句，不能加“过”表示经历，应直接说“快过来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
