INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "以至是说一件事太厉害了，所以有了后面的样子。", "primary_collocate": null, "pronunciation": "yǐ zhì", "ipa": "i˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "天气太热了，以至大家都不想出门。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得太快，以至鞋子都掉了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里太吵，以至我睡不着。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她高兴极了，以至说不出话来。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车堵得厉害，以至我迟到了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得太厉害，以至肚子都疼了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光太亮，以至孩子睁不开眼睛。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜太辣了，以至我喝了三杯水。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业多得很，以至他每天学到半夜。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风刮得很大，以至树都倒了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以至于", "label": "复合"}], "register": "书面语", "sense_fingerprint": "前面的情况程度很深，所以产生后面的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至（yǐ zhì）正是听到的词，表示由前因导致的结果或程度的延伸。"}, {"text": "一致", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，一致（yī zhì）的意思是相同、统一。"}, {"text": "意志", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意志（yì zhì）的意思是决心、意愿。"}, {"text": "遗志", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，遗志（yí zhì）的意思是前人留下的未完成的志愿。"}], "explanations": {"以至": "以至（yǐ zhì）正是听到的词，表示由前因导致的结果或程度的延伸。", "一致": "yǐ（第三声）与 yī（第一声）声调不同，一致（yī zhì）的意思是相同、统一。", "意志": "yǐ（第三声）与 yì（第四声）声调不同，意志（yì zhì）的意思是决心、意愿。", "遗志": "yǐ（第三声）与 yí（第二声）声调不同，遗志（yí zhì）的意思是前人留下的未完成的志愿。"}, "sentence_index": null, "correct_answer": "以至"}, "level_3": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至连接前因“天气太热了”与结果“大家都不想出门”，表示程度深导致的结果。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，而“大家都不想出门”是结果，前后颠倒。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出反面假设，与“天气太热了”导致的结果不符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“却”“也”等词呼应，这里没有相应的转折词，句子不通。"}], "explanations": {"以至": "以至连接前因“天气太热了”与结果“大家都不想出门”，表示程度深导致的结果。", "因为": "语义：“因为”引出原因，而“大家都不想出门”是结果，前后颠倒。", "否则": "语义：“否则”引出反面假设，与“天气太热了”导致的结果不符。", "虽然": "搭配：“虽然”要与“却”“也”等词呼应，这里没有相应的转折词，句子不通。"}, "sentence_index": 0, "correct_answer": "以至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了票，以至进了站。", "explanation": "这里应该用〈于是〉。买票后进站是普通的先后动作，不是程度很深所造成的结果。"}, {"text": "这条路很近，以至很难走。", "explanation": "这里应该用〈然而〉。“很近”与“很难走”是转折关系，以至只表示结果，要用“然而”。"}, {"text": "这么晚了，他以至还没回家。", "explanation": "这里应该用〈竟然〉。“还没回家”是出乎意料的情况，以至表示结果，要用“竟然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至（yǐ zhì）正是听到的词。"}, {"text": "异质", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，异质（yì zhì）的意思是性质不同。"}, {"text": "益智", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，益智（yì zhì）的意思是有益于智力发展。"}, {"text": "移置", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，移置（yí zhì）的意思是转移、搬放到别处。"}], "explanations": {"以至": "以至（yǐ zhì）正是听到的词。", "异质": "yǐ（第三声）与 yì（第四声）声调不同，异质（yì zhì）的意思是性质不同。", "益智": "yǐ（第三声）与 yì（第四声）声调不同，益智（yì zhì）的意思是有益于智力发展。", "移置": "yǐ（第三声）与 yí（第二声）声调不同，移置（yí zhì）的意思是转移、搬放到别处。"}, "sentence_index": null, "correct_answer": "以至"}, "level_3": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至连接前因“灯光太亮”与结果“孩子睁不开眼睛”，表示程度深导致的结果。"}, {"text": "除非", "is_correct": false, "explanation": "语义：“除非”表示唯一的条件，与“灯光太亮”导致的结果不符。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示让步假设，前后不构成因果，不能接在“灯光太亮”之后。"}, {"text": "无论", "is_correct": false, "explanation": "语义：“无论”表示任何条件下结果都不变，后面要接“都”等词呼应，不能引出“灯光太亮”造成的结果。"}], "explanations": {"以至": "以至连接前因“灯光太亮”与结果“孩子睁不开眼睛”，表示程度深导致的结果。", "除非": "语义：“除非”表示唯一的条件，与“灯光太亮”导致的结果不符。", "即使": "语义：“即使”表示让步假设，前后不构成因果，不能接在“灯光太亮”之后。", "无论": "语义：“无论”表示任何条件下结果都不变，后面要接“都”等词呼应，不能引出“灯光太亮”造成的结果。"}, "sentence_index": 6, "correct_answer": "以至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边走路，以至在打电话。", "explanation": "这里应该用〈同时〉。两件事同时进行要用“同时”，以至表示结果，不能这样连接。"}, {"text": "这不是我的错，以至是你的错。", "explanation": "这里应该用〈而是〉。否定后再肯定另一方要用“而是”，以至不能这样连接。"}, {"text": "这个主意不错，以至价格有点贵。", "explanation": "这里应该用〈不过〉。前后是转折关系，要用“不过”，以至只能引出结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气很冷，所以以至大家都不敢出门。", "corrected_sentence": "天气很冷，以至大家都不敢出门。", "error_description": "“以至”前面不能再用“所以”，因为“以至”本身已经表示结果。应删去“所以”，说“天气很冷，以至大家都不敢出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提前订了票，以至春节能回家。", "corrected_sentence": "他提前订了票，以便春节能回家。", "error_description": "“以至”表示由前面的情况导致的程度或结果，不能表示目的；“提前订票”的目的是“春节能回家”，应用“以便”。应把“以至”改为“以便”，说“他提前订了票，以便春节能回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
