INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88304, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示由于前面的情况而产生的结果，或表示程度、范围的延伸。", "primary_collocate": null, "pronunciation": "yǐ zhì", "ipa": "i˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他太累了，以至一躺下就睡着了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，以至路上都是水。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话声音太小，以至我没听清。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年城市变化很大，以至我都不认识路了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事从学生到老师，以至校长都知道了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很忙，以至忘了吃午饭。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看书看得太入迷，以至错过了火车。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格涨得太快，以至很多人不买了。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太好看了，以至我看了三遍。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩得太高兴，以至忘了回家。", "target_word": "以至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以至于", "label": "复合"}], "register": "书面语", "sense_fingerprint": "连接前因与后果，或表示范围、程度的延伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至（yǐ zhì）正是听到的词，表示由前因导致的结果或程度的延伸。"}, {"text": "一致", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，一致（yī zhì）的意思是相同、统一。"}, {"text": "意志", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意志（yì zhì）的意思是决心、意愿。"}, {"text": "遗志", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，遗志（yí zhì）的意思是前人留下的未完成的志愿。"}], "explanations": {"以至": "以至（yǐ zhì）正是听到的词，表示由前因导致的结果或程度的延伸。", "一致": "yǐ（第三声）与 yī（第一声）声调不同，一致（yī zhì）的意思是相同、统一。", "意志": "yǐ（第三声）与 yì（第四声）声调不同，意志（yì zhì）的意思是决心、意愿。", "遗志": "yǐ（第三声）与 yí（第二声）声调不同，遗志（yí zhì）的意思是前人留下的未完成的志愿。"}, "sentence_index": null, "correct_answer": "以至"}, "level_3": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至连接前因“太累了”与结果“一躺下就睡着了”，表示程度深导致的结果。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，而“一躺下就睡着了”是结果，前后颠倒。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示目的，睡着不能是“太累”的目的。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“却”“但”等词呼应，这里后半句没有转折词，句子不通。"}], "explanations": {"以至": "以至连接前因“太累了”与结果“一躺下就睡着了”，表示程度深导致的结果。", "因为": "语义：“因为”引出原因，而“一躺下就睡着了”是结果，前后颠倒。", "以便": "语义：“以便”表示目的，睡着不能是“太累”的目的。", "虽然": "搭配：“虽然”要与“却”“但”等词呼应，这里后半句没有转折词，句子不通。"}, "sentence_index": 0, "correct_answer": "以至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了菜，以至做了饭。", "explanation": "这里应该用〈于是〉。以至表示程度很深所造成的结果，买菜后做饭这种先后动作要用“于是”。"}, {"text": "他很努力，以至没考好。", "explanation": "这里应该用〈可是〉。“很努力”与“没考好”是转折关系，以至表示结果，会说成因果，要用“可是”。"}, {"text": "他能用流利的汉语聊天，以至他学得很好。", "explanation": "这里应该用〈可见〉。以至引出结果，由已知情况推出结论要用“可见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至（yǐ zhì）正是听到的词。"}, {"text": "异质", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，异质（yì zhì）的意思是性质不同。"}, {"text": "益智", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，益智（yì zhì）的意思是有益于智力发展。"}, {"text": "移置", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，移置（yí zhì）的意思是转移、搬放到别处。"}], "explanations": {"以至": "以至（yǐ zhì）正是听到的词。", "异质": "yǐ（第三声）与 yì（第四声）声调不同，异质（yì zhì）的意思是性质不同。", "益智": "yǐ（第三声）与 yì（第四声）声调不同，益智（yì zhì）的意思是有益于智力发展。", "移置": "yǐ（第三声）与 yí（第二声）声调不同，移置（yí zhì）的意思是转移、搬放到别处。"}, "sentence_index": null, "correct_answer": "以至"}, "level_3": {"options": [{"text": "以至", "is_correct": true, "explanation": "以至连接前因“看书看得太入迷”与结果“错过了火车”，表示程度深导致的结果。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“入迷”导致“错过火车”的因果关系不符。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出反面假设，与前面的因果关系不符。"}, {"text": "无论", "is_correct": false, "explanation": "语义：“无论”表示任何条件下结果都不变，要与“都”呼应，不能引出“看书入迷”造成的结果。"}], "explanations": {"以至": "以至连接前因“看书看得太入迷”与结果“错过了火车”，表示程度深导致的结果。", "尽管": "语义：“尽管”表示让步，与“入迷”导致“错过火车”的因果关系不符。", "否则": "语义：“否则”引出反面假设，与前面的因果关系不符。", "无论": "语义：“无论”表示任何条件下结果都不变，要与“都”呼应，不能引出“看书入迷”造成的结果。"}, "sentence_index": 6, "correct_answer": "以至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边做饭，以至在听音乐。", "explanation": "这里应该用〈同时〉。两件事同时进行要用“同时”，以至表示结果，不能这样连接。"}, {"text": "他不是老师，以至是学生。", "explanation": "这里应该用〈而是〉。否定后再肯定另一方要用“而是”，以至不表示这种对比。"}, {"text": "他把钥匙放好，以至下次能找到。", "explanation": "这里应该用〈以便〉。“放好钥匙”的目的是下次能找到，表示目的要用“以便”，不能用“以至”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨下得太大了，所以以至我们都没法出门。", "corrected_sentence": "雨下得太大了，以至我们都没法出门。", "error_description": "“以至”本身已表示由前面的情况导致的结果，前面不能再用“所以”。应删去“所以”，说“雨下得太大了，以至我们都没法出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把作业提前写完，以至周末能出去玩。", "corrected_sentence": "他把作业提前写完，以便周末能出去玩。", "error_description": "“以至”表示结果或程度，不能表示目的；“提前写完作业”的目的是“周末能出去玩”，应用“以便”。应把“以至”改为“以便”，说“他把作业提前写完，以便周末能出去玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假象", "is_correct": true, "explanation": "正确：“真相”与“假象”是反义词。真相是一件事真正的样子，假象是表面的假情况。"}, {"text": "图画", "is_correct": false, "explanation": "“图画”指用线条或颜色描绘的作品，与“真相”没有反义关系。"}, {"text": "歌曲", "is_correct": false, "explanation": "“歌曲”指可以唱的作品，与“真相”不构成对立关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”指天然的水道，与“真相”没有反义关系。"}], "correct_answer": "假象", "explanations": {"假象": "正确：“真相”与“假象”是反义词。真相是一件事真正的样子，假象是表面的假情况。", "图画": "“图画”指用线条或颜色描绘的作品，与“真相”没有反义关系。", "歌曲": "“歌曲”指可以唱的作品，与“真相”不构成对立关系。", "河流": "“河流”指天然的水道，与“真相”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假象", "is_correct": true, "explanation": "正确：“真相”与“假象”是反义词，前者是真实的样子，后者是表面的假象。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”指岩石的块状物，与“真相”没有反义关系。"}, {"text": "火车", "is_correct": false, "explanation": "“火车”指铁路上行驶的交通工具，与“真相”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”指房屋上透光通风的部分，与“真相”没有反义关系。"}], "correct_answer": "假象", "explanations": {"假象": "正确：“真相”与“假象”是反义词，前者是真实的样子，后者是表面的假象。", "石头": "“石头”指岩石的块状物，与“真相”没有反义关系。", "火车": "“火车”指铁路上行驶的交通工具，与“真相”没有反义关系。", "窗户": "“窗户”指房屋上透光通风的部分，与“真相”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真相是一件事真的是怎么样的。", "primary_collocate": null, "pronunciation": "zhēn xiàng", "ipa": "ʈʂən˥ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "看了视频，我才明白事情的真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着说出了真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真相有时候让人难过。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了找到真相，找了很多人。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的真相很简单。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问了很多人，想弄清真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有看到当时的真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一直不告诉我真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的最后，真相终于出现了。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说谎的人怕别人知道真相。", "target_word": "真相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "事实真相", "label": "复合"}, {"form": "真相大白", "label": "成语"}], "register": "中性", "sense_fingerprint": "真相·名词·一件事真正的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真相", "is_correct": true, "explanation": "正确：真相，zhēn xiàng，指一件事真正的样子。"}, {"text": "真想", "is_correct": false, "explanation": "真想 zhēn xiǎng 与 zhēn xiàng 第二个音节声调不同（第三声与第四声），意思是“真的想”。"}, {"text": "针线", "is_correct": false, "explanation": "针线 zhēn xiàn 与 zhēn xiàng 第二个音节韵尾不同（n 与 ng），意思是缝纫用的针和线。"}, {"text": "真香", "is_correct": false, "explanation": "真香 zhēn xiāng 与 zhēn xiàng 第二个音节声调不同（第一声与第四声），意思是食物很香。"}], "explanations": {"真相": "正确：真相，zhēn xiàng，指一件事真正的样子。", "真想": "真想 zhēn xiǎng 与 zhēn xiàng 第二个音节声调不同（第三声与第四声），意思是“真的想”。", "针线": "针线 zhēn xiàn 与 zhēn xiàng 第二个音节韵尾不同（n 与 ng），意思是缝纫用的针和线。", "真香": "真香 zhēn xiāng 与 zhēn xiàng 第二个音节声调不同（第一声与第四声），意思是食物很香。"}, "sentence_index": null, "correct_answer": "真相"}, "level_3": {"options": [{"text": "真相", "is_correct": true, "explanation": "正确：“明白事情的真相”指弄清事情真正的样子，与“看了视频”的语境相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：事情没有味道，“事情的味道”与“我才明白”的语境不相符。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是天气的指标，不是事情的内容，不能“明白”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是人或物的重量，不能说“事情的体重”。"}], "explanations": {"真相": "正确：“明白事情的真相”指弄清事情真正的样子，与“看了视频”的语境相符。", "味道": "语义：事情没有味道，“事情的味道”与“我才明白”的语境不相符。", "气温": "语义：气温是天气的指标，不是事情的内容，不能“明白”。", "体重": "搭配：“体重”是人或物的重量，不能说“事情的体重”。"}, "sentence_index": 0, "correct_answer": "真相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们为了借真相，找了很多人。", "explanation": "这里应该用〈钱〉。“借”的对象是钱物，真相是事实，不能被借。"}, {"text": "他们为了修真相，找了很多人。", "explanation": "这里应该用〈车〉。“修”的对象是车、机器等实物，真相不能被修。"}, {"text": "他们为了喝真相，找了很多人。", "explanation": "这里应该用〈水〉。“喝”的对象是饮料或水，真相不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真相", "is_correct": true, "explanation": "正确：“没有看到当时的真相”指没人见到事情真正的样子，语境相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看到”不能用于“声音”，声音要用“听到”。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”要用“听到”或“感觉”，不能说“看到”。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是用鼻子闻的，与“看到”矛盾，也不符合语境。"}], "explanations": {"真相": "正确：“没有看到当时的真相”指没人见到事情真正的样子，语境相符。", "声音": "搭配：“看到”不能用于“声音”，声音要用“听到”。", "心跳": "搭配：“心跳”要用“听到”或“感觉”，不能说“看到”。", "气味": "语义：气味是用鼻子闻的，与“看到”矛盾，也不符合语境。"}, "sentence_index": 6, "correct_answer": "真相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一直在吃真相。", "explanation": "这里应该用〈饭〉。“吃”的对象是食物，真相不能吃。"}, {"text": "她为家人付出了真相。", "explanation": "这里应该用〈真心〉。“付出”用于感情或精力，真相不能被付出。"}, {"text": "他把真相洗好了。", "explanation": "这里应该用〈相片〉。“洗”用于照片，不能用于真相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子终于说出了一条真相。", "corrected_sentence": "孩子终于说出了一个真相。", "error_description": "量词错误：“真相”是抽象名词，应该用“个”，不能用“条”。正确的说法是“一个真相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些真相们都让人难过。", "corrected_sentence": "这些真相都让人难过。", "error_description": "“们”只用于指人，“真相”是事物，不能加“们”。正确的说法是“这些真相”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
