INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "依法成立、能享有权利并承担义务的组织。", "primary_collocate": null, "pronunciation": "fǎ rén", "ipa": "fa˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "法人是依法成立的组织。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法人享有权利，也要承担义务。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司依法成立，是独立的法人。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法人要按时交税，这是它的义务。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请成为法人，需要先准备材料。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法人有自己的财产，和个人的分开。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会已经登记为法人了。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法人违反法律，也要承担责任。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和公司都是常见的法人。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成立法人需要符合法律的规定。", "target_word": "法人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法人代表", "label": "复合"}, {"form": "企业法人", "label": "复合"}], "register": "书面", "sense_fingerprint": "依法成立、享有权利并承担义务的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法人", "is_correct": true, "explanation": "法人：依法成立、享有权利并承担义务的组织，符合句意。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是依法成立的组织。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是组织，不能说“依法成立”。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：“依法成立”修饰的是组织或团体，“作品”不能这样搭配。"}], "explanations": {"法人": "法人：依法成立、享有权利并承担义务的组织，符合句意。", "动物": "语义：动物不是依法成立的组织。", "天气": "语义：天气不是组织，不能说“依法成立”。", "作品": "搭配：“依法成立”修饰的是组织或团体，“作品”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "法人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的小猫是法人，每天都要吃鱼。", "explanation": "这里应该用〈宠物〉。法人是依法成立的组织，小猫是动物，不能说它是法人。"}, {"text": "法人要按时上班，这是他的义务。", "explanation": "这里应该用〈员工〉。法人是组织，不会“按时上班”，这里应说员工。"}, {"text": "这棵树是法人，每年春天都会开花。", "explanation": "这里应该用〈植物〉。法人是依法成立的组织，树是植物，不能说它是法人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法人", "is_correct": true, "explanation": "法人：依法登记成立的组织，符合“已经登记为”的语境。"}, {"text": "学生", "is_correct": false, "explanation": "语义：协会不能被登记为学生，学生指个人。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是个人，协会不能被登记为游客。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“登记为”后接的应是身份或法律主体，“病人”不能被登记。"}], "explanations": {"法人": "法人：依法登记成立的组织，符合“已经登记为”的语境。", "学生": "语义：协会不能被登记为学生，学生指个人。", "游客": "语义：游客是个人，协会不能被登记为游客。", "病人": "搭配：“登记为”后接的应是身份或法律主体，“病人”不能被登记。"}, "sentence_index": 6, "correct_answer": "法人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的法人每天都检查作业。", "explanation": "这里应该用〈家长〉。法人是组织，不能用来指检查孩子作业的家长。"}, {"text": "这条河流是法人，每天都会流动。", "explanation": "这里应该用〈自然景物〉。法人是依法成立的组织，河流是自然物，不能说它是法人。"}, {"text": "这本书的法人是他。", "explanation": "这里应该用〈作者〉。法人是组织，不能用来指写书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校依法成立，已经很法人了。", "corrected_sentence": "这所学校依法成立，已经是法人了。", "error_description": "词类错误：“法人”是名词，不能被“很”修饰，应用“是”作谓语，说“已经是法人了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "依法成立法人要遵守法律。", "corrected_sentence": "依法成立的法人要遵守法律。", "error_description": "结构助词错误：“依法成立”修饰“法人”时要用“的”，应说“依法成立的法人”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
