INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "行政区划单位，隶属于县。", "primary_collocate": null, "pronunciation": "xiāng", "ipa": "ɕjɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这个乡有三千多人。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县下面有很多乡。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们乡在县的北边。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乡离县城四十公里。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全县一共有十二个乡。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个乡很小，只有两个村。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们乡有一所小学。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乡的路修好了。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们乡的老师。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里的每个乡都有一个医院。", "target_word": "乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乡村", "label": "复合词"}, {"form": "乡下", "label": "复合词"}, {"form": "鄉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "县下面的行政区划单位，如这个乡有三个村", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88310, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乡", "is_correct": true, "explanation": "正确答案：乡（xiāng），指县以下的行政区划单位。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念或想要。"}, {"text": "像", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是相似。"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 xiāng 韵尾不同（-n 与 -ng），意思是先后的先。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 xiāng 声母不同（j 与 x），意思是江河。"}], "explanations": {"乡": "正确答案：乡（xiāng），指县以下的行政区划单位。", "想": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念或想要。", "像": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是相似。", "先": "xiān 与 xiāng 韵尾不同（-n 与 -ng），意思是先后的先。", "江": "jiāng 与 xiāng 声母不同（j 与 x），意思是江河。"}, "sentence_index": null, "correct_answer": "乡"}, "level_3": {"options": [{"text": "乡", "is_correct": true, "explanation": "正确：乡是行政单位，可以有三千多人口。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不是行政单位，不能说有三千多人口。"}, {"text": "河", "is_correct": false, "explanation": "语义：河流不是人口所在的单位，句子在说人口。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”不能与“有三千多人”搭配，人口只能归属于地区或单位。"}], "explanations": {"乡": "正确：乡是行政单位，可以有三千多人口。", "山": "语义：山不是行政单位，不能说有三千多人口。", "河": "语义：河流不是人口所在的单位，句子在说人口。", "书": "搭配：“书”不能与“有三千多人”搭配，人口只能归属于地区或单位。"}, "sentence_index": 0, "correct_answer": "乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乡在市中心，交通很方便。", "explanation": "这里应该用〈街道〉。乡是县以下的农村行政单位，不会设在市中心；市中心的行政单位是街道。"}, {"text": "我住在这个乡的18号楼。", "explanation": "这里应该用〈小区〉。乡是行政区划单位，没有楼号；门牌楼号属于城市里的小区。"}, {"text": "这个乡比县还大，下面有好几个县。", "explanation": "这里应该用〈市〉。乡隶属于县，比县小，下面不会有县；下面有好几个县的是市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88310, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乡", "is_correct": true, "explanation": "正确答案：乡（xiāng），指县以下的行政区划单位。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。"}, {"text": "向", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是方向或朝向。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān 与 xiāng 韵尾不同（-n 与 -ng），意思是新鲜。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng 与 xiāng 声母不同（q 与 x），意思是枪支。"}], "explanations": {"乡": "正确答案：乡（xiāng），指县以下的行政区划单位。", "响": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。", "向": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是方向或朝向。", "鲜": "xiān 与 xiāng 韵尾不同（-n 与 -ng），意思是新鲜。", "枪": "qiāng 与 xiāng 声母不同（q 与 x），意思是枪支。"}, "sentence_index": null, "correct_answer": "乡"}, "level_3": {"options": [{"text": "乡", "is_correct": true, "explanation": "正确：乡可以设立小学。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能设立学校。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不能拥有学校。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能设立学校，“我们花有一所小学”不通。"}], "explanations": {"乡": "正确：乡可以设立小学。", "树": "语义：树不能设立学校。", "车": "语义：车不能拥有学校。", "花": "语义：花不能设立学校，“我们花有一所小学”不通。"}, "sentence_index": 6, "correct_answer": "乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的乡。", "explanation": "这里应该用〈老乡〉。“乡”单独不能指同乡的人，表示同乡要说“老乡”。"}, {"text": "乡下面有很多市。", "explanation": "这里应该用〈县〉。乡隶属于县，比县小，不能统辖市；是县统辖乡，不是乡统辖市。"}, {"text": "这个乡的地铁线很多。", "explanation": "这里应该用〈城市〉。乡是农村行政单位，没有地铁；地铁线多的是城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县城东边有一只乡，离我家很近。", "corrected_sentence": "县城东边有一个乡，离我家很近。", "error_description": "错误：量词“只”用错了。“只”多用于动物，乡是行政单位，应说“一个乡”，量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这乡个很大，有十几个村。", "corrected_sentence": "这个乡很大，有十几个村。", "error_description": "错误：语序错了。量词“个”应放在“这”和“乡”之间，应说“这个乡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
