INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "等级；按质量、水平划分的级别。", "primary_collocate": null, "pronunciation": "děng dì", "ipa": "təŋ²¹⁴ ti⁵¹", "syllable_count": 2, "sentences": [{"text": "这次比赛按成绩分等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶的等第不一样，价钱也不同。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每份作业都定了等第。", "target_word": "等第", "complexity_tier": "T3", "furigana": "lǎo shī gěi měi fèn zuò yè dōu dìng le děng dì", "sentence_source": "generated"}, {"text": "这家店的水果等第很高。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校考试分四个等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等第高的东西，价钱也贵。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画在比赛中得到了最高等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按质量分出东西的等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把苹果分成三个等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个等第的布料最好。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "等第：按质量水平分的级别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等第", "is_correct": true, "explanation": "等第：按质量、水平划分的级别，可以按成绩分出等第。"}, {"text": "体重", "is_correct": false, "explanation": "语义：比赛按成绩分，体重与成绩无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：比赛按成绩划分，颜色与成绩无关，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与比赛成绩无关，不能按成绩分出年龄。"}], "explanations": {"等第": "等第：按质量、水平划分的级别，可以按成绩分出等第。", "体重": "语义：比赛按成绩分，体重与成绩无关，句意不通。", "颜色": "语义：比赛按成绩划分，颜色与成绩无关，句意不通。", "年龄": "语义：年龄与比赛成绩无关，不能按成绩分出年龄。"}, "sentence_index": 0, "correct_answer": "等第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的等第很快。", "explanation": "这里应该用〈速度〉。等第表示级别，不能用来说车速的快慢。"}, {"text": "这朵花的等第很鲜艳。", "explanation": "这里应该用〈颜色〉。等第表示级别，不能用来形容花的颜色是否鲜艳。"}, {"text": "这条路的等第很宽。", "explanation": "这里应该用〈宽度〉。等第表示级别，不能用来说路的宽窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等第", "is_correct": true, "explanation": "等第：比赛中给画作评定的级别，符合“得到了最高……”的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：画作参加比赛，不可能“得到”体重。"}, {"text": "身高", "is_correct": false, "explanation": "语义：画作没有身高，句中指比赛中的评定结果。"}, {"text": "体温", "is_correct": false, "explanation": "语义：画作参加比赛，与体温无关，不能说''得到体温''。"}], "explanations": {"等第": "等第：比赛中给画作评定的级别，符合“得到了最高……”的语境。", "体重": "语义：画作参加比赛，不可能“得到”体重。", "身高": "语义：画作没有身高，句中指比赛中的评定结果。", "体温": "语义：画作参加比赛，与体温无关，不能说''得到体温''。"}, "sentence_index": 6, "correct_answer": "等第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的等第很重。", "explanation": "这里应该用〈重量〉。等第是级别，不能用来说苹果的轻重。"}, {"text": "这位老人的等第很大。", "explanation": "这里应该用〈年龄〉。等第是质量级别，不能用来说人的年龄大小。"}, {"text": "这首歌的等第很响亮。", "explanation": "这里应该用〈音量〉。等第表示级别，不能用来形容声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批米按质量分了三只等第。", "corrected_sentence": "这批米按质量分了三个等第。", "error_description": "错误：“三只等第”。正确：“三个等第”。“等第”是抽象名词，计量用“个”；“只”多用于动物等具体事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个等第最贵地。", "corrected_sentence": "这个等第最贵。", "error_description": "错误：''最贵地''。正确：''最贵''。作谓语的形容词后不加''地''。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
