INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88319, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "而言是说\"从这个人或这件事来看\"，常和\"对\"\"就\"连着用。", "primary_collocate": null, "pronunciation": "ér yán", "ipa": "ɚ˧˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "对我而言，家人比工作重要。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对学生而言，睡觉也很重要。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人而言，安静的生活最好。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小孩而言，这本书太难了。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就这件事而言，他没有错。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就价格而言，这家店很便宜。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对公司而言，这是一个好机会。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就我个人而言，我喜欢住在小城市。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子而言，玩具就是朋友。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对大家而言，今天是特别的一天。", "target_word": "而言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对……而言", "label": "固定搭配"}, {"form": "就……而言", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "跟在对／就……之后，表示从某人或某事的角度来看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而言", "is_correct": true, "explanation": "正确。“对……而言”表示从“我”的角度来说，与句首的“对我”呼应。"}, {"text": "以来", "is_correct": false, "explanation": "搭配：“以来”表示从某时起，不能接在“对我”之后引出评价角度。"}, {"text": "之后", "is_correct": false, "explanation": "语义：“之后”表示时间先后，与“对我”搭配不通，句意不成立。"}, {"text": "在于", "is_correct": false, "explanation": "搭配：“在于”表示关键所在，不能引出评价角度，“对我在于”不成立。"}], "explanations": {"而言": "正确。“对……而言”表示从“我”的角度来说，与句首的“对我”呼应。", "以来": "搭配：“以来”表示从某时起，不能接在“对我”之后引出评价角度。", "之后": "语义：“之后”表示时间先后，与“对我”搭配不通，句意不成立。", "在于": "搭配：“在于”表示关键所在，不能引出评价角度，“对我在于”不成立。"}, "sentence_index": 0, "correct_answer": "而言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对这本书而言，我们今天很累。", "explanation": "语义：“而言”要从人或事件的角度来评价，这里把“这本书”当作评价角度，“我们很累”与之无关，搭配不通。"}, {"text": "向书店而言，这本书太难了。", "explanation": "搭配：“向”不能引出评价的角度，“而言”只与“对”或“就”连用，这里用“向”搭配不当。"}, {"text": "把小孩而言，这本书太难了。", "explanation": "搭配：“把”不能引出评价的角度，“而言”只与“对”或“就”连用，应说“对小孩而言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而言", "is_correct": true, "explanation": "正确。“对……而言”表示从“公司”的角度来说，与“对公司”呼应。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示仅此而已，用于句末，不能引出评价角度，“对公司而已”不成立。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”表示时间先后，与“对公司”搭配不通，句意不成立。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”是递进连词，连接分句，不能引出评价角度，“对公司而且”不成立。"}], "explanations": {"而言": "正确。“对……而言”表示从“公司”的角度来说，与“对公司”呼应。", "而已": "语义：“而已”表示仅此而已，用于句末，不能引出评价角度，“对公司而已”不成立。", "之前": "语义：“之前”表示时间先后，与“对公司”搭配不通，句意不成立。", "而且": "搭配：“而且”是递进连词，连接分句，不能引出评价角度，“对公司而且”不成立。"}, "sentence_index": 6, "correct_answer": "而言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "照学生们而言，今天是特别的一天。", "explanation": "搭配：“照”不能引出评价的角度，“而言”前面只能是“对”或“就”，这里应改用“对”。"}, {"text": "向大家而言，今天是特别的一天。", "explanation": "搭配：“向”不能引出评价的角度，“而言”只与“对”或“就”连用，这里用“向”搭配不当。"}, {"text": "对大家而言，而言今天是特别的一天。", "explanation": "用法：“而言”只能用一次，这里重复出现，结构不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母而言，孩子的健康最重要。", "corrected_sentence": "对父母而言，孩子的健康最重要。", "error_description": "错误：漏掉了介词“对”。“而言”要与“对”或“就”连用，应为“对父母而言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对学生就而言，这个专业很有用。", "corrected_sentence": "对学生而言，这个专业很有用。", "error_description": "错误：“对”与“就”不能同时用。“对……而言”中间不加“就”，应为“对学生而言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "深", "is_correct": true, "explanation": "深与浅相对，指从上到下距离大，与“湖边的水比较浅”构成反义。"}, {"text": "宽", "is_correct": false, "explanation": "宽说左右距离大，与水的深浅不构成反义。"}, {"text": "高", "is_correct": false, "explanation": "高说由下到上距离大，与水的深浅不构成反义。"}, {"text": "远", "is_correct": false, "explanation": "远说距离长，与水的深浅不构成反义。"}], "correct_answer": "深", "explanations": {"深": "深与浅相对，指从上到下距离大，与“湖边的水比较浅”构成反义。", "宽": "宽说左右距离大，与水的深浅不构成反义。", "高": "高说由下到上距离大，与水的深浅不构成反义。", "远": "远说距离长，与水的深浅不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "深", "is_correct": true, "explanation": "深与浅相对，指从上到下距离大，与“岸边的水很浅”构成反义。"}, {"text": "快", "is_correct": false, "explanation": "快说速度高，与水的深浅不构成反义。"}, {"text": "长", "is_correct": false, "explanation": "长说距离或时间大，与水的深浅不构成反义。"}, {"text": "热", "is_correct": false, "explanation": "热说温度高，与水的深浅不构成反义。"}], "correct_answer": "深", "explanations": {"深": "深与浅相对，指从上到下距离大，与“岸边的水很浅”构成反义。", "快": "快说速度高，与水的深浅不构成反义。", "长": "长说距离或时间大，与水的深浅不构成反义。", "热": "热说温度高，与水的深浅不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "浅是从上到下不深，水不多。", "primary_collocate": null, "pronunciation": "qiǎn", "ipa": "tɕʰjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条河很浅，小孩可以走过去。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池子的水太浅，鱼游不开。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池一边深，一边浅。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边的水比较浅，能看见底。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水太浅，鸭子游不起来。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小溪浅得可以看见石头。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水太浅，大船开不进来。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口井不深，水也很浅。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天河水很浅，船过不去。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岸边的水很浅，孩子可以在这里玩。", "target_word": "浅", "complexity_tier": "T3", "furigana": "àn biān de shuǐ hěn qiǎn, hái zi kě yǐ zài zhè lǐ wán", "sentence_source": "generated"}], "morphological_forms": [{"form": "浅浅", "label": "重叠"}, {"form": "淺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水从上到下不深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浅", "is_correct": true, "explanation": "正确答案：浅 qiǎn（第三声），指从上到下距离小、水不深。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiǎn（第三声）声调不同，意思是前面。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiǎn（第三声）声调不同，意思是钱。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是一千。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是欠（钱）。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是减少。"}], "explanations": {"浅": "正确答案：浅 qiǎn（第三声），指从上到下距离小、水不深。", "前": "qián（第二声）与 qiǎn（第三声）声调不同，意思是前面。", "钱": "qián（第二声）与 qiǎn（第三声）声调不同，意思是钱。", "千": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是一千。", "欠": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是欠（钱）。", "减": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是减少。"}, "sentence_index": null, "correct_answer": "浅"}, "level_3": {"options": [{"text": "浅", "is_correct": true, "explanation": "浅：从上到下距离小，符合“小孩可以走过去”的语境。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”指从上到下距离大，河深则小孩无法走过去，与句意矛盾。"}, {"text": "急", "is_correct": false, "explanation": "语义：“急”说水流快，与河水深浅无关，不能解释小孩可以走过去。"}, {"text": "高", "is_correct": false, "explanation": "搭配：说水的深浅用“深”或“浅”，不说“很高”。"}], "explanations": {"浅": "浅：从上到下距离小，符合“小孩可以走过去”的语境。", "深": "语义：“深”指从上到下距离大，河深则小孩无法走过去，与句意矛盾。", "急": "语义：“急”说水流快，与河水深浅无关，不能解释小孩可以走过去。", "高": "搭配：说水的深浅用“深”或“浅”，不说“很高”。"}, "sentence_index": 0, "correct_answer": "浅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块冰很浅，人不能走上去。", "explanation": "这里应该用〈薄〉。浅指从上到下距离小、水不深；冰、纸等的厚度要用薄。"}, {"text": "这堵墙很浅，我一跳就能翻过去。", "explanation": "这里应该用〈低〉。浅指从上到下距离小；墙、桌子等的高度要用低。"}, {"text": "这条小路很浅，只能走一个人。", "explanation": "这里应该用〈窄〉。浅指从上到下距离小；路的左右宽度要用窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "浅", "is_correct": true, "explanation": "正确答案：浅 qiǎn（第三声），指从上到下距离小、水不深。"}, {"text": "牵", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是牵（拉）。"}, {"text": "签", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是签（字）。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是抱歉。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是剪。"}], "explanations": {"浅": "正确答案：浅 qiǎn（第三声），指从上到下距离小、水不深。", "牵": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是牵（拉）。", "签": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是签（字）。", "歉": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是抱歉。", "剪": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是剪。"}, "sentence_index": null, "correct_answer": "浅"}, "level_3": {"options": [{"text": "浅", "is_correct": true, "explanation": "浅：水从上到下不深，所以大船开不进来，符合句意。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，与船能不能开进来无关。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说卫生状况，水干净不会让大船开不进来。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”说声音大，与水的深浅、船能否开进来无关。"}], "explanations": {"浅": "浅：水从上到下不深，所以大船开不进来，符合句意。", "贵": "语义：“贵”说价格，与船能不能开进来无关。", "干净": "语义：“干净”说卫生状况，水干净不会让大船开不进来。", "吵": "语义：“吵”说声音大，与水的深浅、船能否开进来无关。"}, "sentence_index": 6, "correct_answer": "浅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很浅，只有三层。", "explanation": "这里应该用〈矮〉。浅指从上到下距离小、水不深；楼房的高矮要用矮。"}, {"text": "这根铁丝很浅，一拉就断了。", "explanation": "这里应该用〈细〉。浅指从上到下距离小；铁丝等的粗细要用细。"}, {"text": "这段时间很浅，还不够准备。", "explanation": "这里应该用〈短〉。浅指从上到下距离小；时间的长短要用短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片浅滩很浅得能看见鱼。", "corrected_sentence": "这片浅滩浅得能看见鱼。", "error_description": "错误：“很浅得”同时用“很”和“得”标记程度。正确：“浅得能看见鱼”，用“得”引出程度补语时不再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池子的水浅很。", "corrected_sentence": "池子的水很浅。", "error_description": "错误：程度副词“很”放在了形容词“浅”之后。正确：“很浅”，程度副词应放在形容词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "深", "is_correct": true, "explanation": "深与浅相对，指从表面到底部距离大，与“雪很浅”构成反义。"}, {"text": "宽", "is_correct": false, "explanation": "宽说左右距离大，与从表面到底部的距离不构成反义。"}, {"text": "远", "is_correct": false, "explanation": "远说空间距离长，与深浅不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮说光线强，与深浅不构成反义。"}], "correct_answer": "深", "explanations": {"深": "深与浅相对，指从表面到底部距离大，与“雪很浅”构成反义。", "宽": "宽说左右距离大，与从表面到底部的距离不构成反义。", "远": "远说空间距离长，与深浅不构成反义。", "亮": "亮说光线强，与深浅不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
