INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从表面到底部距离小的；不深。", "primary_collocate": null, "pronunciation": "qiǎn", "ipa": "tɕʰjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个抽屉太浅，放不下大书。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手上的伤口不浅，要去医院。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盘子很浅，不能装太多汤。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪很浅，才到脚面。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的坑很浅，不用担心。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的鞋口很浅，跑步会掉。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆太浅，树根长不开。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙滩上的脚印很浅，风一吹就没了。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子很浅，放不下这个花瓶。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把种子埋得太浅，鸟都吃掉了。", "target_word": "浅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浅浅", "label": "重叠"}, {"form": "淺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体从表面到底部距离小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浅", "is_correct": true, "explanation": "正确答案：浅 qiǎn（第三声），指从表面到底部距离小。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiǎn（第三声）声调不同，意思是前面。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiǎn（第三声）声调不同，意思是钱。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是一千。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是欠（钱）。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是减少。"}], "explanations": {"浅": "正确答案：浅 qiǎn（第三声），指从表面到底部距离小。", "前": "qián（第二声）与 qiǎn（第三声）声调不同，意思是前面。", "钱": "qián（第二声）与 qiǎn（第三声）声调不同，意思是钱。", "千": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是一千。", "欠": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是欠（钱）。", "减": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是减少。"}, "sentence_index": null, "correct_answer": "浅"}, "level_3": {"options": [{"text": "浅", "is_correct": true, "explanation": "浅：从表面到底部距离小，符合“放不下大书”的语境。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：说抽屉的深浅用“浅”或“深”，不用“亮”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与抽屉能否放下大书无关。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”说质地，与抽屉的深浅、能否放书无关。"}], "explanations": {"浅": "浅：从表面到底部距离小，符合“放不下大书”的语境。", "亮": "搭配：说抽屉的深浅用“浅”或“深”，不用“亮”。", "甜": "语义：“甜”说味道，与抽屉能否放下大书无关。", "软": "语义：“软”说质地，与抽屉的深浅、能否放书无关。"}, "sentence_index": 0, "correct_answer": "浅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很浅，刚好够不到柜子。", "explanation": "这里应该用〈矮〉。浅指从表面到底部距离小；人的身高要用矮。"}, {"text": "这根绳子很浅，不够绑这个箱子。", "explanation": "这里应该用〈短〉。浅指从表面到底部距离小；绳子的长度要用短。"}, {"text": "这根针很浅，线都穿不过去。", "explanation": "这里应该用〈细〉。浅指从表面到底部距离小；针、线等的粗细要用细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "浅", "is_correct": true, "explanation": "正确答案：浅 qiǎn（第三声），指从表面到底部距离小。"}, {"text": "牵", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是牵（拉）。"}, {"text": "签", "is_correct": false, "explanation": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是签（字）。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是抱歉。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是剪。"}], "explanations": {"浅": "正确答案：浅 qiǎn（第三声），指从表面到底部距离小。", "牵": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是牵（拉）。", "签": "qiān（第一声）与 qiǎn（第三声）声调不同，意思是签（字）。", "歉": "qiàn（第四声）与 qiǎn（第三声）声调不同，意思是抱歉。", "剪": "jiǎn 与 qiǎn 声母不同（j 与 q），声调相同，意思是剪。"}, "sentence_index": null, "correct_answer": "浅"}, "level_3": {"options": [{"text": "浅", "is_correct": true, "explanation": "浅：花盆从上到下距离小，树根没有生长空间，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与树根能否生长无关。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，与树根能否生长无关。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不用于说花盆的深浅。"}], "explanations": {"浅": "浅：花盆从上到下距离小，树根没有生长空间，符合句意。", "甜": "语义：“甜”说味道，与树根能否生长无关。", "贵": "语义：“贵”说价格，与树根能否生长无关。", "吵": "搭配：“吵”形容声音，不用于说花盆的深浅。"}, "sentence_index": 6, "correct_answer": "浅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块饼很浅，一口就能吃完。", "explanation": "这里应该用〈薄〉。浅指从上到下距离小；饼、纸等的厚度要用薄。"}, {"text": "他的声音很浅，后排的人都听不见。", "explanation": "这里应该用〈低〉。浅指从上到下距离小；声音的高低要用低。"}, {"text": "他的饭量很浅，一碗就饱了。", "explanation": "这里应该用〈小〉。浅指从上到下距离小；饭量的多少要用小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个托盘浅地只能放几块饼干。", "corrected_sentence": "这个托盘浅得只能放几块饼干。", "error_description": "错误：程度补语前用了“地”。正确：“浅得只能放几块饼干”，应用“得”引出补语；“地”用于修饰动词，不能用于补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把花籽埋很浅，芽很快就出来了。", "corrected_sentence": "他把花籽埋得很浅，芽很快就出来了。", "error_description": "错误：补语前漏了“得”。正确：“埋得很浅”，“得”引出程度补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
