INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88323, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲是用嘴轻轻碰一下人，表示喜欢。", "primary_collocate": null, "pronunciation": "qīn", "ipa": "/tɕʰin˥/", "syllable_count": 1, "sentences": [{"text": "妈妈亲了一下孩子的脸。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲了亲小狗的头。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿跑过来亲了我一下。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶亲着小孙子的脸。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出门前亲了亲妈妈。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩亲了一下妹妹的手。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻亲了一下宝宝。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想亲小猫，小猫跑了。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在她的脸上亲了一下。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没亲过小狗。", "target_word": "亲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲了", "label": "体标"}, {"form": "亲过", "label": "体标"}, {"form": "亲亲", "label": "重叠"}, {"form": "親", "label": "繁体"}], "register": "口语", "sense_fingerprint": "亲：用嘴轻轻碰一下人，表示喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88323, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲", "is_correct": true, "explanation": "正确：亲 qīn，用嘴轻轻碰一下人，表示喜欢。"}, {"text": "青", "is_correct": false, "explanation": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是青色。"}, {"text": "轻", "is_correct": false, "explanation": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是轻松、轻重。"}, {"text": "琴", "is_correct": false, "explanation": "qín（第二声）与 qīn（第一声）声调不同，意思是乐器。"}, {"text": "勤", "is_correct": false, "explanation": "qín（第二声）与 qīn（第一声）声调不同，意思是勤劳。"}], "explanations": {"亲": "正确：亲 qīn，用嘴轻轻碰一下人，表示喜欢。", "青": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是青色。", "轻": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是轻松、轻重。", "琴": "qín（第二声）与 qīn（第一声）声调不同，意思是乐器。", "勤": "qín（第二声）与 qīn（第一声）声调不同，意思是勤劳。"}, "sentence_index": null, "correct_answer": "亲"}, "level_3": {"options": [{"text": "亲", "is_correct": true, "explanation": "正确：亲是用嘴轻轻碰人，表示喜欢，与“亲了一下孩子的脸”相符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：写是用笔写字，不能用来指脸上的动作。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱是发出歌声，不能用来指脸上的动作。"}, {"text": "夸", "is_correct": false, "explanation": "配价：“夸”的对象是人或成绩，不能说“夸孩子的脸”。"}], "explanations": {"亲": "正确：亲是用嘴轻轻碰人，表示喜欢，与“亲了一下孩子的脸”相符。", "写": "搭配：写是用笔写字，不能用来指脸上的动作。", "唱": "搭配：唱是发出歌声，不能用来指脸上的动作。", "夸": "配价：“夸”的对象是人或成绩，不能说“夸孩子的脸”。"}, "sentence_index": 0, "correct_answer": "亲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头不小心亲了一下门框。", "explanation": "这里应该用〈碰〉。亲表示用嘴唇接触人、表示喜爱，不能用于门框；碰是轻轻接触或撞到。"}, {"text": "他用手亲了亲杯子。", "explanation": "这里应该用〈摸〉。亲要用嘴唇接触人或动物，用手接触杯子应该说摸。"}, {"text": "他一拳亲在对方的脸上。", "explanation": "这里应该用〈打〉。亲表示喜爱的轻碰，不能用于拳击动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88323, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亲", "is_correct": true, "explanation": "正确：亲 qīn，用嘴轻轻碰一下人，表示喜欢。"}, {"text": "清", "is_correct": false, "explanation": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是清楚、清澈。"}, {"text": "芹", "is_correct": false, "explanation": "qín（第二声）与 qīn（第一声）声调不同，意思是芹菜。"}, {"text": "寝", "is_correct": false, "explanation": "qǐn（第三声）与 qīn（第一声）声调不同，意思是睡觉、寝室。"}], "explanations": {"亲": "正确：亲 qīn，用嘴轻轻碰一下人，表示喜欢。", "清": "qīng（第一声）与 qīn 韵母不同（ing 与 in），意思是清楚、清澈。", "芹": "qín（第二声）与 qīn（第一声）声调不同，意思是芹菜。", "寝": "qǐn（第三声）与 qīn（第一声）声调不同，意思是睡觉、寝室。"}, "sentence_index": null, "correct_answer": "亲"}, "level_3": {"options": [{"text": "亲", "is_correct": true, "explanation": "正确：亲是用嘴轻轻碰人，表示喜欢，与“轻轻亲了一下宝宝”相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是重重地扔或跌，与“轻轻”和表示喜欢都不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱是发出歌声，不能用来指对宝宝的动作。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”不能带“宝宝”作宾语，不能说“跑了一下宝宝”。"}], "explanations": {"亲": "正确：亲是用嘴轻轻碰人，表示喜欢，与“轻轻亲了一下宝宝”相符。", "摔": "语义：摔是重重地扔或跌，与“轻轻”和表示喜欢都不符。", "唱": "搭配：唱是发出歌声，不能用来指对宝宝的动作。", "跑": "配价：“跑”不能带“宝宝”作宾语，不能说“跑了一下宝宝”。"}, "sentence_index": 6, "correct_answer": "亲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他亲了一下电梯按钮。", "explanation": "这里应该用〈按〉。亲表示用嘴唇接触人或动物表示喜爱，按电梯要用按，不能说亲。"}, {"text": "他亲了亲那碗汤，觉得很香。", "explanation": "这里应该用〈闻〉。亲要用嘴唇接触人或动物，闻汤的香味要说闻。"}, {"text": "他一脚亲在门上。", "explanation": "这里应该用〈踢〉。亲表示喜爱的轻碰，不能用于踢的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
