INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使工作、活动等由小到大地展开进行。", "primary_collocate": null, "pronunciation": "kāi zhǎn", "ipa": "kʰai˥ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小区的垃圾分类工作开展得很好。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究工作开展得很顺利。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校准备开展一次安全教育。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在村里开展了帮助老人的活动。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我们开展了三次大型活动。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项活动先在小城市开展，后来全国都有了。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让大家多运动，公司开展了健步走比赛。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作刚开展的时候，人不多。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里正在开展卫生宣传活动。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们开展小组讨论。", "target_word": "开展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开展了", "label": "完成体"}, {"form": "开展过", "label": "经历体"}, {"form": "开展着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "开展·动词·使工作活动由小到大展开进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开展", "is_correct": true, "explanation": "正确。「工作开展得很好」是常见说法，指工作推进的情况。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能用于「工作」，工作不能唱。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡与工作的进展无关，与句子对工作的评价不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能与「工作」搭配。"}], "explanations": {"开展": "正确。「工作开展得很好」是常见说法，指工作推进的情况。", "唱": "搭配：「唱」不能用于「工作」，工作不能唱。", "睡": "语义：睡与工作的进展无关，与句子对工作的评价不符。", "喝": "搭配：「喝」不能与「工作」搭配。"}, "sentence_index": 0, "correct_answer": "开展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村里开展了一所学校，专门教孩子读书。", "explanation": "这里应该用〈开办〉。学校、工厂等机构要说开办，开展不用于机构。"}, {"text": "他开展了门，走进房间。", "explanation": "这里应该用〈推开〉。开展指工作、活动，不用于门这类具体物体。"}, {"text": "他开展了书，开始读。", "explanation": "这里应该用〈打开〉。开展指工作、活动，不用于书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开展", "is_correct": true, "explanation": "正确。「公司开展了比赛」是常见说法，指组织活动。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是猛然掉落，不能用于组织比赛。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：「吞」只用于食物等，不能吞比赛。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：「抱」用于人或物，不能抱比赛。"}], "explanations": {"开展": "正确。「公司开展了比赛」是常见说法，指组织活动。", "摔": "语义：摔是猛然掉落，不能用于组织比赛。", "吞": "搭配：「吞」只用于食物等，不能吞比赛。", "抱": "搭配：「抱」用于人或物，不能抱比赛。"}, "sentence_index": 6, "correct_answer": "开展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我中午开展了一顿饭，吃得很饱。", "explanation": "这里应该用〈吃〉。开展指工作、活动由小到大展开，不用于吃饭。"}, {"text": "妈妈开展了一碗汤，端到桌上。", "explanation": "这里应该用〈盛〉。开展指工作、活动，不用于盛装食物。"}, {"text": "我开展了一个电话，告诉他这件事。", "explanation": "这里应该用〈打〉。开展指工作、活动，不用于电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社区的志愿服务开展得很顺利得。", "corrected_sentence": "这个社区的志愿服务开展得很顺利。", "error_description": "程度补语“得”只用一次，“很顺利得”多出一个“得”，应说“开展得很顺利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区开展了过垃圾分类宣传。", "corrected_sentence": "这个小区开展过垃圾分类宣传。", "error_description": "“过”是经历体标记，与“了”不能同时用在动词后，“开展了过”错，应说“开展过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
