INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "澄清是把说不清的事讲清楚，让大家明白。", "primary_collocate": null, "pronunciation": "chéng qīng", "ipa": "ʈʂʰɤŋ˧˥ tɕʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "公司发了一个通知，澄清这件事。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他马上出来澄清，说这是误会。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你澄清一下，昨天到底发生了什么。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问了很多问题，想澄清事实。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息是假的，我们必须澄清。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师澄清了同学们的误会。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要澄清，这件事和他没有关系。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写文章澄清了网上的说法。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星公开澄清了那些不对的消息。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想澄清大家的误会，就开了会。", "target_word": "澄清", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "澄清了", "label": "体标"}, {"form": "澄清过", "label": "体标"}, {"form": "澄清一下", "label": "动量"}], "register": "中性", "sense_fingerprint": "澄清：把不清楚的事实、误会讲清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "澄清", "is_correct": true, "explanation": "澄清 chéng qīng 为正确答案，意思是把说不清的事讲清楚。"}, {"text": "成亲", "is_correct": false, "explanation": "成亲 chéng qīn：第二个音节韵尾 n 与 ng 不同（qīn 与 qīng），意思是结婚。"}, {"text": "常青", "is_correct": false, "explanation": "常青 cháng qīng：第一个音节韵母 ang 与 eng 不同，意思是长久保持绿色。"}, {"text": "成精", "is_correct": false, "explanation": "成精 chéng jīng：第二个音节声母 j 与 q 不同（jīng 与 qīng），意思是修炼成精怪。"}, {"text": "承情", "is_correct": false, "explanation": "承情 chéng qíng：第二个音节声调不同（qíng 为第二声，qīng 为第一声），意思是受到别人的好意。"}], "explanations": {"澄清": "澄清 chéng qīng 为正确答案，意思是把说不清的事讲清楚。", "成亲": "成亲 chéng qīn：第二个音节韵尾 n 与 ng 不同（qīn 与 qīng），意思是结婚。", "常青": "常青 cháng qīng：第一个音节韵母 ang 与 eng 不同，意思是长久保持绿色。", "成精": "成精 chéng jīng：第二个音节声母 j 与 q 不同（jīng 与 qīng），意思是修炼成精怪。", "承情": "承情 chéng qíng：第二个音节声调不同（qíng 为第二声，qīng 为第一声），意思是受到别人的好意。"}, "sentence_index": null, "correct_answer": "澄清"}, "level_3": {"options": [{"text": "澄清", "is_correct": true, "explanation": "正确。句中指把「这件事」讲清楚，与「发了一个通知」相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：「隐瞒」是不让人知道，与「发了一个通知」的公开告知相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」是记不住，公司主动发通知却忘记这件事，句意说不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」是讥笑，与公司发通知说明情况的语境不符，句意不通。"}], "explanations": {"澄清": "正确。句中指把「这件事」讲清楚，与「发了一个通知」相符。", "隐瞒": "语义：「隐瞒」是不让人知道，与「发了一个通知」的公开告知相反。", "忘记": "语义：「忘记」是记不住，公司主动发通知却忘记这件事，句意说不通。", "嘲笑": "语义：「嘲笑」是讥笑，与公司发通知说明情况的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "澄清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了一下午澄清房间。", "explanation": "这里应该用〈清理〉。澄清指把说不清的事情或误会讲清楚，不用于打扫房间。"}, {"text": "秘书花了一上午澄清会议资料。", "explanation": "这里应该用〈整理〉。澄清针对说不清的事或说法，会议资料要用〈整理〉来分类归档。"}, {"text": "同学们每天放学后澄清教室。", "explanation": "这里应该用〈打扫〉。澄清是讲清楚事情，把教室弄干净要说〈打扫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "澄清", "is_correct": true, "explanation": "正确。句中指表明事情与他无关，是把事实讲清楚。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」是记不住，「我要忘记」后接说明事实的句子，句意不通。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：「道歉」表示自己有过错，与「没有关系」的表态矛盾。"}, {"text": "负责", "is_correct": false, "explanation": "语义：「负责」是承担责任，与「这件事和他没有关系」的意思相反，句意矛盾。"}], "explanations": {"澄清": "正确。句中指表明事情与他无关，是把事实讲清楚。", "忘记": "语义：「忘记」是记不住，「我要忘记」后接说明事实的句子，句意不通。", "道歉": "语义：「道歉」表示自己有过错，与「没有关系」的表态矛盾。", "负责": "语义：「负责」是承担责任，与「这件事和他没有关系」的意思相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "澄清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力澄清了绳子。", "explanation": "这里应该用〈解开〉。澄清指把说不清的事讲清楚，绳子打结要用〈解开〉。"}, {"text": "他把报告里的错字澄清了。", "explanation": "这里应该用〈修改〉。澄清用于讲清说不清的事，改正错字要用〈修改〉。"}, {"text": "医生用药帮他澄清了视力。", "explanation": "这里应该用〈恢复〉。澄清指讲清事情，视力恢复要用〈恢复〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在澄清了这件事。", "corrected_sentence": "他正在澄清这件事。", "error_description": "「正在」表示动作进行中，不能与动态助词「了」同用。正确：他正在澄清这件事。错误：「正在」后多加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想澄清一下这件事了。", "corrected_sentence": "我想澄清一下这件事。", "error_description": "「想」表示打算，动作还没有发生，句末不能加「了」。正确：我想澄清一下这件事。错误：句末多加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
