INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "试是先做一做，看看行不行。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂɻ̩˥˩", "syllable_count": 1, "sentences": [{"text": "你试一下这个办法吧。", "target_word": "试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜我没吃过，想试一试。", "target_word": "试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小，你试试大一点的。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先试一次，不行再改。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不会游泳，但是想试一试。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一个办法不行，我又试了另一个。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以试着跟他说说你的想法。", "target_word": "试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，别怕错，大家都可以试。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋你试一下，合脚就买。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我试过很多方法，还是睡不着。", "target_word": "试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "试试", "label": "重叠"}, {"form": "试了", "label": "体标"}, {"form": "试过", "label": "体标"}, {"form": "试着", "label": "体标"}, {"form": "試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先做一做某事或某个办法，看看行不行、合不合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88329, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试", "is_correct": true, "explanation": "试 shì（第四声），意思是先做一做，看看行不行。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是数字四。"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时间。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是数字十。"}, {"text": "失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失去。"}, {"text": "社", "is_correct": false, "explanation": "shè 与 shì 韵母不同（è 与 ì），意思是社会、团体。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是诗歌。"}], "explanations": {"试": "试 shì（第四声），意思是先做一做，看看行不行。", "四": "sì 与 shì 声母不同（s 与 sh），意思是数字四。", "时": "shí（第二声）与 shì（第四声）声调不同，意思是时间。", "十": "shí（第二声）与 shì（第四声）声调不同，意思是数字十。", "失": "shī（第一声）与 shì（第四声）声调不同，意思是失去。", "社": "shè 与 shì 韵母不同（è 与 ì），意思是社会、团体。", "诗": "shī（第一声）与 shì（第四声）声调不同，意思是诗歌。"}, "sentence_index": null, "correct_answer": "试"}, "level_3": {"options": [{"text": "试", "is_correct": true, "explanation": "试：先做一做，看这个办法行不行，与“一下”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝的对象是饮料，不能说“喝这个办法”，这里语义不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：睡是不及物动词，不能带“办法”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿多用于衣物、鞋袜，不能说“穿一下这个办法”。"}], "explanations": {"试": "试：先做一做，看这个办法行不行，与“一下”搭配。", "喝": "语义：喝的对象是饮料，不能说“喝这个办法”，这里语义不通。", "睡": "配价：睡是不及物动词，不能带“办法”作宾语。", "穿": "搭配：穿多用于衣物、鞋袜，不能说“穿一下这个办法”。"}, "sentence_index": 0, "correct_answer": "试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份作业我今天试完了。", "explanation": "这里应该用〈做〉。试表示尝试、检验，做完作业要说“做完”，不说“试完”。"}, {"text": "我在那里试到了很多温暖。", "explanation": "这里应该用〈感受〉。试表示尝试，不表示感觉到，感受到温暖要用“感受”。"}, {"text": "我试过很多困难，所以很坚强。", "explanation": "这里应该用〈经历〉。试不能表示遇到并承受困难，经历困难要用“经历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88329, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试", "is_correct": true, "explanation": "试 shì（第四声），意思是先做一做，看看行不行。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是石头。"}, {"text": "师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是老师。"}, {"text": "似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是像、似乎。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是使用、让。"}, {"text": "射", "is_correct": false, "explanation": "shè 与 shì 韵母不同（è 与 ì），意思是射击。"}], "explanations": {"试": "试 shì（第四声），意思是先做一做，看看行不行。", "石": "shí（第二声）与 shì（第四声）声调不同，意思是石头。", "师": "shī（第一声）与 shì（第四声）声调不同，意思是老师。", "似": "sì 与 shì 声母不同（s 与 sh），意思是像、似乎。", "使": "shǐ（第三声）与 shì（第四声）声调不同，意思是使用、让。", "射": "shè 与 shì 韵母不同（è 与 ì），意思是射击。"}, "sentence_index": null, "correct_answer": "试"}, "level_3": {"options": [{"text": "试", "is_correct": true, "explanation": "试着：尝试着去做，符合“你可以……”的建议语气。"}, {"text": "忘", "is_correct": false, "explanation": "语义：忘与“说说想法”意思矛盾，不能用来修饰说话的方式。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：摔是身体跌倒的动作，不能与“说说想法”搭配。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是把东西扯开，不能用来表示说话的方式。"}], "explanations": {"试": "试着：尝试着去做，符合“你可以……”的建议语气。", "忘": "语义：忘与“说说想法”意思矛盾，不能用来修饰说话的方式。", "摔": "搭配：摔是身体跌倒的动作，不能与“说说想法”搭配。", "撕": "语义：撕是把东西扯开，不能用来表示说话的方式。"}, "sentence_index": 6, "correct_answer": "试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把房间试得很干净。", "explanation": "这里应该用〈打扫〉。试表示先做一做看行不行，不表示清洁房间。"}, {"text": "我试了一封信给朋友。", "explanation": "这里应该用〈写〉。试不能表示写信这个动作。"}, {"text": "他每天晚上试两个小时的中文。", "explanation": "这里应该用〈学〉。试表示尝试一下，不表示长期学习某门课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他试了一下了这个办法，没成功。", "corrected_sentence": "他试了一下这个办法，没成功。", "error_description": "错误在体标“了”重复：“试了一下”后面又加了一个“了”，多余的“了”要去掉，应说“试了一下这个办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可以试试一试这个方法。", "corrected_sentence": "你可以试一试这个方法。", "error_description": "错误在于“试试”和“一试”重复，多余成分要去掉，应说“试一试”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
