INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体最上部或动物最前部,长有脑、眼、口、鼻等器官的部分。", "primary_collocate": null, "pronunciation": "tóu", "ipa": "tʰou˧˥", "syllable_count": 1, "sentences": [{"text": "他的头上戴着一顶红帽子。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的头有点儿疼，想休息一下。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫把头放在我的腿上睡觉。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她低着头，在认真地看书。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的头受了一点伤。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的头很圆，眼睛又大又亮。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把头抬起来，看黑板。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一走进门，头就碰到了门框。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人摇了摇头，什么也没说。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的时候，你的头要露出水面。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "繁体"}, {"form": "头发", "label": "复合"}], "register": "中性", "sense_fingerprint": "头:人体最上部、动物最前部,长有脑和五官的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67aa835c-524f-4aad-8e43-c58392166a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "头", "is_correct": true, "explanation": "正确答案。tóu，指人体最上部，长有脑和五官。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 tóu（第二声）声调不同，意思是透过、透明。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}], "explanations": {"头": "正确答案。tóu，指人体最上部，长有脑和五官。", "偷": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷。", "透": "tòu（第四声）与 tóu（第二声）声调不同，意思是透过、透明。", "楼": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。", "愁": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}, "sentence_index": null, "correct_answer": "头"}, "level_3": {"options": [{"text": "头", "is_correct": true, "explanation": "正确。句中“头”指人体最上部，帽子戴在头上。"}, {"text": "脸", "is_correct": false, "explanation": "语义：帽子应戴在头部，脸上不能戴帽子。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“戴”用于帽子时要说“戴在头上”，“手上戴帽子”不通。"}, {"text": "腿", "is_correct": false, "explanation": "语义：帽子不能戴在腿上，句意不通。"}], "explanations": {"头": "正确。句中“头”指人体最上部，帽子戴在头上。", "脸": "语义：帽子应戴在头部，脸上不能戴帽子。", "手": "搭配：“戴”用于帽子时要说“戴在头上”，“手上戴帽子”不通。", "腿": "语义：帽子不能戴在腿上，句意不通。"}, "sentence_index": 0, "correct_answer": "头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用头写了一封信。", "explanation": "这里应该用〈手〉。写信要用手拿笔，不能用头写。"}, {"text": "我的头很渴，想喝水。", "explanation": "这里应该用〈嗓子〉或直接说“我很渴”。渴不说“头渴”。"}, {"text": "他用头听着音乐。", "explanation": "这里应该用〈耳朵〉。听声音要用耳朵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "头", "is_correct": true, "explanation": "正确答案。tóu，指人体最上部，长有脑和五官。"}, {"text": "仇", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨、仇人。"}, {"text": "稠", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是浓稠、稠密。"}, {"text": "绸", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是筹备、筹划。"}], "explanations": {"头": "正确答案。tóu，指人体最上部，长有脑和五官。", "仇": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨、仇人。", "稠": "chóu 与 tóu 声母不同（ch 与 t），意思是浓稠、稠密。", "绸": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。", "筹": "chóu 与 tóu 声母不同（ch 与 t），意思是筹备、筹划。"}, "sentence_index": null, "correct_answer": "头"}, "level_3": {"options": [{"text": "头", "is_correct": true, "explanation": "正确。“请把头抬起来”指抬起头部，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是固定的建筑，不能被抬起来。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“抬”不与“天空”搭配，人抬起的是身体部位或可移动的物体。"}, {"text": "大海", "is_correct": false, "explanation": "配价：大海无法被人抬起，“抬”的宾语须是可移动的物体或身体部位。"}], "explanations": {"头": "正确。“请把头抬起来”指抬起头部，符合句意。", "墙": "语义：墙是固定的建筑，不能被抬起来。", "天空": "搭配：“抬”不与“天空”搭配，人抬起的是身体部位或可移动的物体。", "大海": "配价：大海无法被人抬起，“抬”的宾语须是可移动的物体或身体部位。"}, "sentence_index": 6, "correct_answer": "头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗用头摇着尾巴。", "explanation": "这里应该去掉“用头”。摇尾巴是尾巴的动作，与头无关。"}, {"text": "他把戒指戴在头上。", "explanation": "这里应该用〈手指〉。戒指戴在手指上，不戴在头上。"}, {"text": "我用头踢了一下球。", "explanation": "这里应该用〈脚〉。“踢”是脚的动作，用头碰球要说“顶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从窗户里伸出了一只头。", "corrected_sentence": "他从窗户里伸出了一个头。", "error_description": "错误在于量词。“头”作整体计数时用“个”，“只”多用于小动物或成对的东西。正确说法是“伸出了一个头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抬了起头，看着我。", "corrected_sentence": "他抬起了头，看着我。", "error_description": "错误在于“了”的位置。“抬起”是动补结构，“了”应放在补语“起”之后，说“抬起了头”，不能说“抬了起头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
