INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "无产阶级是自己没有工厂和土地，要靠做工过日子的人。", "primary_collocate": null, "pronunciation": "wú chǎn jiē jí", "ipa": "u˧˥ ʈʂʰan˨˩ tɕjɛ˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "无产阶级没有工厂，也没有土地。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级靠做工过日子。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，无产阶级的生活很苦。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级每天都要去工厂做工。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷是无产阶级，一辈子没有地。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，无产阶级就是没有工厂和土地的人。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级的孩子很早就要帮家里赚钱。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在旧社会，无产阶级过着很穷的日子。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级没有钱买房子，只能租房住。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了很多无产阶级的故事。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "没有工厂和土地、靠做工过日子的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“无产阶级”指没有工厂和土地的人，与句子相符。"}, {"text": "地主", "is_correct": false, "explanation": "语义：“地主”拥有土地，与“没有土地”矛盾。"}, {"text": "资本家", "is_correct": false, "explanation": "语义：“资本家”拥有工厂，与“没有工厂”矛盾。"}, {"text": "贵族", "is_correct": false, "explanation": "搭配：“贵族”通常与领地、土地相连，说“没有土地”不通。"}], "explanations": {"无产阶级": "正确：“无产阶级”指没有工厂和土地的人，与句子相符。", "地主": "语义：“地主”拥有土地，与“没有土地”矛盾。", "资本家": "语义：“资本家”拥有工厂，与“没有工厂”矛盾。", "贵族": "搭配：“贵族”通常与领地、土地相连，说“没有土地”不通。"}, "sentence_index": 0, "correct_answer": "无产阶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个无产阶级有很多土地，每年都收租。", "explanation": "这里应该用〈地主〉。无产阶级没有土地，不能拥有很多土地、收租。"}, {"text": "那个无产阶级很富有，拥有三座厂房。", "explanation": "这里应该用〈资本家〉。无产阶级没有工厂，不能说“拥有三座厂房”。"}, {"text": "那个无产阶级每天都在自己的工厂里发号施令。", "explanation": "这里应该用〈老板〉。无产阶级没有生产资料，不能在工厂里发号施令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“无产阶级”的孩子家里没有其他收入，要早早赚钱，与句意相符。"}, {"text": "富豪", "is_correct": false, "explanation": "语义：“富豪”家庭富裕，孩子不必早早赚钱，与句意矛盾。"}, {"text": "王公", "is_correct": false, "explanation": "语义：“王公”是有封地的贵族，孩子不必早早赚钱，与句意矛盾。"}, {"text": "地主", "is_correct": false, "explanation": "语义：“地主”有很多土地，孩子不必早早帮家里赚钱，与句意矛盾。"}], "explanations": {"无产阶级": "正确：“无产阶级”的孩子家里没有其他收入，要早早赚钱，与句意相符。", "富豪": "语义：“富豪”家庭富裕，孩子不必早早赚钱，与句意矛盾。", "王公": "语义：“王公”是有封地的贵族，孩子不必早早赚钱，与句意矛盾。", "地主": "语义：“地主”有很多土地，孩子不必早早帮家里赚钱，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "无产阶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子的无产阶级都有自己的田地。", "explanation": "这里应该用〈农民〉。无产阶级没有土地，不能说“都有自己的田地”。"}, {"text": "那个无产阶级每年都会开新的工厂。", "explanation": "这里应该用〈工厂主〉。无产阶级没有工厂，不能每年开新工厂。"}, {"text": "那个无产阶级拥有几家店，生意很好。", "explanation": "这里应该用〈商人〉。无产阶级没有生产资料，不能拥有几家店、做生意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有很多工厂和土地，是无产阶级。", "corrected_sentence": "他家没有工厂和土地，是无产阶级。", "error_description": "词义用错：无产阶级没有工厂和土地，有很多工厂和土地的人不是无产阶级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家有很多地，所以是无产阶级。", "corrected_sentence": "他家没有地，所以是无产阶级。", "error_description": "词义用错：无产阶级没有土地，有很多地的人不是无产阶级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
