INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "没有生产资料、靠出卖劳动力为生的工人阶级。", "primary_collocate": null, "pronunciation": "wú chǎn jiē jí", "ipa": "u˧˥ ʈʂʰan˨˩ tɕjɛ˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "无产阶级是靠出卖劳动力为生的工人阶级。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级没有生产资料，只能给老板打工。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级和资产阶级的关系很紧张。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业发展以后，无产阶级的人数多了起来。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级要团结起来，争取更好的工资。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是无产阶级的历史。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级用劳动换工资，不能靠土地生活。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马克思很关心无产阶级的命运。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们认为无产阶级应该有自己的政党。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无产阶级在工厂里工作了很多年。", "target_word": "无产阶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "没有生产资料、出卖劳动力的工人阶级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“无产阶级”就是靠出卖劳动力为生的工人阶级，与定义一致。"}, {"text": "地主", "is_correct": false, "explanation": "语义：“地主”靠收租土地为生，不是靠出卖劳动力为生，与句意矛盾。"}, {"text": "雇主", "is_correct": false, "explanation": "语义：“雇主”是雇用别人的人，不是靠出卖劳动力为生的人。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“农民”通常与土地相连，不说“工人阶级”，与句子不合。"}], "explanations": {"无产阶级": "正确：“无产阶级”就是靠出卖劳动力为生的工人阶级，与定义一致。", "地主": "语义：“地主”靠收租土地为生，不是靠出卖劳动力为生，与句意矛盾。", "雇主": "语义：“雇主”是雇用别人的人，不是靠出卖劳动力为生的人。", "农民": "搭配：“农民”通常与土地相连，不说“工人阶级”，与句子不合。"}, "sentence_index": 0, "correct_answer": "无产阶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个无产阶级把自己的工厂租给别人，每月收租金。", "explanation": "这里应该用〈厂主〉。无产阶级没有生产资料，不能拥有工厂出租、每月收租金。"}, {"text": "那个无产阶级每月付给工人工资。", "explanation": "这里应该用〈雇主〉。无产阶级没有钱雇人，不能付给工人工资。"}, {"text": "这家公司的无产阶级每年都分红。", "explanation": "这里应该用〈股东〉。无产阶级没有生产资料，不能分红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无产阶级", "is_correct": true, "explanation": "正确：“无产阶级”没有生产资料，只能用劳动换工资，与“不能靠土地生活”相符。"}, {"text": "商人", "is_correct": false, "explanation": "语义：“商人”靠买卖赚钱，不用劳动换工资，与句意不符。"}, {"text": "王公", "is_correct": false, "explanation": "语义：“王公”靠土地和封地过日子，与“不能靠土地生活”矛盾。"}, {"text": "资本家", "is_correct": false, "explanation": "语义：“资本家”拥有生产资料，不用劳动换工资，与句意矛盾。"}], "explanations": {"无产阶级": "正确：“无产阶级”没有生产资料，只能用劳动换工资，与“不能靠土地生活”相符。", "商人": "语义：“商人”靠买卖赚钱，不用劳动换工资，与句意不符。", "王公": "语义：“王公”靠土地和封地过日子，与“不能靠土地生活”矛盾。", "资本家": "语义：“资本家”拥有生产资料，不用劳动换工资，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "无产阶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的无产阶级决定了工资的高低。", "explanation": "这里应该用〈资本家〉。无产阶级没有生产资料，不能决定工资的高低。"}, {"text": "那个无产阶级在自己的田里种了很多年。", "explanation": "这里应该用〈自耕农〉。无产阶级没有土地，不能在自己的田里种地。"}, {"text": "那个无产阶级每天都在自己的办公室里发号施令。", "explanation": "这里应该用〈老板〉。无产阶级出卖劳动力，不能在办公室里发号施令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "无产阶级拥有很多工厂，靠收利润生活。", "corrected_sentence": "资本家拥有很多工厂，靠收利润生活。", "error_description": "词义用错：无产阶级没有生产资料，拥有工厂、靠利润生活的是资本家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无产阶级靠收地租生活。", "corrected_sentence": "无产阶级靠出卖劳动力生活。", "error_description": "词义用错：无产阶级没有土地，靠出卖劳动力为生，不能靠收地租生活。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
