INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88335, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "低下是能力、素质、格调等比别人差。", "primary_collocate": null, "pronunciation": "dī xià", "ipa": "ti˥ ɕjɑ˥˩", "syllable_count": 2, "sentences": [{"text": "他的工作能力低下，同事都不愿意和他合作。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影格调低下，我看了一半就走了。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个工厂工人的技术低下，做出来的东西很差。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望水平低下的同学多练习。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇的生产力还很低下，大家过得不容易。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小缺乏训练，动手能力低下，很难做好细活。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务水平低下，客人越来越少。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做事的效率太低下，一天只做一点点。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的行为说明他的素质低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为文化水平低下，他只能做简单的工作。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能力、素质、格调等比别人差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下（dī xià）：能力、素质、格调等比别人差。"}, {"text": "底下", "is_correct": false, "explanation": "底下（dǐ xia）与低下（dī xià）首字声调不同（第三声），意思是下面、底部。"}, {"text": "地下", "is_correct": false, "explanation": "地下（dì xià）与低下（dī xià）首字声调不同（第四声），意思是地面以下。"}, {"text": "低价", "is_correct": false, "explanation": "低价（dī jià）与低下（dī xià）末字声母不同（j 与 x），意思是价格低。"}], "explanations": {"低下": "低下（dī xià）：能力、素质、格调等比别人差。", "底下": "底下（dǐ xia）与低下（dī xià）首字声调不同（第三声），意思是下面、底部。", "地下": "地下（dì xià）与低下（dī xià）首字声调不同（第四声），意思是地面以下。", "低价": "低价（dī jià）与低下（dī xià）末字声母不同（j 与 x），意思是价格低。"}, "sentence_index": null, "correct_answer": "低下"}, "level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下：形容工作能力比别人差，与“他的工作能力”搭配。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材，不能用来形容工作能力。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容心情，不能用于形容能力。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，与“工作能力”不相容。"}], "explanations": {"低下": "低下：形容工作能力比别人差，与“他的工作能力”搭配。", "苗条": "体貌：“苗条”形容身材，不能用来形容工作能力。", "愉快": "语义：“愉快”形容心情，不能用于形容能力。", "热闹": "语义：“热闹”形容场面或气氛，与“工作能力”不相容。"}, "sentence_index": 0, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很低下，比同班同学矮半个头。", "explanation": "这里应该用〈矮〉。低下用于能力、素质等，形容身高只说〈矮〉。"}, {"text": "他最近心情很低下，不太爱说话。", "explanation": "这里应该用〈低落〉。心情的低沉要说〈低落〉，低下用于能力、素质等，不用于心情。"}, {"text": "这位歌手的声音很低下，听起来很舒服。", "explanation": "这里应该用〈低沉〉。声音的低沉要说〈低沉〉，低下不用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下：形容服务水平比别人差，与“这家店的服务水平”搭配。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身体，不能用来形容服务水平。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”形容头脑，与“服务水平”不相容。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境，不能用于形容服务水平。"}], "explanations": {"低下": "低下：形容服务水平比别人差，与“这家店的服务水平”搭配。", "瘦": "体貌：“瘦”形容身体，不能用来形容服务水平。", "清醒": "语义：“清醒”形容头脑，与“服务水平”不相容。", "寂静": "语义：“寂静”形容环境，不能用于形容服务水平。"}, "sentence_index": 6, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的价格很低下，很多人都买了。", "explanation": "这里应该用〈低廉〉。低下用于能力、素质等，价格便宜要说〈低廉〉。"}, {"text": "这座小屋的屋顶很低下，要弯着腰进门。", "explanation": "这里应该用〈低矮〉。低下不用于房屋高矮，屋顶低要说〈低矮〉。"}, {"text": "这个市场最近很低下，买卖都不好做。", "explanation": "这里应该用〈低迷〉。市场、行情的萎靡要说〈低迷〉，低下用于能力、素质等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工作能力被低下，经理很着急。", "corrected_sentence": "他的工作能力低下，经理很着急。", "error_description": "错误：被低下。正确：低下。“低下”是形容词，不能用“被”字句，去掉“被”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们学习的效率太低下得，一天只学一点点。", "corrected_sentence": "他们学习的效率太低下，一天只学一点点。", "error_description": "错误：太低下得。正确：太低下。“太”修饰形容词时直接放在形容词前，后面不加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
