INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88336, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（地位、水平等）在一般标准之下；低。", "primary_collocate": null, "pronunciation": "dī xià", "ipa": "ti˥ ɕjɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这家工厂的生产效率很低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个时代，女人的地位非常低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的教学水平比较低下，学生都不满意。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为管理水平低下，公司每年都亏钱。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的生活水平还很低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的教育水平还比较低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品质量低下，顾客不会再买。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去农民的社会地位十分低下。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗水平低下，很多病得不到治疗。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法解决效率低下的问题。", "target_word": "低下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "地位、水平、效率等在一般标准之下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下（dī xià）：水平、地位等在一般标准之下。"}, {"text": "底下", "is_correct": false, "explanation": "底下（dǐ xia）与低下（dī xià）首字声调不同（第三声），意思是下面、底部。"}, {"text": "地下", "is_correct": false, "explanation": "地下（dì xià）与低下（dī xià）首字声调不同（第四声），意思是地面以下。"}, {"text": "低价", "is_correct": false, "explanation": "低价（dī jià）与低下（dī xià）末字声母不同（j 与 x），意思是价格低。"}], "explanations": {"低下": "低下（dī xià）：水平、地位等在一般标准之下。", "底下": "底下（dǐ xia）与低下（dī xià）首字声调不同（第三声），意思是下面、底部。", "地下": "地下（dì xià）与低下（dī xià）首字声调不同（第四声），意思是地面以下。", "低价": "低价（dī jià）与低下（dī xià）末字声母不同（j 与 x），意思是价格低。"}, "sentence_index": null, "correct_answer": "低下"}, "level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下：形容生产效率在一般标准之下，与“很”搭配。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容生产效率。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用于形容效率。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，与“生产效率”不相容。"}], "explanations": {"低下": "低下：形容生产效率在一般标准之下，与“很”搭配。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容生产效率。", "聪明": "语义：“聪明”形容人的智力，不能用于形容效率。", "热情": "语义：“热情”形容人的态度，与“生产效率”不相容。"}, "sentence_index": 0, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段时间，股市一直很低下，投资的人都很失望。", "explanation": "这里应该用〈低迷〉。股市、行情的萎靡要说〈低迷〉，低下用于地位、水平等，不用于股市。"}, {"text": "这座山的海拔很低下，几乎看不到雪。", "explanation": "这里应该用〈低〉。低下用于地位、水平、效率等，海拔这类数值只说〈低〉。"}, {"text": "这段路上车速很低下，后面的车都超过了它。", "explanation": "这里应该用〈慢〉。低下用于地位、水平等，描述车速的快慢要说〈慢〉，不说〈低下〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低下", "is_correct": true, "explanation": "低下：形容产品质量在一般标准之下，与“产品质量”搭配。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体积，不能用来形容产品质量。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或动物讨人喜欢，与“产品质量”不相容。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性格或态度，不能用于产品。"}], "explanations": {"低下": "低下：形容产品质量在一般标准之下，与“产品质量”搭配。", "高大": "体貌：“高大”形容身材或体积，不能用来形容产品质量。", "可爱": "语义：“可爱”形容人或动物讨人喜欢，与“产品质量”不相容。", "温柔": "语义：“温柔”形容人的性格或态度，不能用于产品。"}, "sentence_index": 6, "correct_answer": "低下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的声音很低下，听起来很舒服。", "explanation": "这里应该用〈低沉〉。低下用于水平、地位，声音的低沉要说〈低沉〉。"}, {"text": "这件衣服的价格很低下，买的人很多。", "explanation": "这里应该用〈低廉〉。低下用于水平、质量，价格便宜要说〈低廉〉。"}, {"text": "这间房子的屋顶很低下，我们都要弯腰走路。", "explanation": "这里应该用〈低矮〉。低下用于水平、地位，房屋高矮要说〈低矮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的管理水平被低下。", "corrected_sentence": "这家工厂的管理水平很低下。", "error_description": "“被”字句不能用于形容词“低下”；应说“很低下”，表示程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家医院的服务质量被低下，病人很不满意。", "corrected_sentence": "那家医院的服务质量低下，病人很不满意。", "error_description": "“低下”是形容词，不能用“被”字句；去掉“被”，说“那家医院的服务质量低下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
