INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "课是老师在教室里教学生的一段时间。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "今天下午我们有两节课。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节课有四十五分钟。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一节课八点开始。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天的课讲得很清楚。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的课很快就结束了。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一节课在哪个教室？", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的课学生们都爱听。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上午的课太多，我有点儿累。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到教室时，课已经开始了。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节课老师让我们先听后说。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "課", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老师在教室里给学生上的一节课的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。“两节课”指一段教学时间，“节”用来计量课程，这里只有“课”能填入。"}, {"text": "电话", "is_correct": false, "explanation": "量词：“节”不能计量电话，电话应说“通”。"}, {"text": "朋友", "is_correct": false, "explanation": "量词：“节”不能计量人，“朋友”应说“个”。"}, {"text": "歌", "is_correct": false, "explanation": "量词：“节”不能计量歌，歌应说“首”。"}], "explanations": {"课": "正确。“两节课”指一段教学时间，“节”用来计量课程，这里只有“课”能填入。", "电话": "量词：“节”不能计量电话，电话应说“通”。", "朋友": "量词：“节”不能计量人，“朋友”应说“个”。", "歌": "量词：“节”不能计量歌，歌应说“首”。"}, "sentence_index": 0, "correct_answer": "课"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最喜欢的课是音乐。", "explanation": "语义：这里的“课”指学校的科目，是另一种意思；本句要表示一段教学时间，学科则说“门”。"}, {"text": "这门课需要买两本书。", "explanation": "语义：这里的“门课”指学校的科目，是另一种意思；本句要表示一段教学时间。"}, {"text": "我们每天上一张课。", "explanation": "量词：“张”用于纸、桌子等，一段教学时间要用“节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。“他讲的课”指他讲授的课，学生们爱听的是课，与“爱听”搭配。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“爱听”不能用于“作业”，作业是要做的东西。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“饭”是用来吃的，不能说“爱听”。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“风景”是用来看的，不能说“爱听”。"}], "explanations": {"课": "正确。“他讲的课”指他讲授的课，学生们爱听的是课，与“爱听”搭配。", "作业": "搭配：“爱听”不能用于“作业”，作业是要做的东西。", "饭": "搭配：“饭”是用来吃的，不能说“爱听”。", "风景": "搭配：“风景”是用来看的，不能说“爱听”。"}, "sentence_index": 6, "correct_answer": "课"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课我考得不太好。", "explanation": "语义：这里的“课”指学校的科目，是另一种意思；本句要表示一段教学时间。"}, {"text": "我们今天上了一场课。", "explanation": "量词：“场”用于场地上的活动，一段教学时间要用“节”。"}, {"text": "我们每天都吃一节课。", "explanation": "语义：“课”指一段教学时间，不能被“吃”，这里的动词与本词的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
