INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学校里开设的一门教学科目。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "这学期我选了三门课。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的一门课是音乐。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的老师很年轻。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学是我最难的一门课。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个学期都要学八门课。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课需要买两本书。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想选哪门课？", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新开了一门做饭的课。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课我考得不太好。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几门课里我最爱画画。", "target_word": "课", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "課", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校里要学的一门科目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。课（kè，第四声）指学校里的一门科目，即本句所说的“课”。"}, {"text": "颗", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，“颗”是量词，用于颗粒状的东西。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，“可”意思是可以、可能。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kè（第四声）声调不同，“咳”意思是咳嗽。"}], "explanations": {"课": "正确。课（kè，第四声）指学校里的一门科目，即本句所说的“课”。", "颗": "kē（第一声）与 kè（第四声）声调不同，“颗”是量词，用于颗粒状的东西。", "可": "kě（第三声）与 kè（第四声）声调不同，“可”意思是可以、可能。", "咳": "ké（第二声）与 kè（第四声）声调不同，“咳”意思是咳嗽。"}, "sentence_index": null, "correct_answer": "课"}, "level_3": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。“选了三门”的对象是学校里的科目，只有“课”能填入。"}, {"text": "电影", "is_correct": false, "explanation": "量词：“门”不能计量电影，电影应说“部”。"}, {"text": "照片", "is_correct": false, "explanation": "量词：“门”不能计量照片，照片应说“张”。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：“演讲”指一次发言活动，不是可以选修的科目。"}], "explanations": {"课": "正确。“选了三门”的对象是学校里的科目，只有“课”能填入。", "电影": "量词：“门”不能计量电影，电影应说“部”。", "照片": "量词：“门”不能计量照片，照片应说“张”。", "演讲": "语义：“演讲”指一次发言活动，不是可以选修的科目。"}, "sentence_index": 0, "correct_answer": "课"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学是我最难的一个课。", "explanation": "量词：指学校的科目要用“门”，不用“个”。"}, {"text": "我们上完了这节课，就去吃饭了。", "explanation": "语义：这里的“课”指一段教学时间，是另一种意思；本词条要表示学校的科目，应说“门”。"}, {"text": "数学是我最难的一本课。", "explanation": "量词：指学校的科目要用“门”，“本”用于书册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88338, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。课（kè，第四声）指学校里的一门科目，即本句所说的“课”。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，“渴”意思是想喝水。"}, {"text": "壳", "is_correct": false, "explanation": "ké（第二声）与 kè（第四声）声调不同，“壳”意思是外壳。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，“科”指分类的门类，如“科学”“外科”。"}, {"text": "棵", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，“棵”是量词，用于植物。"}], "explanations": {"课": "正确。课（kè，第四声）指学校里的一门科目，即本句所说的“课”。", "渴": "kě（第三声）与 kè（第四声）声调不同，“渴”意思是想喝水。", "壳": "ké（第二声）与 kè（第四声）声调不同，“壳”意思是外壳。", "科": "kē（第一声）与 kè（第四声）声调不同，“科”指分类的门类，如“科学”“外科”。", "棵": "kē（第一声）与 kè（第四声）声调不同，“棵”是量词，用于植物。"}, "sentence_index": null, "correct_answer": "课"}, "level_3": {"options": [{"text": "课", "is_correct": true, "explanation": "正确。“哪门”后面要接学校的科目，只有“课”能填入。"}, {"text": "汽车", "is_correct": false, "explanation": "量词：“门”不能计量汽车，汽车应说“辆”。"}, {"text": "朋友", "is_correct": false, "explanation": "量词：“门”不能计量人，“朋友”应说“个”。"}, {"text": "电话", "is_correct": false, "explanation": "量词：“门”不能计量电话，电话应说“通”。"}], "explanations": {"课": "正确。“哪门”后面要接学校的科目，只有“课”能填入。", "汽车": "量词：“门”不能计量汽车，汽车应说“辆”。", "朋友": "量词：“门”不能计量人，“朋友”应说“个”。", "电话": "量词：“门”不能计量电话，电话应说“通”。"}, "sentence_index": 6, "correct_answer": "课"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课我都吃完了。", "explanation": "语义：“课”指学校的一门科目，科目是用来学的，不能被“吃”，动词与本词意思不符。"}, {"text": "我们在这几节课上吃饭。", "explanation": "语义：这里的“课”指一段教学时间，而本词条要表示学科，学科应说“门”。"}, {"text": "这几个课里我最爱画画。", "explanation": "量词：指学校的科目要用“门”，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX