INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人权是每个人都应该有的好处,比如能吃饱、能上学、不被打。", "primary_collocate": null, "pronunciation": "rén quán", "ipa": "ʐən˧˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "每个孩子都有上学的权利，这是人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饱饭是最基本的人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人权让每个人都能安全地生活。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能打人，因为每个人都有人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊重别人的人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在为人权工作。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都应该有人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是人权的故事。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护人权，大家都有责任。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人权问题", "label": "复合"}, {"form": "人权组织", "label": "复合"}, {"form": "人權", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每个人都应有的基本好处，如吃饱、上学、不挨打", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“这是作业”把权利说成了任务，与上文“上学的权利”所说的意思不合。"}, {"text": "人权", "is_correct": true, "explanation": "正确：指每个人应有的基本权利，与上文“上学的权利”相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，与权利无关，不能用来解释上文。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景是可以观赏的景色，不能说“这是风景”来解释权利。"}], "explanations": {"作业": "语义：“这是作业”把权利说成了任务，与上文“上学的权利”所说的意思不合。", "人权": "正确：指每个人应有的基本权利，与上文“上学的权利”相合。", "身材": "体貌：身材指人的体形，与权利无关，不能用来解释上文。", "风景": "语义：风景是可以观赏的景色，不能说“这是风景”来解释权利。"}, "sentence_index": 0, "correct_answer": "人权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依法享有选举的人权。", "explanation": "这里应该用〈权利〉。人权指人人生来就有的基本权利，不指选举权这类具体的法定权利。"}, {"text": "我们享有言论人权。", "explanation": "这里应该用〈自由〉。言论自由是具体的一项自由，人权是对基本权利的统称，不单指言论。"}, {"text": "他在公司的人权很高。", "explanation": "这里应该用〈地位〉。地位指在社会或组织中的位置，可以说高低；人权是人人应有的基本权利，不能用来表示职位高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能成为工作服务的对象，“为鱼工作”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“为……工作”要求服务对象是人或组织，“桌子”不能作为工作的对象。"}, {"text": "人权", "is_correct": true, "explanation": "正确：“为人权工作”指为人权事业服务，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以为之工作的对象。"}], "explanations": {"鱼": "语义：鱼不能成为工作服务的对象，“为鱼工作”句意不通。", "桌子": "配价：“为……工作”要求服务对象是人或组织，“桌子”不能作为工作的对象。", "人权": "正确：“为人权工作”指为人权事业服务，符合语境。", "天气": "语义：天气是自然现象，不是可以为之工作的对象。"}, "sentence_index": 6, "correct_answer": "人权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保护一匹人权，大家都有责任。", "explanation": "这里应该用〈项〉。“匹”用于马、布等，人权是抽象的权利，计量用“项”。"}, {"text": "保护一棵人权，大家都有责任。", "explanation": "这里应该用〈项〉。“棵”用于树木等植物，人权是抽象概念，不能用“棵”计量。"}, {"text": "保护一张人权，大家都有责任。", "explanation": "这里应该用〈项〉。“张”多用于纸张、桌子等平面的东西，不能用来计量人权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人人权都应该被尊重。", "corrected_sentence": "每个人的人权都应该被尊重。", "error_description": "错误：“每个人”修饰“人权”时漏了“的”。正确应为“每个人的人权”，“每个人”作定语须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每张人权都应该被尊重。", "corrected_sentence": "每项人权都应该被尊重。", "error_description": "错误：“人权”的量词用了“张”。正确应用“项”，“张”用于纸张、桌子等平面的东西，抽象的权利应用“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
