INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人依其本性应享有的基本权利,如生存权、自由权等。", "primary_collocate": null, "pronunciation": "rén quán", "ipa": "ʐən˧˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "生存权和自由权都是基本人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国政府都应该保护人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织一直关注人权问题。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位研究人权的律师。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律应该保障公民的人权。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人权是每个人生来就有的权利。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上讨论了人权问题。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人权情况有了改善。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尊重人权是社会进步的标志。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为人权写了很多文章。", "target_word": "人权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人权问题", "label": "复合"}, {"form": "人权组织", "label": "复合"}, {"form": "人權", "label": "繁体"}], "register": "正式", "sense_fingerprint": "人依本性应享有的基本权利，如生存权、自由权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，不是权利，句中“都是基本……”说的是权利。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是用来做事的器物，不能与生存权、自由权并列为基本权利。"}, {"text": "人权", "is_correct": true, "explanation": "正确：“基本人权”指人依本性应享有的基本权利，与上文的生存权、自由权相合。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“基本”修饰抽象的权利或原则，不能说“基本木材”。"}], "explanations": {"粮食": "语义：粮食是食物，不是权利，句中“都是基本……”说的是权利。", "工具": "语义：工具是用来做事的器物，不能与生存权、自由权并列为基本权利。", "人权": "正确：“基本人权”指人依本性应享有的基本权利，与上文的生存权、自由权相合。", "木材": "搭配：“基本”修饰抽象的权利或原则，不能说“基本木材”。"}, "sentence_index": 0, "correct_answer": "人权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的人权归作者所有。", "explanation": "这里应该用〈版权〉。版权指作品的著作权，人权是人依本性应享有的基本权利，不能用来指书的权益归属。"}, {"text": "法官有依法审判的人权。", "explanation": "这里应该用〈职权〉。职权指职务赋予的权力，人权指人依本性应享有的基本权利，不指官员的职务权力。"}, {"text": "他在公司的人权很高。", "explanation": "这里应该用〈地位〉。地位可以说高低；人权不指职位，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼泪", "is_correct": false, "explanation": "配价：“讨论”的对象须是可议论的事项，“眼泪”不能作为会上讨论的议题。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情，不是需要在会上讨论的问题。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是会议上讨论的问题。"}, {"text": "人权", "is_correct": true, "explanation": "正确：“人权问题”是固定说法，指与人权有关的问题，符合语境。"}], "explanations": {"眼泪": "配价：“讨论”的对象须是可议论的事项，“眼泪”不能作为会上讨论的议题。", "微笑": "语义：微笑是表情，不是需要在会上讨论的问题。", "桌子": "语义：桌子是家具，不是会议上讨论的问题。", "人权": "正确：“人权问题”是固定说法，指与人权有关的问题，符合语境。"}, "sentence_index": 6, "correct_answer": "人权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她为一首人权写了很多文章。", "explanation": "这里应该用〈项〉。人权是抽象概念，计量用“项”；“首”用于诗歌、歌曲，不能用于人权。"}, {"text": "她为一座人权写了很多文章。", "explanation": "这里应该用〈项〉。“座”用于山、楼等大型固定的东西，不能用来计量人权。"}, {"text": "她为一支人权写了很多文章。", "explanation": "这里应该用〈项〉。“支”多用于笔、队伍等，不能用来计量抽象的人权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人人权都不能被侵犯。", "corrected_sentence": "每个人的人权都不能被侵犯。", "error_description": "错误：“每个人”修饰“人权”时漏了“的”。正确应为“每个人的人权”，“每个人”作定语须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每张人权都应该被尊重。", "corrected_sentence": "每项人权都应该被尊重。", "error_description": "错误：“人权”的量词用了“张”。正确应用“项”，“张”用于纸张、桌子等平面的东西，抽象的权利应用“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
