INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灯光是灯发出来的亮光。", "primary_collocate": null, "pronunciation": "dēng guāng", "ipa": "tɤŋ˥ kuɑŋ˥", "syllable_count": 2, "sentences": [{"text": "房间里的灯光很温暖。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，远处有一片灯光。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光太亮了，我睡不着。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的灯光突然暗了下来。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的灯光照着小路。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关了灯，屋里没有灯光了。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在柔和的灯光下吃晚饭。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上看，城市的灯光像星星。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里的灯光慢慢灭了。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢昏黄的灯光，觉得很安静。", "target_word": "灯光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片灯光", "label": "量词"}, {"form": "一道灯光", "label": "量词"}, {"form": "舞台灯光", "label": "复合"}, {"form": "燈光", "label": "繁体"}], "register": "中性", "sense_fingerprint": "灯发出来的亮光，指照明的光线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88341, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灯光", "is_correct": true, "explanation": "正确：灯光是灯发出的亮光。"}, {"text": "风光", "is_correct": false, "explanation": "dēng 与 fēng 声母不同（d 与 f），意思是风景、景色。"}, {"text": "增光", "is_correct": false, "explanation": "dēng 与 zēng 声母不同（d 与 z），意思是增添光彩。"}, {"text": "声光", "is_correct": false, "explanation": "dēng 与 shēng 声母不同（d 与 sh），意思是声音和光线。"}, {"text": "灯管", "is_correct": false, "explanation": "guāng 与 guǎn 韵母不同且声调不同，意思是日光灯的灯管。"}], "explanations": {"灯光": "正确：灯光是灯发出的亮光。", "风光": "dēng 与 fēng 声母不同（d 与 f），意思是风景、景色。", "增光": "dēng 与 zēng 声母不同（d 与 z），意思是增添光彩。", "声光": "dēng 与 shēng 声母不同（d 与 sh），意思是声音和光线。", "灯管": "guāng 与 guǎn 韵母不同且声调不同，意思是日光灯的灯管。"}, "sentence_index": null, "correct_answer": "灯光"}, "level_3": {"options": [{"text": "灯光", "is_correct": true, "explanation": "正确：灯光是灯发出的光，房间里的灯光可以是温暖的。"}, {"text": "星光", "is_correct": false, "explanation": "语义：星光来自远处的星星，不会在房间里，也不能说温暖。"}, {"text": "阴影", "is_correct": false, "explanation": "搭配：“阴影”指光被遮挡后形成的暗处，不能用“温暖”形容。"}, {"text": "光速", "is_correct": false, "explanation": "语义：光速是光传播的速度，不是房间里的照明，不能说温暖。"}], "explanations": {"灯光": "正确：灯光是灯发出的光，房间里的灯光可以是温暖的。", "星光": "语义：星光来自远处的星星，不会在房间里，也不能说温暖。", "阴影": "搭配：“阴影”指光被遮挡后形成的暗处，不能用“温暖”形容。", "光速": "语义：光速是光传播的速度，不是房间里的照明，不能说温暖。"}, "sentence_index": 0, "correct_answer": "灯光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中午的灯光太强了，出门要戴帽子。", "explanation": "这里应该用〈阳光〉。灯光指灯发出的光，中午照在外面的是太阳的光，要说阳光。"}, {"text": "篝火的灯光照亮了夜空。", "explanation": "这里应该用〈火光〉。灯光指灯发出的光，篝火燃烧发出的光要说火光。"}, {"text": "星星的灯光在夜空中闪烁。", "explanation": "这里应该用〈光芒〉。灯光指灯发出的光，星星自身发出的光要说光芒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灯光", "is_correct": true, "explanation": "正确：灯光是灯发出的光，“柔和的灯光下”指在柔和的照明里吃饭。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声响亮，与“柔和”矛盾，不能作为吃饭的环境。"}, {"text": "尘土", "is_correct": false, "explanation": "搭配：“柔和”不用来形容尘土，“尘土下吃晚饭”也不合理。"}, {"text": "热浪", "is_correct": false, "explanation": "语义：热浪是炎热的气流，与“柔和”冲突，也不能作为吃饭的环境。"}], "explanations": {"灯光": "正确：灯光是灯发出的光，“柔和的灯光下”指在柔和的照明里吃饭。", "雷声": "语义：雷声响亮，与“柔和”矛盾，不能作为吃饭的环境。", "尘土": "搭配：“柔和”不用来形容尘土，“尘土下吃晚饭”也不合理。", "热浪": "语义：热浪是炎热的气流，与“柔和”冲突，也不能作为吃饭的环境。"}, "sentence_index": 6, "correct_answer": "灯光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天灯光很好，正适合在院子里晒被子。", "explanation": "这里应该用〈日光〉。灯光指灯发出的光，晒被子用的太阳光要说日光。"}, {"text": "灶里的灯光烧得很旺，水很快就开了。", "explanation": "这里应该用〈火苗〉。灯光指灯发出的光，灶里燃烧的火焰要说火苗。"}, {"text": "电焊的时候，灯光四处飞溅。", "explanation": "这里应该用〈火花〉。灯光指灯发出的光，迸溅的火星要说火花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角的一个灯光慢慢亮了起来。", "corrected_sentence": "街角的一道灯光慢慢亮了起来。", "error_description": "错误：“一个灯光”；正确：“一道灯光”。修饰“灯光”的量词用“道”“片”“束”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在暖黄的灯光上读书。", "corrected_sentence": "妈妈在暖黄的灯光下读书。", "error_description": "错误：“灯光上”；正确：“灯光下”。“下”表示在某种条件之下，要用“下”；“上”表示物体表面之上，不能用于灯光。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高分", "is_correct": true, "explanation": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "无关：“课本”是学习用的书，与“低分”没有反义关系。"}, {"text": "铅笔", "is_correct": false, "explanation": "无关：“铅笔”是书写工具，与“低分”没有反义关系。"}, {"text": "黑板", "is_correct": false, "explanation": "无关：“黑板”是教室里的设备，与“低分”没有反义关系。"}], "correct_answer": "高分", "explanations": {"高分": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。", "课本": "无关：“课本”是学习用的书，与“低分”没有反义关系。", "铅笔": "无关：“铅笔”是书写工具，与“低分”没有反义关系。", "黑板": "无关：“黑板”是教室里的设备，与“低分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高分", "is_correct": true, "explanation": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。"}, {"text": "饭碗", "is_correct": false, "explanation": "无关：“饭碗”是盛饭的器具，与“低分”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "无关：“雨伞”是遮雨的用具，与“低分”没有反义关系。"}, {"text": "山峰", "is_correct": false, "explanation": "无关：“山峰”是地理事物，与“低分”没有反义关系。"}], "correct_answer": "高分", "explanations": {"高分": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。", "饭碗": "无关：“饭碗”是盛饭的器具，与“低分”没有反义关系。", "雨伞": "无关：“雨伞”是遮雨的用具，与“低分”没有反义关系。", "山峰": "无关：“山峰”是地理事物，与“低分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "低分是考试得到的分数很少。", "primary_collocate": null, "pronunciation": "dī fēn", "ipa": "ti˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这次考试我只得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学考了低分，我不想回家。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了低分，妈妈没有生气。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试得低分的同学要多复习。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分不是失败，是学习的开始。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿着低分的试卷回家了。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说低分的同学可以再考一次。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没复习，他才考了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到试卷上的低分，她哭了。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望英语不再考低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低分段", "label": "复合"}], "register": "口语", "sense_fingerprint": "考试中得到的很少的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白眼", "is_correct": false, "explanation": "语义：“白眼”是别人冷淡的态度，不是考试能得到的结果。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“只得了低分”指考试分数很少，与语境相合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是考试能得到的分数，“只得了雨”语义不合。"}], "explanations": {"白眼": "语义：“白眼”是别人冷淡的态度，不是考试能得到的结果。", "低分": "正确：“只得了低分”指考试分数很少，与语境相合。", "脾气": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。", "雨": "语义：雨不是考试能得到的分数，“只得了雨”语义不合。"}, "sentence_index": 0, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次低分很高，妈妈很开心。", "explanation": "这里应该用〈考分〉。“考分”可以说高，“低分”本身表示分数低，不能说“很高”。"}, {"text": "我这次考了一条低分。", "explanation": "这里应该用〈个〉。“低分”是考试分数，计量用“个”；“条”用于细长的东西。"}, {"text": "我这次考了一座低分。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型固定的东西，不能计量分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "搭配：“老师说……的同学”要求修饰语是表示成绩的词，“饭菜”不能这样修饰。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，与考试成绩无关，“雨伞的同学可以再考一次”句意不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，与考试无关，句意不通。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“低分的同学可以再考一次”指考试成绩低的同学，符合语境。"}], "explanations": {"饭菜": "搭配：“老师说……的同学”要求修饰语是表示成绩的词，“饭菜”不能这样修饰。", "雨伞": "语义：雨伞是遮雨的用具，与考试成绩无关，“雨伞的同学可以再考一次”句意不通。", "沙发": "语义：沙发是家具，与考试无关，句意不通。", "低分": "正确：“低分的同学可以再考一次”指考试成绩低的同学，符合语境。"}, "sentence_index": 6, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的英语低分一直很好，妈妈很骄傲。", "explanation": "这里应该用〈成绩〉。“成绩”可以说好或坏，“低分”表示分数低，不能说“很好”。"}, {"text": "我的英语低分很喜欢唱歌。", "explanation": "这里应该用〈同学〉。低分是分数，不能“喜欢唱歌”，这个动作的主语须是人。"}, {"text": "他这次的低分很高，同学们都很佩服。", "explanation": "这里应该用〈得分〉。“得分”可以说高，“低分”表示分数低，与“很高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试我得了一条低分。", "corrected_sentence": "这次考试我得了一个低分。", "error_description": "错误：“低分”的量词用了“条”。正确应用“个”，“条”多用于细长的东西，不能计量分数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我低分让妈妈很担心。", "corrected_sentence": "我的低分让妈妈很担心。", "error_description": "错误：“我”修饰“低分”时漏了“的”。正确应为“我的低分”，“我”作定语须加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高分", "is_correct": true, "explanation": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”是装东西的袋子，与“低分”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是房屋的构件，与“低分”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与“低分”没有反义关系。"}], "correct_answer": "高分", "explanations": {"高分": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。", "书包": "无关：“书包”是装东西的袋子，与“低分”没有反义关系。", "窗户": "无关：“窗户”是房屋的构件，与“低分”没有反义关系。", "河流": "无关：“河流”是地理事物，与“低分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高分", "is_correct": true, "explanation": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与“低分”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”是种花草的场所，与“低分”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是自然物，与“低分”没有反义关系。"}], "correct_answer": "高分", "explanations": {"高分": "反义：“高分”与“低分”都指分数，高低相对，是反义关系。", "桌子": "无关：“桌子”是家具，与“低分”没有反义关系。", "花园": "无关：“花园”是种花草的场所，与“低分”没有反义关系。", "石头": "无关：“石头”是自然物，与“低分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较低的分数。", "primary_collocate": null, "pronunciation": "dī fēn", "ipa": "ti˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这个电影在网上只得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛里裁判给他打了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分和高分只差几分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店得了低分，客人很少。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的跳水动作得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分不一定是坏事，可以让人进步。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选手们看到低分，都很吃惊。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的低分让他很难过。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评委给这首歌打了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分的作品不能参加下一轮。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低分段", "label": "复合"}], "register": "中性", "sense_fingerprint": "评比、打分中较低的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "搭配：“得”后接的应是可获得的评分，“得了名字”不成立。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“只得了低分”指评分较低，与语境相合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是评分，“只得了雨”不能表示任何评价，语义不合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}], "explanations": {"名字": "搭配：“得”后接的应是可获得的评分，“得了名字”不成立。", "低分": "正确：“只得了低分”指评分较低，与语境相合。", "雨": "语义：雨不是评分，“只得了雨”不能表示任何评价，语义不合。", "脾气": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}, "sentence_index": 0, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学低分很喜欢跑步。", "explanation": "这里应该用〈同学〉。低分是分数，不能“喜欢跑步”，这个动作的主语须是人。"}, {"text": "裁判给他打了一条低分。", "explanation": "这里应该用〈个〉。“低分”是分数，计量用“个”；“条”用于细长的东西，不能计量分数。"}, {"text": "裁判给他打了一座低分。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型固定的东西，不能计量分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能作为“看到”的对象。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音只能听到，不能“看到”，“看到声音”句意不通。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“看到低分”指看到评比中较低的分数，与语境相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能被看到，“看到味道”句意不通。"}], "explanations": {"空气": "语义：空气看不见，不能作为“看到”的对象。", "声音": "语义：声音只能听到，不能“看到”，“看到声音”句意不通。", "低分": "正确：“看到低分”指看到评比中较低的分数，与语境相合。", "味道": "语义：味道不能被看到，“看到味道”句意不通。"}, "sentence_index": 6, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影得到了很高的低分，网上都在夸。", "explanation": "这里应该用〈评价〉。“评价”可以说高或低，“低分”本身表示分数低，不能与“很高”搭配。"}, {"text": "他这次的低分很好，老师很高兴。", "explanation": "这里应该用〈成绩〉。“成绩”可以说好或坏，“低分”表示分数低，不能说“很好”。"}, {"text": "他的低分很高，队友都很兴奋。", "explanation": "这里应该用〈得分〉。“得分”可以说高，“低分”指分数低，与“很高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位选手拿到了一条低分。", "corrected_sentence": "这位选手拿到了一个低分。", "error_description": "错误：“低分”的量词用了“条”。正确应用“个”，“条”多用于细长的东西，不能计量分数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这次只了低分，很难过。", "corrected_sentence": "我这次只得了低分，很难过。", "error_description": "错误：“低分”前漏了动词“得”，写成“只了低分”。正确应为“只得了低分”，“得”与“低分”构成动宾，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
