INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猫是我们常养的小动物，身上软软的，会抓老鼠。", "primary_collocate": null, "pronunciation": "māo", "ipa": "mɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "我家有一只白色的猫。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫喜欢睡在太阳下面。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫的身上软软的。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫晚上抓到了一只老鼠。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹每天给猫喂水和吃的。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫跳上了桌子。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的猫不喜欢洗澡。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫抓着沙发，妈妈很生气。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居养了两只猫。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠看见猫，马上跑了。", "target_word": "猫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "猫咪", "label": "复合"}, {"form": "野猫", "label": "复合"}, {"form": "猫猫", "label": "重叠"}, {"form": "貓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "猫·名词·常养的会抓老鼠的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88345, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猫", "is_correct": true, "explanation": "正确：猫 māo（第一声），指常养的小动物。"}, {"text": "妈", "is_correct": false, "explanation": "mā 与 māo 的韵母不同（少了 -o），意思是妈妈。"}, {"text": "毛", "is_correct": false, "explanation": "máo（第二声）与 māo（第一声）声调不同，意思是毛发。"}, {"text": "冒", "is_correct": false, "explanation": "mào（第四声）与 māo（第一声）声调不同，意思是冒出。"}], "explanations": {"猫": "正确：猫 māo（第一声），指常养的小动物。", "妈": "mā 与 māo 的韵母不同（少了 -o），意思是妈妈。", "毛": "máo（第二声）与 māo（第一声）声调不同，意思是毛发。", "冒": "mào（第四声）与 māo（第一声）声调不同，意思是冒出。"}, "sentence_index": null, "correct_answer": "猫"}, "level_3": {"options": [{"text": "猫", "is_correct": true, "explanation": "正确：“我家有一只白色的猫”描述家里养的动物，语境相符。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不是可以养的东西，“一只白色的歌”没有意义。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“只”不用于桌子，应说“一张白色的桌子”。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“云”的量词是“朵”，不能说“一只白色的云”。"}], "explanations": {"猫": "正确：“我家有一只白色的猫”描述家里养的动物，语境相符。", "歌": "语义：歌不是可以养的东西，“一只白色的歌”没有意义。", "桌子": "搭配：量词“只”不用于桌子，应说“一张白色的桌子”。", "云": "搭配：“云”的量词是“朵”，不能说“一只白色的云”。"}, "sentence_index": 0, "correct_answer": "猫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣的猫很软。", "explanation": "这里应该用〈毛〉。“猫”指动物，毛衣的纤维要说“毛”，不能说“猫”。"}, {"text": "妈妈用猫织了一件毛衣。", "explanation": "这里应该用〈毛线〉。“织”的材料是毛线，猫是动物，不能用来织毛衣。"}, {"text": "他用猫擦干了脸。", "explanation": "这里应该用〈毛巾〉。“擦”要用毛巾等物，猫是动物，不能用来擦脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88345, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "猫", "is_correct": true, "explanation": "正确：猫 māo（第一声），指常养的小动物。"}, {"text": "帽", "is_correct": false, "explanation": "mào（第四声）与 māo（第一声）声调不同，意思是帽子。"}, {"text": "锚", "is_correct": false, "explanation": "máo（第二声）与 māo（第一声）声调不同，意思是船上用来固定船的铁器。"}, {"text": "矛", "is_correct": false, "explanation": "máo（第二声）与 māo（第一声）声调不同，意思是古代的长柄武器。"}], "explanations": {"猫": "正确：猫 māo（第一声），指常养的小动物。", "帽": "mào（第四声）与 māo（第一声）声调不同，意思是帽子。", "锚": "máo（第二声）与 māo（第一声）声调不同，意思是船上用来固定船的铁器。", "矛": "máo（第二声）与 māo（第一声）声调不同，意思是古代的长柄武器。"}, "sentence_index": null, "correct_answer": "猫"}, "level_3": {"options": [{"text": "猫", "is_correct": true, "explanation": "正确：“我的猫不喜欢洗澡”指家里的动物，语境相符。"}, {"text": "花", "is_correct": false, "explanation": "语义：花没有喜好，“我的花不喜欢洗澡”与语境矛盾。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会有喜好，也不能洗澡。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“洗澡”只用于人或动物，汽车要说“洗车”。"}], "explanations": {"猫": "正确：“我的猫不喜欢洗澡”指家里的动物，语境相符。", "花": "语义：花没有喜好，“我的花不喜欢洗澡”与语境矛盾。", "书": "语义：书不会有喜好，也不能洗澡。", "汽车": "搭配：“洗澡”只用于人或动物，汽车要说“洗车”。"}, "sentence_index": 6, "correct_answer": "猫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把猫存进了银行。", "explanation": "这里应该用〈钱〉。“存”的对象是钱，猫是动物，不能存进银行。"}, {"text": "她用猫打开了抽屉。", "explanation": "这里应该用〈钥匙〉。“打开”抽屉要用钥匙，猫是动物，不能用来开抽屉。"}, {"text": "我们用猫煮了汤。", "explanation": "这里应该用〈锅〉。“煮”要用锅，猫是动物，不能用来煮汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家养了一条猫。", "corrected_sentence": "我家养了一只猫。", "error_description": "量词错误：猫应该用“只”，不能用“条”（“条”用于细长的东西）。正确的说法是“一只猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些猫们都很可爱。", "corrected_sentence": "这些猫都很可爱。", "error_description": "“们”只用于指人，“猫”是动物，不能加“们”。正确的说法是“这些猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
