INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "其它是除了说过的这些以外,别的东西。", "primary_collocate": null, "pronunciation": "qí tā", "ipa": "tɕʰi˧˥ tʰa˥", "syllable_count": 2, "sentences": [{"text": "我只买了苹果，其它的东西明天再买。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有书和笔，其它的都是妈妈的。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太贵了，我想看看其它的。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了红色的，其它颜色我都不喜欢。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先做作业，其它的事情等一下再说。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三道菜很好吃，其它的我没有吃。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只学这十个字，其它的下次再学。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿这本书吧，其它的留在这里。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只喝水，不喝咖啡和其它饮料。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里只有一张床，其它东西都没有。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "其他", "label": "异形词"}], "register": "中性", "sense_fingerprint": "代词；指已说过的东西之外的别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其它", "is_correct": true, "explanation": "代词，指苹果之外的别的东西，与“只买了苹果”相合。"}, {"text": "怎么", "is_correct": false, "explanation": "语法：“怎么”是疑问副词，询问方式或原因，不能加“的”修饰“东西”。"}, {"text": "为什么", "is_correct": false, "explanation": "语法：“为什么”询问原因，不能加“的”修饰名词“东西”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，不表示“其余的”，无法承接“只买了苹果”。"}], "explanations": {"其它": "代词，指苹果之外的别的东西，与“只买了苹果”相合。", "怎么": "语法：“怎么”是疑问副词，询问方式或原因，不能加“的”修饰“东西”。", "为什么": "语法：“为什么”询问原因，不能加“的”修饰名词“东西”。", "谁": "语义：“谁”是疑问代词，不表示“其余的”，无法承接“只买了苹果”。"}, "sentence_index": 0, "correct_answer": "其它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想要其它一杯咖啡。", "explanation": "这里应该用〈另一杯〉。其它指所说之外的事物，不能与“一杯”直接组合表示再添一个，应说“另一杯”。"}, {"text": "我会游泳，其它一项运动我还会跳舞。", "explanation": "这里应该用〈另外〉。其它是代词，不能直接与数量短语“一项运动”组合表示再加一项，应说“另外一项运动”。"}, {"text": "首先我们吃饭，其它我们去散步。", "explanation": "这里应该用〈其次〉。其它只指所说之外的别的事物，不表示先后顺序，此处应用“其次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其它", "is_correct": true, "explanation": "代词，指“这十个字”之外的别的字，与“下次再学”相合。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人自身，与“这十个字”之外的其余字不构成对照。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”口语色彩浓，且专指他人，不指学习的字，与书面语境不合。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”会指向“这十个字”，说今天学过的字下次再学，与句意相反。"}], "explanations": {"其它": "代词，指“这十个字”之外的别的字，与“下次再学”相合。", "自己": "语义：“自己”指说话人自身，与“这十个字”之外的其余字不构成对照。", "人家": "语域：“人家”口语色彩浓，且专指他人，不指学习的字，与书面语境不合。", "它们": "语义：“它们”会指向“这十个字”，说今天学过的字下次再学，与句意相反。"}, "sentence_index": 6, "correct_answer": "其它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "其它一课我们要学汉字，语法以后再学。", "explanation": "这里应该用〈首先〉。其它不能直接与数量短语“一课”组合，也不表示先后顺序，此处应用“首先”。"}, {"text": "我想去公园，其它今天下雨了。", "explanation": "这里应该用〈可是〉。其它只指所说之外的别的事物，不能表示转折，两个分句的对比要用“可是”。"}, {"text": "这次考试我考得不错，其它一次我还得了奖。", "explanation": "这里应该用〈另外〉。其它是代词，不能直接与“一次”组合表示再添一件，补充时应用“另外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先做完作业，其它们的事情明天再做。", "corrected_sentence": "我先做完作业，其它的事情明天再做。", "error_description": "错误形式：“其它们”；正确形式：“其它”。“其它”是代词，后面不能加“们”表示复数，应直接说“其它的事情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里有一张桌子和两把椅子，其它地家具都是旧的。", "corrected_sentence": "屋里有一张桌子和两把椅子，其它的家具都是旧的。", "error_description": "错误形式：“其它地家具”；正确形式：“其它的家具”。“地”是状语标记，用于修饰动词、形容词；“其它”修饰名词“家具”，应用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
