INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "玩笑是为了让大家笑，说的不是真的话。", "primary_collocate": null, "pronunciation": "wán xiào", "ipa": "wan˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他说的是玩笑，你别当真。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是开个玩笑，你别生气。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你别信，是开玩笑的。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚才那句话只是玩笑，不用当真。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，她刚才只是开玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把他的玩笑当真。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的那句玩笑，大家都笑出了声。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说要去月亮上工作？别开玩笑了。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他会飞，纯粹是开玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开玩笑要看人，有些话不能说。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个玩笑", "label": "量词搭配"}, {"form": "开玩笑", "label": "常用搭配"}, {"form": "玩笑话", "label": "复合词"}], "register": "口语", "sense_fingerprint": "为了让人笑而说的不真实的话，不能当真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩笑", "is_correct": true, "explanation": "正确：“玩笑”指为了逗人笑而说的不真实的话，与后面的“你别当真”相呼应。"}, {"text": "实话", "is_correct": false, "explanation": "语义：“实话”是真实的话，接上“你别当真”前后矛盾。"}, {"text": "事实", "is_correct": false, "explanation": "语义：“事实”是真实的情况，不能说“你别当真”。"}, {"text": "礼物", "is_correct": false, "explanation": "配价：“说的是”后面要接所说的话或内容，“礼物”不是可以说的内容。"}], "explanations": {"玩笑": "正确：“玩笑”指为了逗人笑而说的不真实的话，与后面的“你别当真”相呼应。", "实话": "语义：“实话”是真实的话，接上“你别当真”前后矛盾。", "事实": "语义：“事实”是真实的情况，不能说“你别当真”。", "礼物": "配价：“说的是”后面要接所说的话或内容，“礼物”不是可以说的内容。"}, "sentence_index": 0, "correct_answer": "玩笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了骗我的钱，他编了一个玩笑。", "explanation": "这里应该用〈谎话〉。玩笑是为了逗人笑而说的话，不是为了骗人；“为了骗钱”这种目的要用谎话。"}, {"text": "他向我许下了一个玩笑，说下周一定还钱。", "explanation": "这里应该用〈承诺〉。承诺是郑重许下、要兑现的话，玩笑只是逗人笑的话，不能用来许下。"}, {"text": "警察在现场找到了关键玩笑，案子因此破了。", "explanation": "这里应该用〈证据〉。证据是能证明事实的东西，玩笑只是逗人笑的话，不能当证据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩笑", "is_correct": true, "explanation": "正确：“玩笑”是逗人笑的话，与后面的“大家都笑出了声”相符。"}, {"text": "忠告", "is_correct": false, "explanation": "语义：“忠告”是劝人的话，不会让人笑出声，与句意不符。"}, {"text": "箴言", "is_correct": false, "explanation": "语域：“箴言”是书面语，口语里一般不说“那句箴言”，而且不会让人笑出声。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是应认真对待的道理，不会让人笑出声，与句意不符。"}], "explanations": {"玩笑": "正确：“玩笑”是逗人笑的话，与后面的“大家都笑出了声”相符。", "忠告": "语义：“忠告”是劝人的话，不会让人笑出声，与句意不符。", "箴言": "语域：“箴言”是书面语，口语里一般不说“那句箴言”，而且不会让人笑出声。", "道理": "语义：“道理”是应认真对待的道理，不会让人笑出声，与句意不符。"}, "sentence_index": 6, "correct_answer": "玩笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发烧时说的全是玩笑，醒来后什么都不记得。", "explanation": "这里应该用〈胡话〉。玩笑是有意逗人的话，发烧时无意说出的话不叫玩笑。"}, {"text": "我们制定了一个玩笑，明天开始执行。", "explanation": "这里应该用〈计划〉。计划是要执行的安排，玩笑只是逗人笑的话，不能用来制定和执行。"}, {"text": "经过仔细调查，他得出了一个玩笑。", "explanation": "这里应该用〈结论〉。结论是经过推理得出的判断，玩笑是逗人笑的话，不能说“得出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为他是认真的，其实那只是一条玩笑。", "corrected_sentence": "我以为他是认真的，其实那只是一句玩笑。", "error_description": "量词用错：不真实的话要用“句”来数，“条”用于长条形的东西，不能说“一条玩笑”。正确是“一句玩笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才打玩笑，我是认真的。", "corrected_sentence": "他刚才开玩笑，我是认真的。", "error_description": "动词用错：“玩笑”与“开”搭配，应说“开玩笑”，不能说“打玩笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
