INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为逗人发笑而说的话或做的事。", "primary_collocate": null, "pronunciation": "wán xiào", "ipa": "wan˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "同学们给他开了个玩笑，他笑了。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩笑有点儿过分了。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在我的杯子里放了糖，这是个玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩总是互相开玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四月一日，大家都喜欢开玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个玩笑，全家人都笑了。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玩笑只能和好朋友开。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢别人拿她的身高开玩笑。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的玩笑太多，大家总是笑个不停。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸总有新玩笑，家里很热闹。", "target_word": "玩笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个玩笑", "label": "量词搭配"}, {"form": "开玩笑", "label": "常用搭配"}, {"form": "玩笑话", "label": "复合词"}], "register": "口语", "sense_fingerprint": "逗人发笑的话语或举动，包括捉弄人的小行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩笑", "is_correct": true, "explanation": "正确：“玩笑”是逗人发笑的举动，与“他笑了”相符，“开了个”的搭配也对。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”会让人不快，不会让人笑，与“他笑了”矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“开”不跟“玩具”搭配，玩具要说“玩”或“买”，不能说“开玩具”。"}, {"text": "通知", "is_correct": false, "explanation": "搭配：“通知”要说“发”或“下”，“开了个通知”不通。"}], "explanations": {"玩笑": "正确：“玩笑”是逗人发笑的举动，与“他笑了”相符，“开了个”的搭配也对。", "批评": "语义：“批评”会让人不快，不会让人笑，与“他笑了”矛盾。", "玩具": "搭配：“开”不跟“玩具”搭配，玩具要说“玩”或“买”，不能说“开玩具”。", "通知": "搭配：“通知”要说“发”或“下”，“开了个通知”不通。"}, "sentence_index": 0, "correct_answer": "玩笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出了一个玩笑，大家猜了半天也没猜出来。", "explanation": "这里应该用〈谜语〉。“出”搭配谜语，玩笑要说“开”或“讲”，不能说“出玩笑”。"}, {"text": "他去商店买了一个玩笑，拿回家给弟弟看。", "explanation": "这里应该用〈玩具〉。玩笑是说出来或做出来的，不能买，买到的是玩具。"}, {"text": "他把玩笑端上了桌，大家都开心地吃了起来。", "explanation": "这里应该用〈饭菜〉。玩笑是说的话或做的事，不能端上桌、拿来吃；端上桌的是饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩笑", "is_correct": true, "explanation": "正确：“玩笑”可以和“开”搭配，“这种玩笑只能和好朋友开”句意通顺。"}, {"text": "秘密", "is_correct": false, "explanation": "搭配：“开”不跟“秘密”搭配，秘密要说“说”或“透露”。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”不能拿来和朋友“开”，与“开玩笑”的意思不合。"}, {"text": "笔记", "is_correct": false, "explanation": "语义：“笔记”是记录的东西，不能拿来和朋友“开”，与句意不合。"}], "explanations": {"玩笑": "正确：“玩笑”可以和“开”搭配，“这种玩笑只能和好朋友开”句意通顺。", "秘密": "搭配：“开”不跟“秘密”搭配，秘密要说“说”或“透露”。", "病": "语义：“病”不能拿来和朋友“开”，与“开玩笑”的意思不合。", "笔记": "语义：“笔记”是记录的东西，不能拿来和朋友“开”，与句意不合。"}, "sentence_index": 6, "correct_answer": "玩笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参加了一个玩笑，大家都很开心。", "explanation": "这里应该用〈游戏〉。“参加”搭配游戏、比赛，玩笑不能参加。"}, {"text": "他在比赛中赢得了一个玩笑，大家都鼓掌。", "explanation": "这里应该用〈奖品〉。“赢得”的对象是奖品、奖杯，玩笑是逗人笑的话，不能被赢得。"}, {"text": "他在会上宣读了一个玩笑，大家都笑了起来。", "explanation": "这里应该用〈宣言〉。“宣读”搭配宣言、文件，玩笑是逗人笑的话，不能宣读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总爱给同学打玩笑，大家都习惯了。", "corrected_sentence": "他总爱给同学开玩笑，大家都习惯了。", "error_description": "错误：动词用错。“玩笑”与“开”搭配，应说“开玩笑”，不能说“打玩笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总用我开玩笑，我很生气。", "corrected_sentence": "他总拿我开玩笑，我很生气。", "error_description": "错误：介词用错。引出被开玩笑的人要用“拿”，应说“拿我开玩笑”，“用”不能这样引出人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债是借了别人的钱或东西，还没有还。", "primary_collocate": null, "pronunciation": "zhài", "ipa": "ʈʂaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他借钱买房，现在还有很多债。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔债他一直没有还。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每个月都用工资还债。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欠了一身债，晚上睡不着觉。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想借债过日子。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友向他要债，他只好先借钱。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，有债就要还。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还清了所有的债，心里很轻松。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了开店，他们背了一笔债。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔债已经拖了三年，还没有还。", "target_word": "债", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔债", "label": "量词"}, {"form": "债务", "label": "复合"}, {"form": "债主", "label": "复合"}], "register": "通用", "sense_fingerprint": "借了别人的钱或东西而没有还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债", "is_correct": true, "explanation": "正确。债（第四声）指借了别人的钱或东西还没还。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 zhài 声母不同（z 与 zh），意思是又一次。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 zhài 声调不同（第一声与第四声），意思是采下、摘取。"}, {"text": "宅", "is_correct": false, "explanation": "zhái 与 zhài 声调不同（第二声），意思是住所。"}, {"text": "窄", "is_correct": false, "explanation": "zhǎi 与 zhài 声调不同（第三声与第四声），意思是狭窄。"}], "explanations": {"债": "正确。债（第四声）指借了别人的钱或东西还没还。", "再": "zài 与 zhài 声母不同（z 与 zh），意思是又一次。", "摘": "zhāi 与 zhài 声调不同（第一声与第四声），意思是采下、摘取。", "宅": "zhái 与 zhài 声调不同（第二声），意思是住所。", "窄": "zhǎi 与 zhài 声调不同（第三声与第四声），意思是狭窄。"}, "sentence_index": null, "correct_answer": "债"}, "level_3": {"options": [{"text": "债", "is_correct": true, "explanation": "这里应该用〈债〉。“很多债”指欠下的钱没还，与借钱买房的语境一致。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与借钱买房无关，不能说“还有很多钥匙”。"}, {"text": "利率", "is_correct": false, "explanation": "搭配：“利率”是比率，不能用“很多”来计数。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与借钱买房无关，这里不能说“还有很多天气”。"}], "explanations": {"债": "这里应该用〈债〉。“很多债”指欠下的钱没还，与借钱买房的语境一致。", "钥匙": "语义：钥匙是开锁的工具，与借钱买房无关，不能说“还有很多钥匙”。", "利率": "搭配：“利率”是比率，不能用“很多”来计数。", "天气": "语义：天气与借钱买房无关，这里不能说“还有很多天气”。"}, "sentence_index": 0, "correct_answer": "债"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行把一笔债取了出来，准备买车。", "explanation": "这里应该用〈存款〉。债是欠别人的钱，不能像存在银行里的钱那样取出；从银行取出的钱是〈存款〉。"}, {"text": "他每年都要交债。", "explanation": "这里应该用〈学费〉。债是要还的，不能用“交”；每年为上学交的钱是〈学费〉。"}, {"text": "他是我的债，每个月都来要钱。", "explanation": "这里应该用〈债主〉。债指欠下的钱或东西，不指人；放债给别人、向人讨钱的人要用〈债主〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "债", "is_correct": true, "explanation": "正确。债（第四声）指欠别人的钱或东西。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zhài 韵母不同（an 与 ai），意思是站立、车站。"}, {"text": "晒", "is_correct": false, "explanation": "shài 与 zhài 声母不同（sh 与 zh），意思是晒太阳。"}, {"text": "在", "is_correct": false, "explanation": "zài 与 zhài 声母不同（z 与 zh），意思是在某处。"}], "explanations": {"债": "正确。债（第四声）指欠别人的钱或东西。", "站": "zhàn 与 zhài 韵母不同（an 与 ai），意思是站立、车站。", "晒": "shài 与 zhài 声母不同（sh 与 zh），意思是晒太阳。", "在": "zài 与 zhài 声母不同（z 与 zh），意思是在某处。"}, "sentence_index": null, "correct_answer": "债"}, "level_3": {"options": [{"text": "债", "is_correct": true, "explanation": "这里应该用〈债〉。“有债就要还”指欠下的钱要归还，与“还”搭配。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“还”能搭配钱、东西，不能说“还歌”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不能被借用或归还，“有眼睛就要还”不合常理。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能用“有时间就要还”表示欠下的东西。"}], "explanations": {"债": "这里应该用〈债〉。“有债就要还”指欠下的钱要归还，与“还”搭配。", "歌": "搭配：“还”能搭配钱、东西，不能说“还歌”。", "眼睛": "语义：眼睛不能被借用或归还，“有眼睛就要还”不合常理。", "时间": "语义：时间是抽象概念，不能用“有时间就要还”表示欠下的东西。"}, "sentence_index": 6, "correct_answer": "债"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考了一笔债，妈妈很生气。", "explanation": "这里应该用〈成绩〉。债指欠下的钱或东西，不能是考试的结果；考试的结果要说〈成绩〉。"}, {"text": "他因为闯红灯，被交警罚了一笔债。", "explanation": "这里应该用〈罚款〉。交警处罚的钱要用〈罚款〉；债指欠别人的钱，不是处罚。"}, {"text": "他每晚帮孩子检查债。", "explanation": "这里应该用〈作业〉。债指欠下的钱或东西，不能检查；帮孩子检查学习任务要用〈作业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还有一个债没还。", "corrected_sentence": "他还有一笔债没还。", "error_description": "“债”的量词是“笔”，不能说“一个债”；应说“一笔债”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于还好了那笔债。", "corrected_sentence": "他终于还清了那笔债。", "error_description": "“还清”表示全部还完，“还好”不能作为还债的结果补语；应说“还清了那笔债”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
