INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身是人的身体，不是头和手脚。", "primary_collocate": null, "pronunciation": "shēn", "ipa": "ʂən˥", "syllable_count": 1, "sentences": [{"text": "小女孩蹲下身，看地上的小花。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人弯下身，捡起地上的一张纸。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈俯下身，亲了亲睡着的孩子。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一进来，大家都站起身。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他半夜醒了，从床上坐起身。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民累了，直起身，看看天。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻过身，又睡着了。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背过身，不想让我看见他哭。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很窄，我侧过身，让他先走。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转过身，向我挥了挥手。", "target_word": "身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身体", "label": "复合"}, {"form": "全身", "label": "复合"}], "register": "中性", "sense_fingerprint": "身:名词,人的身体,躯干部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b2c49-67cb-4e0b-8485-554d907afa77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "身", "is_correct": true, "explanation": "正确。身是人的身体，不是头和手脚。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是神灵、精神。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（eng 与 en），意思是生命、出生。"}, {"text": "真", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真实。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shēn 韵母不同（an 与 en），意思是山。"}], "explanations": {"身": "正确。身是人的身体，不是头和手脚。", "神": "shén（第二声）与 shēn（第一声）声调不同，意思是神灵、精神。", "生": "shēng 与 shēn 韵母不同（eng 与 en），意思是生命、出生。", "真": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真实。", "山": "shān 与 shēn 韵母不同（an 与 en），意思是山。"}, "sentence_index": null, "correct_answer": "身"}, "level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "正确。「蹲下身」是固定说法，指身体向下弯。"}, {"text": "脚", "is_correct": false, "explanation": "语义：蹲下的是整个身体，脚只是肢体，不能作「蹲下」的对象。"}, {"text": "头", "is_correct": false, "explanation": "搭配：「蹲下」后不接「头」，头不能作这个动作的对象。"}, {"text": "手", "is_correct": false, "explanation": "配价：「蹲下」不带「手」作宾语，手不能与「蹲下」组合。"}], "explanations": {"身": "正确。「蹲下身」是固定说法，指身体向下弯。", "脚": "语义：蹲下的是整个身体，脚只是肢体，不能作「蹲下」的对象。", "头": "搭配：「蹲下」后不接「头」，头不能作这个动作的对象。", "手": "配价：「蹲下」不带「手」作宾语，手不能与「蹲下」组合。"}, "sentence_index": 0, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用身拿起了桌上的杯子。", "explanation": "这里应该用〈手〉。拿东西要用手，身指身体，不指手。"}, {"text": "我每天坚持锻炼身，身体越来越好。", "explanation": "这里应该用〈身体〉。锻炼的对象要说身体，身不能单独作锻炼的宾语。"}, {"text": "天冷了，他把帽子戴在身上。", "explanation": "这里应该用〈头〉。帽子戴在头上，身指身体，不指头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88353, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "身", "is_correct": true, "explanation": "正确。身是人的身体，不是头和手脚。"}, {"text": "声", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（eng 与 en），意思是声音。"}, {"text": "针", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh 与 sh），意思是针。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shēn（第一声）声调不同，意思是审查。"}], "explanations": {"身": "正确。身是人的身体，不是头和手脚。", "声": "shēng 与 shēn 韵母不同（eng 与 en），意思是声音。", "针": "zhēn 与 shēn 声母不同（zh 与 sh），意思是针。", "审": "shěn（第三声）与 shēn（第一声）声调不同，意思是审查。"}, "sentence_index": null, "correct_answer": "身"}, "level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "正确。「翻过身」指身体翻转，是固定说法。"}, {"text": "脸", "is_correct": false, "explanation": "语义：脸不能整体翻转，「翻过」说的是身体的翻动。"}, {"text": "腿", "is_correct": false, "explanation": "搭配：「翻过」后不接「腿」，腿不能作翻转的对象。"}, {"text": "肩", "is_correct": false, "explanation": "语义：肩不能整体翻转，与「又睡着了」的动作不符。"}], "explanations": {"身": "正确。「翻过身」指身体翻转，是固定说法。", "脸": "语义：脸不能整体翻转，「翻过」说的是身体的翻动。", "腿": "搭配：「翻过」后不接「腿」，腿不能作翻转的对象。", "肩": "语义：肩不能整体翻转，与「又睡着了」的动作不符。"}, "sentence_index": 6, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗外闪过一个身，我没看清是谁。", "explanation": "这里应该用〈身影〉。看到的人影要说身影，身指人的身体，不单独指人影。"}, {"text": "我把书放进身里，带去学校。", "explanation": "这里应该用〈书包〉。身指身体，不能当作装东西的容器，装书要用书包。"}, {"text": "这个身很聪明，学习很努力。", "explanation": "这里应该用〈人〉。身指身体，不能用来指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他蹲身下，捡起了地上的钥匙。", "corrected_sentence": "他蹲下身，捡起了地上的钥匙。", "error_description": "「蹲身下」错，应说「蹲下身」。「下」是结果补语，要紧跟动词，「身」作宾语放在最后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他翻身过，又接着看书。", "corrected_sentence": "他翻过身，又接着看书。", "error_description": "「翻身过」错，「过」是动态助词，要紧跟动词，应说「翻过身」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e14bf10c-a340-47c7-aa70-29015ef8edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "返回", "is_correct": true, "explanation": "返回与“前往”是反义：前往是朝某处去，返回是回到原处。"}, {"text": "学习", "is_correct": false, "explanation": "学习与“前往”没有反义关系，二者不是方向相反的行为。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与“前往”没有反义关系，二者不是相对的动作。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与“前往”没有反义关系，二者不是方向相反的动作。"}], "correct_answer": "返回", "explanations": {"返回": "返回与“前往”是反义：前往是朝某处去，返回是回到原处。", "学习": "学习与“前往”没有反义关系，二者不是方向相反的行为。", "吃饭": "吃饭与“前往”没有反义关系，二者不是相对的动作。", "睡觉": "睡觉与“前往”没有反义关系，二者不是方向相反的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
