INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "前往就是往那里去。", "primary_collocate": null, "pronunciation": "qián wǎng", "ipa": "t͡ɕʰjɛn˧˥ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "我们明天前往上海。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐飞机前往北京开会。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家马上前往一号门。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她前往机场接朋友。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们前往公园参加活动。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经前往车站了。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很快前往现场。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐火车前往海边。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理下午前往工厂检查。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们前往山上看日出。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前往了", "label": "完成体"}, {"form": "前往过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "动词，前往某地，去到那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前往", "is_correct": true, "explanation": "正确：“前往”后接地点，表示朝那个地方去，与“明天”的安排相符。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”后接地点要加“到”或“去”，不能直接说“出发上海”。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”后接的是交通工具，不能直接接地名“上海”。"}, {"text": "逃往", "is_correct": false, "explanation": "语义：“逃往”含有逃避的意思，与“我们明天”的正常出行不相符。"}], "explanations": {"前往": "正确：“前往”后接地点，表示朝那个地方去，与“明天”的安排相符。", "出发": "配价：“出发”后接地点要加“到”或“去”，不能直接说“出发上海”。", "坐": "配价：“坐”后接的是交通工具，不能直接接地名“上海”。", "逃往": "语义：“逃往”含有逃避的意思，与“我们明天”的正常出行不相符。"}, "sentence_index": 0, "correct_answer": "前往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她下午前往王老师。", "explanation": "这里应该用〈拜访〉。“前往”后面接地点，不能直接接人，应说“拜访王老师”。"}, {"text": "他前往站在门口等人。", "explanation": "这里应该用〈走到〉。“前往”表示向某地移动，“站在门口”是静止的状态，二者不能搭配，应说“他走到门口等人”。"}, {"text": "我把这本书前往桌子上。", "explanation": "这里应该用〈放〉。“前往”表示移动到某地，把东西放到某处要用“放”，应说“我把这本书放在桌子上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前往", "is_correct": true, "explanation": "正确：“前往”表示朝某处去，与“很快”的行动节奏相符，句子通顺。"}, {"text": "逗留", "is_correct": false, "explanation": "语义：“逗留”表示停留不走，与“很快”的节奏矛盾。"}, {"text": "徘徊", "is_correct": false, "explanation": "语义：“徘徊”表示来回走动、停留不前，与“很快”矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能直接带“现场”作目的地。"}], "explanations": {"前往": "正确：“前往”表示朝某处去，与“很快”的行动节奏相符，句子通顺。", "逗留": "语义：“逗留”表示停留不走，与“很快”的节奏矛盾。", "徘徊": "语义：“徘徊”表示来回走动、停留不前，与“很快”矛盾。", "散步": "配价：“散步”是不及物动词，不能直接带“现场”作目的地。"}, "sentence_index": 6, "correct_answer": "前往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客们在湖边前往，聊了一下午天。", "explanation": "这里应该用〈散步〉。“前往”是有目的地的移动，在湖边悠闲走动聊天要用“散步”。"}, {"text": "游客们前往在山上。", "explanation": "这里应该用〈待〉。“前往”表示向某地移动，不能接“在＋地点”表示停留，应说“游客们待在山上”。"}, {"text": "这里前往很多游客。", "explanation": "这里应该用〈吸引〉。“前往”的主语须是能移动的人，地点不能去“前往”游客；地点吸引很多游客要用“吸引”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们后天前往了广州。", "corrected_sentence": "我们后天前往广州。", "error_description": "错误：“后天”是将来的时间，“前往”后面不能用“了”表示已经完成。应去掉“了”，说“我们后天前往广州”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午前往到学校。", "corrected_sentence": "他下午前往学校。", "error_description": "“前往”本身已经表示去某处，后面不能再加“到”，应说“前往学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
