INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向某个地方去;到某处去。", "primary_collocate": null, "pronunciation": "qián wǎng", "ipa": "t͡ɕʰjɛn˧˥ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "老师带学生前往博物馆。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人前往西藏旅行。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请前往二楼办手续。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船前往小岛。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前往国外学习了。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家前往教室上课。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，我们前往饭店。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车前往朋友家。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部分客人前往会议厅。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她前往医院看望奶奶。", "target_word": "前往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前往了", "label": "完成体"}, {"form": "前往过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "动词，向某处去，到某处去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前往", "is_correct": true, "explanation": "正确：“前往”表示向某处去，与“老师带学生”去博物馆的行动相符。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”后接地点要加“到”或“去”，不能直接说“出发博物馆”。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”后接交通工具，不能直接接地点“博物馆”。"}, {"text": "闯入", "is_correct": false, "explanation": "语义：“闯入”含有擅自进入的意思，与老师带学生参观的情况不符。"}], "explanations": {"前往": "正确：“前往”表示向某处去，与“老师带学生”去博物馆的行动相符。", "出发": "配价：“出发”后接地点要加“到”或“去”，不能直接说“出发博物馆”。", "坐": "配价：“坐”后接交通工具，不能直接接地点“博物馆”。", "闯入": "语义：“闯入”含有擅自进入的意思，与老师带学生参观的情况不符。"}, "sentence_index": 0, "correct_answer": "前往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们前往老师。", "explanation": "这里应该用〈见〉。“前往”后面接地点，不能直接接人，应说“去见老师”。"}, {"text": "她前往坐在沙发上。", "explanation": "这里应该用〈走到〉。“前往”表示向某地移动，“坐在沙发上”是静止的状态，应说“她走到沙发旁坐下”。"}, {"text": "我们在街上前往，买了很多东西。", "explanation": "这里应该用〈逛〉。“前往”是有目的地的移动，没有目的地的随意走动、购物要用“逛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前往", "is_correct": true, "explanation": "正确：“前往”表示去某处，与“比赛结束后”去饭店的安排相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能直接带“饭店”作目的地。"}, {"text": "登上", "is_correct": false, "explanation": "配价：“登上”后接的是高处的物体，不能接“饭店”。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”含有逃避的意思，与比赛后正常去饭店不相符。"}], "explanations": {"前往": "正确：“前往”表示去某处，与“比赛结束后”去饭店的安排相符。", "散步": "配价：“散步”是不及物动词，不能直接带“饭店”作目的地。", "登上": "配价：“登上”后接的是高处的物体，不能接“饭店”。", "逃离": "语义：“逃离”含有逃避的意思，与比赛后正常去饭店不相符。"}, "sentence_index": 6, "correct_answer": "前往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她前往我这儿来玩。", "explanation": "这里应该用〈过来〉。“前往”是离开说话人去别处，朝说话人的方向来要用“过来”，“前往”与“来”方向相反。"}, {"text": "她前往在医院里。", "explanation": "这里应该用〈待〉。“前往”表示向某地移动，不能接“在＋地点”表示停留。"}, {"text": "她前往奶奶。", "explanation": "这里应该用〈看望〉。“前往”后面接地点，不能直接接人，应说“看望奶奶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们前往去图书馆学习。", "corrected_sentence": "同学们前往图书馆学习。", "error_description": "“前往”本身已经表示去，后面不能再加动词“去”，应说“前往图书馆学习”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她向前往郊外看望奶奶。", "corrected_sentence": "她前往郊外看望奶奶。", "error_description": "错误：“前往”本身已经表示向某处去，前面不能再加介词“向”。应直接说“前往郊外”，即“她前往郊外看望奶奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
