INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进行球类运动的场地。", "primary_collocate": null, "pronunciation": "qiú chǎng", "ipa": "tɕʰiou̯˧˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个球场可以打篮球，也可以踢足球。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场的地面刚刚修好了。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，球员先在球场上热身。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有三个大球场。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场里的灯突然坏了。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷从四面八方来到球场。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场四周都有高高的网。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把球场打扫得很干净。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球场的地是红色的。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场门口站着很多等票的人。", "target_word": "球场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个球场", "label": "量词"}, {"form": "足球场", "label": "复合"}, {"form": "网球场", "label": "复合"}, {"form": "球場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "球场：进行球类运动或比赛的场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球场", "is_correct": true, "explanation": "正确。球场是进行球类运动的场地，句中说可以打篮球、踢足球。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：「游泳池」是用来游泳的，不能打篮球、踢足球。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是看书的地方，无法用来打篮球。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房」是做饭的地方，不是运动场地，不能打篮球、踢足球。"}], "explanations": {"球场": "正确。球场是进行球类运动的场地，句中说可以打篮球、踢足球。", "游泳池": "语义：「游泳池」是用来游泳的，不能打篮球、踢足球。", "图书馆": "语义：「图书馆」是看书的地方，无法用来打篮球。", "厨房": "语义：「厨房」是做饭的地方，不是运动场地，不能打篮球、踢足球。"}, "sentence_index": 0, "correct_answer": "球场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的球场每天生产三万辆汽车。", "explanation": "这里应该用〈工厂〉。球场是进行球类运动的场地，生产汽车要在〈工厂〉。"}, {"text": "这个球场可以游泳，也可以潜水。", "explanation": "这里应该用〈游泳池〉。球场是进行球类运动的场地，不能用来游泳。"}, {"text": "妈妈在这个球场里熨烫衣服。", "explanation": "这里应该用〈家〉。球场是进行球类运动的场地，熨烫衣服一般在家里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球场", "is_correct": true, "explanation": "正确。球场是比赛场地，四周围有高网，句意相符。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：「花瓶」不是有网围绕的场地，「四周都有高高的网」与它不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：「书包」是背着的袋子，不会「四周都有高高的网」。"}, {"text": "饭桌", "is_correct": false, "explanation": "搭配：「饭桌」四周不会有高网，「高高的网」与饭桌的特征不搭配。"}], "explanations": {"球场": "正确。球场是比赛场地，四周围有高网，句意相符。", "花瓶": "语义：「花瓶」不是有网围绕的场地，「四周都有高高的网」与它不符。", "书包": "语义：「书包」是背着的袋子，不会「四周都有高高的网」。", "饭桌": "搭配：「饭桌」四周不会有高网，「高高的网」与饭桌的特征不搭配。"}, "sentence_index": 6, "correct_answer": "球场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校在球场里印刷了三万本书。", "explanation": "这里应该用〈印刷厂〉。球场是进行球类运动的场地，印书要在〈印刷厂〉。"}, {"text": "这个球场的书架上摆满了旧书。", "explanation": "这里应该用〈书店〉。球场是运动场地，不会摆满书架，卖书要在〈书店〉。"}, {"text": "球场的柜台前排着很多取钱的人。", "explanation": "这里应该用〈银行〉。球场不办理取钱业务，取钱要去〈银行〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校旁边有两张新球场。", "corrected_sentence": "学校旁边有两个新球场。", "error_description": "球场应该用量词「个」。正确：学校旁边有两个新球场。错误：用了量词「张」，「张」用于平而薄的东西，如纸、桌子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们往球场上踢足球。", "corrected_sentence": "孩子们在球场上踢足球。", "error_description": "表示在球场里进行活动，要用介词「在」。正确：孩子们在球场上踢足球。错误：用了「往」，「往」表示动作的方向，不表示活动的地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
