INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机中用于暂时存放程序和数据的存储器。", "primary_collocate": null, "pronunciation": "nèi cún", "ipa": "nei̯˥˩ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "内存用来暂时存放程序和数据。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内存里的数据，关机后就会消失。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序运行时，要先把数据放进内存。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内存的读写速度比硬盘快得多。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑断电后，内存中的内容不会保留。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内存和硬盘不同，它不能长期保存文件。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统会自动管理内存的使用。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内存容量越大，电脑同时处理的任务越多。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种内存的频率比较高，价格也贵一些。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序出错时，内存中的数据可能会丢失。", "target_word": "内存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "内存条", "label": "复合"}, {"form": "运行内存", "label": "复合"}, {"form": "內存", "label": "繁体"}], "register": "书面", "sense_fingerprint": "计算机中暂时存放程序和数据的存储器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "键盘", "is_correct": false, "explanation": "语义：“键盘”是用来输入文字的设备，不能存放程序和数据。"}, {"text": "鼠标", "is_correct": false, "explanation": "语义：「鼠标」是输入设备，不用来存放程序和数据。"}, {"text": "显示器", "is_correct": false, "explanation": "搭配：“显示器”只说显示内容，不说存放程序和数据。"}, {"text": "内存", "is_correct": true, "explanation": "内存：计算机中用于暂时存放程序和数据的存储器，符合句意。"}], "explanations": {"键盘": "语义：“键盘”是用来输入文字的设备，不能存放程序和数据。", "鼠标": "语义：「鼠标」是输入设备，不用来存放程序和数据。", "显示器": "搭配：“显示器”只说显示内容，不说存放程序和数据。", "内存": "内存：计算机中用于暂时存放程序和数据的存储器，符合句意。"}, "sentence_index": 0, "correct_answer": "内存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "内存断电后，数据还能保留。", "explanation": "这里应该用〈硬盘〉。内存断电后数据会消失，断电后仍能保留数据的是〈硬盘〉。"}, {"text": "内存负责显示画面。", "explanation": "这里应该用〈显示器〉。内存只负责暂时存放程序和数据，显示画面要用〈显示器〉。"}, {"text": "内存负责保护电脑不受病毒攻击。", "explanation": "这里应该用〈杀毒软件〉。内存只暂时存放程序和数据，不能防御病毒，防病毒要用〈杀毒软件〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画面", "is_correct": false, "explanation": "搭配：“管理”的对象一般是资源或事务，不说管理画面的使用。"}, {"text": "语气", "is_correct": false, "explanation": "语义：“语气”是说话的口气，与管理资源的意思无关。"}, {"text": "内存", "is_correct": true, "explanation": "内存：计算机中用于暂时存放程序和数据的存储器，系统管理的是它的使用，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气候状况，与系统管理资源无关。"}], "explanations": {"画面": "搭配：“管理”的对象一般是资源或事务，不说管理画面的使用。", "语气": "语义：“语气”是说话的口气，与管理资源的意思无关。", "内存": "内存：计算机中用于暂时存放程序和数据的存储器，系统管理的是它的使用，符合句意。", "天气": "语义：“天气”指气候状况，与系统管理资源无关。"}, "sentence_index": 6, "correct_answer": "内存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "内存负责给电脑降温。", "explanation": "这里应该用〈散热器〉。内存只负责暂存数据，给电脑降温要用〈散热器〉。"}, {"text": "内存负责移动光标。", "explanation": "这里应该用〈鼠标〉。内存不负责控制光标，移动光标要用〈鼠标〉。"}, {"text": "这辆车的内存很大，一箱油能跑很远。", "explanation": "这里应该用〈油箱〉。内存是电脑里暂存数据的地方，说车的油量要用〈油箱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑装了一条内存们，程序跑得很快。", "corrected_sentence": "这台电脑装了一条内存，程序跑得很快。", "error_description": "错误形式是“一条内存们”，正确形式是“一条内存”。“们”只用于指人的名词，“内存”是物，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑换了一本新内存，运行快多了。", "corrected_sentence": "这台电脑换了一条新内存，运行快多了。", "error_description": "错误形式是“一本新内存”，正确形式是“一条新内存”。“本”用于书籍，内存条应按“条”计量，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
