INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选手是被选出来去比赛的人。", "primary_collocate": null, "pronunciation": "xuǎn shǒu", "ipa": "ɕɥɛn˨˩˦ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位选手跑得很快。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十位选手站在起跑线上。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们学校的游泳选手。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，选手们都很紧张。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个选手第一次参加比赛。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的乒乓球选手非常有名。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众给每位选手送上了花。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选手每天练习五个小时。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想做一名好选手。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选手们在休息室里等着上场。", "target_word": "选手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选手们", "label": "复数"}], "register": "中性", "sense_fingerprint": "被选出来参加比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选手", "is_correct": true, "explanation": "选手：被选出来参加比赛的人，符合“跑得很快”的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "量词：“位”只用于人，不能说“这位汽车”。"}, {"text": "小狗", "is_correct": false, "explanation": "量词：“位”只用于人，小狗应该说“这只小狗”。"}, {"text": "婴儿", "is_correct": false, "explanation": "常识：婴儿还不会跑，与“跑得很快”矛盾。"}], "explanations": {"选手": "选手：被选出来参加比赛的人，符合“跑得很快”的语境。", "汽车": "量词：“位”只用于人，不能说“这位汽车”。", "小狗": "量词：“位”只用于人，小狗应该说“这只小狗”。", "婴儿": "常识：婴儿还不会跑，与“跑得很快”矛盾。"}, "sentence_index": 0, "correct_answer": "选手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有一条选手参加了比赛。", "explanation": "这里应该用〈位〉。量词“条”用于细长的东西，不能用来数人，选手应该用“名”或“位”。"}, {"text": "那台选手跑得很快。", "explanation": "这里应该用〈位〉。量词“台”用于机器等物品，不能用来数人。"}, {"text": "这块选手非常有名。", "explanation": "这里应该用〈位〉。量词“块”用于片状的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选手", "is_correct": true, "explanation": "选手：参加比赛的人，观众给他们送花，符合语境。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：观众不会给小偷送花，这样说与语境矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：观众不会给敌人送花，与句意不符。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子不是人，观众不会给它送花，与句意矛盾。"}], "explanations": {"选手": "选手：参加比赛的人，观众给他们送花，符合语境。", "小偷": "语义：观众不会给小偷送花，这样说与语境矛盾。", "敌人": "语义：观众不会给敌人送花，与句意不符。", "蚊子": "语义：蚊子不是人，观众不会给它送花，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "选手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "选手们坐在评审席上，给每个节目打了分。", "explanation": "这里应该用〈评委〉。选手是参加比赛的人，坐在评审席上给节目打分的应说评委。"}, {"text": "选手们在大会上宣读了选举结果，统计了所有选票。", "explanation": "这里应该用〈计票员〉。选手是参加比赛的人，统计选票的应说计票员。"}, {"text": "选手们在场边拿着话筒，采访了每一位教练。", "explanation": "这里应该用〈记者〉。选手是参加比赛的人，场边拿话筒采访教练的应说记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只年轻的选手赢得了冠军。", "corrected_sentence": "那位年轻的选手赢得了冠军。", "error_description": "量词错误：“选手”指人，应用“位”或“名”，不能用“只”。应为“那位年轻的选手赢得了冠军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位选手们都很紧张。", "corrected_sentence": "三位选手都很紧张。", "error_description": "数量词错误：已有“三位”表示数量，“选手”后不能再加“们”。应为“三位选手都很紧张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
