INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南是一个方向。太阳中午时在这个方向。", "primary_collocate": null, "pronunciation": "nán", "ipa": "nan˧˥", "syllable_count": 1, "sentences": [{"text": "中午，我面朝南站着，影子落在北边。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车往南开了一公里。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向南看，你就能看见那座山。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路往南通向海边。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子秋天往南飞，春天又往北飞回来。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子朝南放好。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的院门朝南开。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了车，他往南走，我往北走。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面朝南，左边是东，右边是西。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你往南再走一百米就到了。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南边", "label": "复合"}, {"form": "南方", "label": "复合"}], "register": "中性", "sense_fingerprint": "中午太阳所在的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "南", "is_correct": true, "explanation": "正确答案。nán（第二声）表示太阳中午所在的方向。"}, {"text": "蓝", "is_correct": false, "explanation": "lán 与 nán 声母不同（l／n），蓝的意思是蓝色。"}, {"text": "年", "is_correct": false, "explanation": "nián 与 nán 韵母不同（-ian／-an），年的意思是年份。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}], "explanations": {"南": "正确答案。nán（第二声）表示太阳中午所在的方向。", "蓝": "lán 与 nán 声母不同（l／n），蓝的意思是蓝色。", "年": "nián 与 nán 韵母不同（-ian／-an），年的意思是年份。", "谈": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}, "sentence_index": null, "correct_answer": "南"}, "level_3": {"options": [{"text": "南", "is_correct": true, "explanation": "中午太阳在南方，人面朝南站着，影子落在北边，符合句意。"}, {"text": "上", "is_correct": false, "explanation": "搭配：“朝上”多指躺着时面向上，不用于描述站着的人。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“朝下”多指趴着，不用于描述站着的人。"}, {"text": "地", "is_correct": false, "explanation": "语义：站着的人不会面朝地面，“面朝地站着”与句子的站立姿势矛盾。"}], "explanations": {"南": "中午太阳在南方，人面朝南站着，影子落在北边，符合句意。", "上": "搭配：“朝上”多指躺着时面向上，不用于描述站着的人。", "下": "搭配：“朝下”多指趴着，不用于描述站着的人。", "地": "语义：站着的人不会面朝地面，“面朝地站着”与句子的站立姿势矛盾。"}, "sentence_index": 0, "correct_answer": "南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校在我家的南，走路只要十分钟。", "explanation": "这里应该用〈南边〉。表示位置要说“南边”，“我家的南”不这么说。"}, {"text": "早上，太阳从南边升起，我们向它走去。", "explanation": "这里应该用〈东〉。太阳早上升起的方向是东，“南”不表示太阳升起的方向。"}, {"text": "他的老家在中国南，那里冬天不冷。", "explanation": "这里应该用〈南方〉。表示地区要说“中国南方”，“中国南”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88363, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "南", "is_correct": true, "explanation": "正确答案。nán（第二声）表示太阳中午所在的方向。"}, {"text": "兰", "is_correct": false, "explanation": "lán 与 nán 声母不同（l／n），兰的意思是兰花。"}, {"text": "瞒", "is_correct": false, "explanation": "mán 与 nán 声母不同（m／n），瞒的意思是隐瞒。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}], "explanations": {"南": "正确答案。nán（第二声）表示太阳中午所在的方向。", "兰": "lán 与 nán 声母不同（l／n），兰的意思是兰花。", "瞒": "mán 与 nán 声母不同（m／n），瞒的意思是隐瞒。", "谈": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}, "sentence_index": null, "correct_answer": "南"}, "level_3": {"options": [{"text": "南", "is_correct": true, "explanation": "“朝南”指院门面向南方，符合句意。"}, {"text": "天", "is_correct": false, "explanation": "语义：院门不会朝天开，与“院门开”的方向矛盾。"}, {"text": "地面", "is_correct": false, "explanation": "搭配：门一般不说“朝地面开”，这个搭配不自然。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶不是门的朝向，“院门朝屋顶开”与句意矛盾。"}], "explanations": {"南": "“朝南”指院门面向南方，符合句意。", "天": "语义：院门不会朝天开，与“院门开”的方向矛盾。", "地面": "搭配：门一般不说“朝地面开”，这个搭配不自然。", "屋顶": "语义：屋顶不是门的朝向，“院门朝屋顶开”与句意矛盾。"}, "sentence_index": 6, "correct_answer": "南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的南有一条河，夏天可以游泳。", "explanation": "这里应该用〈南面〉。表示家的一侧要说“南面”，“我家的南”不这么说。"}, {"text": "我的老家在广东的南，那里一年都很热。", "explanation": "这里应该用〈南部〉。说某个省份的一部分要用“南部”，“广东的南”不这么说。"}, {"text": "我的书放在桌子的南，快拿过来吧。", "explanation": "这里应该用〈南侧〉。表示物体的某一侧要说“南侧”，“桌子的南”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚才南跑了一会儿。", "corrected_sentence": "他刚才往南跑了一会儿。", "error_description": "错误：“南跑”，缺少“往”。正确：“往南跑”。表示朝某个方向行进时，方向词前要加“往”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在南开了一公里。", "corrected_sentence": "我们往南开了一公里。", "error_description": "错误：“在南开”，应为“往南开”。表示行进的方向要用“往”，“在”表示所在的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
