INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "四个基本方位之一,与北相对,面对太阳升起的方向时,在右手一侧。", "primary_collocate": null, "pronunciation": "nán", "ipa": "nan˧˥", "syllable_count": 1, "sentences": [{"text": "窗户朝南，冬天很暖和。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直往南走，就能看到海。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁秋天向南飞。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图的下面是南，上面是北。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南和北正好相反。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的房子门朝南。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从北到南，坐火车要两天。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看太阳，往南走去。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往北去，我往南去。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请面向南站好。", "target_word": "南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南边", "label": "复合"}, {"form": "南方", "label": "复合"}], "register": "中性", "sense_fingerprint": "与北相对的基本方位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "南", "is_correct": true, "explanation": "正确答案。nán（第二声）表示四个基本方位之一，与北相对。"}, {"text": "蓝", "is_correct": false, "explanation": "lán 与 nán 声母不同（l／n），蓝的意思是蓝色。"}, {"text": "年", "is_correct": false, "explanation": "nián 与 nán 韵母不同（-ian／-an），年的意思是年份。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}], "explanations": {"南": "正确答案。nán（第二声）表示四个基本方位之一，与北相对。", "蓝": "lán 与 nán 声母不同（l／n），蓝的意思是蓝色。", "年": "nián 与 nán 韵母不同（-ian／-an），年的意思是年份。", "谈": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}, "sentence_index": null, "correct_answer": "南"}, "level_3": {"options": [{"text": "南", "is_correct": true, "explanation": "“朝南”指窗户面向南方，南面日照充足，冬天暖和，符合句意。"}, {"text": "北", "is_correct": false, "explanation": "语义：窗户朝北日照少，与“冬天很暖和”矛盾。"}, {"text": "上", "is_correct": false, "explanation": "搭配：“朝上”多指躺着时面向上，不用来描述窗户的朝向。"}, {"text": "下", "is_correct": false, "explanation": "搭配：窗户不说“朝下”，“朝下”不能描述窗户的朝向。"}], "explanations": {"南": "“朝南”指窗户面向南方，南面日照充足，冬天暖和，符合句意。", "北": "语义：窗户朝北日照少，与“冬天很暖和”矛盾。", "上": "搭配：“朝上”多指躺着时面向上，不用来描述窗户的朝向。", "下": "搭配：窗户不说“朝下”，“朝下”不能描述窗户的朝向。"}, "sentence_index": 0, "correct_answer": "南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在南，离学校很近。", "explanation": "这里应该用〈南边〉。表示位置要说“住在南边”，单独的“南”不用于“住在”后。"}, {"text": "太阳每天从南边升起，从西边落下。", "explanation": "这里应该用〈东〉。太阳升起的方向是东，“南”指与北相对的方向，不能说“从南边升起”。"}, {"text": "我的老家在中国南，那里夏天很热。", "explanation": "这里应该用〈南方〉。表示地区要说“中国南方”，“中国南”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88364, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "南", "is_correct": true, "explanation": "正确答案。nán（第二声）表示四个基本方位之一，与北相对。"}, {"text": "兰", "is_correct": false, "explanation": "lán 与 nán 声母不同（l／n），兰的意思是兰花。"}, {"text": "瞒", "is_correct": false, "explanation": "mán 与 nán 声母不同（m／n），瞒的意思是隐瞒。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}], "explanations": {"南": "正确答案。nán（第二声）表示四个基本方位之一，与北相对。", "兰": "lán 与 nán 声母不同（l／n），兰的意思是兰花。", "瞒": "mán 与 nán 声母不同（m／n），瞒的意思是隐瞒。", "谈": "tán 与 nán 声母不同（t／n），谈的意思是谈话。"}, "sentence_index": null, "correct_answer": "南"}, "level_3": {"options": [{"text": "南", "is_correct": true, "explanation": "“从北到南”指南北两端的距离，远距离路程，符合“坐火车要两天”。"}, {"text": "门", "is_correct": false, "explanation": "语义：从北到门口的距离不需要坐火车两天，与句意矛盾。"}, {"text": "屋", "is_correct": false, "explanation": "搭配：“从……到……”后接的是地点或方位，一般不说“从北到屋”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙离得很近，坐火车两天的路程与墙的位置矛盾。"}], "explanations": {"南": "“从北到南”指南北两端的距离，远距离路程，符合“坐火车要两天”。", "门": "语义：从北到门口的距离不需要坐火车两天，与句意矛盾。", "屋": "搭配：“从……到……”后接的是地点或方位，一般不说“从北到屋”。", "墙": "语义：墙离得很近，坐火车两天的路程与墙的位置矛盾。"}, "sentence_index": 6, "correct_answer": "南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的南有一个大超市，买东西很方便。", "explanation": "这里应该用〈南面〉。表示物体的一侧要说“南面”，“学校的南”不这么说。"}, {"text": "我的老家在四川的南，那里夏天很热。", "explanation": "这里应该用〈南部〉。说某个省份的一部分要用“南部”，“四川的南”不这么说。"}, {"text": "我的椅子在桌子的南，离门很近。", "explanation": "这里应该用〈南侧〉。表示物体的某一侧要说“南侧”，“桌子的南”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们南骑，很快就能到海边。", "corrected_sentence": "我们往南骑，很快就能到海边。", "error_description": "错误：“南骑”，缺少“往”。正确：“往南骑”。表示朝某个方向行进时，方向词前要加“往”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他沿着海边南往骑，骑了很久。", "corrected_sentence": "他沿着海边往南骑，骑了很久。", "error_description": "错误：“南往”，应为“往南”。方向词要放在“往”后面，不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
