INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生孩子是妈妈把肚子里的宝宝生出来。", "primary_collocate": null, "pronunciation": "shēng hái zi", "ipa": "ʂɤŋ˥ xaɪ˧˥ tsɿ", "syllable_count": 3, "sentences": [{"text": "她明年想生孩子。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在医院生孩子。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐今天要去医院生孩子。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生孩子的时候，妈妈很辛苦。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算结婚以后生孩子。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生孩子以前，她买了很多小衣服。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶在家里生孩子，那时候没有医院。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想太早生孩子。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生孩子很不容易，要小心身体。", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你太太快要生孩子了，真高兴！", "target_word": "生孩子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生了孩子", "label": "体标"}, {"form": "生过孩子", "label": "体标"}, {"form": "生个孩子", "label": "离合"}], "register": "口语", "sense_fingerprint": "妈妈把肚子里的宝宝生出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生孩子", "is_correct": true, "explanation": "正确：“想”后接的是人能主动去做的事，“想生孩子”符合句意。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“想”后接自主动作，“失眠”是身不由己的状态，不能说“想失眠”。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：人不会结冰，“想结冰”不成立。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：下雨由天气决定，不能由人“想”去做。"}], "explanations": {"生孩子": "正确：“想”后接的是人能主动去做的事，“想生孩子”符合句意。", "失眠": "搭配：“想”后接自主动作，“失眠”是身不由己的状态，不能说“想失眠”。", "结冰": "语义：人不会结冰，“想结冰”不成立。", "下雨": "搭配：下雨由天气决定，不能由人“想”去做。"}, "sentence_index": 0, "correct_answer": "生孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天生孩子了，今天好多了。", "explanation": "这里应该用〈生病〉。生孩子只指女性分娩，不能用来说男性身体不舒服。"}, {"text": "这家工厂每天都在生孩子。", "explanation": "这里应该用〈生产〉。生孩子指人分娩，工厂制造东西要用生产。"}, {"text": "这片果园今年生孩子很多。", "explanation": "这里应该用〈结果〉。生孩子指人分娩，果树开花结果要说结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生孩子", "is_correct": true, "explanation": "正确：过去女性常在家里分娩，与“那时候没有医院”前后呼应。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“在家里”与“出差”（需要离开居住地）矛盾。"}, {"text": "登山", "is_correct": false, "explanation": "语义：登山需要到山上去，与“在家里”矛盾。"}, {"text": "环游", "is_correct": false, "explanation": "语义：环游需要长途出行，不能在家里进行。"}], "explanations": {"生孩子": "正确：过去女性常在家里分娩，与“那时候没有医院”前后呼应。", "出差": "搭配：“在家里”与“出差”（需要离开居住地）矛盾。", "登山": "语义：登山需要到山上去，与“在家里”矛盾。", "环游": "语义：环游需要长途出行，不能在家里进行。"}, "sentence_index": 6, "correct_answer": "生孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为这件事生孩子了，整天不说话。", "explanation": "这里应该用〈生气〉。生孩子指分娩，因为事情不高兴要说生气。"}, {"text": "这棵树生孩子得很快，一年就长高了一米。", "explanation": "这里应该用〈生长〉。生孩子指分娩，植物长大要说生长。"}, {"text": "医生负责生孩子。", "explanation": "这里应该用〈接生〉。生孩子是产妇自己分娩，医生帮助分娩要说接生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年生孩子过了。", "corrected_sentence": "她去年生孩子了。", "error_description": "错误：“过”不能放在宾语“孩子”之后。此句说的是去年已经发生的事，只用“了”：她去年生孩子了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她那年生孩子过，很高兴。", "corrected_sentence": "她那年生孩子了，很高兴。", "error_description": "错误：“生孩子过”；正确：“生孩子了”。“过”表示经历，要放在动词“生”后面（生过孩子）；此处说的是已经发生的事，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "与“全同”相对，指每一点都不一样。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与全同没有反义关系，清楚的反义词是“模糊”。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮与全同没有反义关系，明亮的反义词是“昏暗”。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂与全同没有反义关系，复杂的反义词是“简单”。"}], "correct_answer": "不同", "explanations": {"不同": "与“全同”相对，指每一点都不一样。", "清楚": "清楚与全同没有反义关系，清楚的反义词是“模糊”。", "明亮": "明亮与全同没有反义关系，明亮的反义词是“昏暗”。", "复杂": "复杂与全同没有反义关系，复杂的反义词是“简单”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "与“全同”相对，指每一点都不一样。"}, {"text": "陌生", "is_correct": false, "explanation": "陌生与全同没有反义关系，陌生的反义词是“熟悉”。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹与全同没有反义关系，热闹的反义词是“冷清”。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬与全同没有反义关系，坚硬的反义词是“柔软”。"}], "correct_answer": "不同", "explanations": {"不同": "与“全同”相对，指每一点都不一样。", "陌生": "陌生与全同没有反义关系，陌生的反义词是“熟悉”。", "热闹": "热闹与全同没有反义关系，热闹的反义词是“冷清”。", "坚硬": "坚硬与全同没有反义关系，坚硬的反义词是“柔软”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全同是每一点都一样，没有不同。", "primary_collocate": null, "pronunciation": "quán tóng", "ipa": "tɕʰɥɛn˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这两个三角形的大小和形状全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张图片看起来全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两本书的内容全同，只是封面不一样。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这两道题的答案全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子的颜色和样子全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两份报告的数字全同，大家都觉得奇怪。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的想法并不全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字的写法全同吗？", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找出两个全同的图形。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两件衣服的样式全同，连扣子的位置也一样。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全同三角形", "label": "复合"}], "register": "书面", "sense_fingerprint": "全同：每一点都一样，没有不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全同", "is_correct": true, "explanation": "与听到的读音完全一致，意思是每一点都一样，没有不同。"}, {"text": "全通", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是完全贯通。"}, {"text": "全图", "is_correct": false, "explanation": "tú（第二声）与 tóng 声母、声调相同，韵母不同（u 与 ong），意思是完整的图。"}, {"text": "全停", "is_correct": false, "explanation": "tíng（第二声）与 tóng 韵母不同（ing 与 ong），意思是完全停止。"}], "explanations": {"全同": "与听到的读音完全一致，意思是每一点都一样，没有不同。", "全通": "tōng（第一声）与 tóng（第二声）声调不同，意思是完全贯通。", "全图": "tú（第二声）与 tóng 声母、声调相同，韵母不同（u 与 ong），意思是完整的图。", "全停": "tíng（第二声）与 tóng 韵母不同（ing 与 ong），意思是完全停止。"}, "sentence_index": null, "correct_answer": "全同"}, "level_3": {"options": [{"text": "全同", "is_correct": true, "explanation": "全同：指两个图形每一点都一样，符合句意。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”说分量或心情，不能用来形容大小和形状。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人的情绪或态度，与几何图形的大小和形状无关。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情或动作，不能说形状温柔。"}], "explanations": {"全同": "全同：指两个图形每一点都一样，符合句意。", "沉重": "搭配：“沉重”说分量或心情，不能用来形容大小和形状。", "冷静": "语义：“冷静”形容人的情绪或态度，与几何图形的大小和形状无关。", "温柔": "语义：“温柔”形容人的性情或动作，不能说形状温柔。"}, "sentence_index": 0, "correct_answer": "全同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两张照片很全同。", "explanation": "这里应该用〈相似〉。全同表示每一点都一样，没有程度之分，不能用“很”修饰。"}, {"text": "这两个苹果全同，但是一个大，一个小。", "explanation": "这里应该用〈相似〉。全同表示每一点都一样，不能与“一个大，一个小”同时出现；说有差别时要用“相似”。"}, {"text": "这两个孩子长得有点全同。", "explanation": "这里应该用〈像〉。全同表示完全一样，不能用“有点”修饰；只说有几分相似时要用“像”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全同", "is_correct": true, "explanation": "全同：指想法每一点都一样，与“并不”搭配，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来形容想法。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”多形容颜色，不能与“想法”搭配。"}, {"text": "蓬松", "is_correct": false, "explanation": "体貌：“蓬松”形容物体松散而鼓起的样子，不适用于想法。"}], "explanations": {"全同": "全同：指想法每一点都一样，与“并不”搭配，符合句意。", "清脆": "语义：“清脆”形容声音，不能用来形容想法。", "鲜艳": "搭配：“鲜艳”多形容颜色，不能与“想法”搭配。", "蓬松": "体貌：“蓬松”形容物体松散而鼓起的样子，不适用于想法。"}, "sentence_index": 6, "correct_answer": "全同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个朋友年纪大约全同。", "explanation": "这里应该用〈相仿〉。全同表示完全相同，不能与“大约”搭配；说年纪接近时要用“相仿”。"}, {"text": "他们俩的脾气比别人全同。", "explanation": "这里应该用〈相似〉。全同没有比较的余地，不能用在“比”字句里；说程度相近时要用“相似”。"}, {"text": "他们全同地笑了。", "explanation": "这里应该用〈一起〉。全同是描述事物每一点都一样的形容词，不表示动作的方式；说大家同时笑要用“一起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器复印全同。", "corrected_sentence": "这台机器复印得全同。", "error_description": "错误形式是“复印全同”，正确形式是“复印得全同”。动词后面带形容词作补语时要用“得”连接，漏掉“得”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两张照片修改以后就变得全同过。", "corrected_sentence": "这两张照片修改以后就变得全同了。", "error_description": "错误形式是“全同过”，正确形式是“全同了”。“过”表示经历过的动作，这里说的是变化的结果，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
