INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88368, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "完全相同。", "primary_collocate": null, "pronunciation": "quán tóng", "ipa": "tɕʰɥɛn˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这两个房间的布置全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个盒子的大小全同，我分不出来。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了两个全同的三角形。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两封信的内容全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个苹果的样子全同，但是味道不同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张表格上的名字全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的意见并不全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条路的长度全同。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两个全同的杯子。", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个句子的意思全同吗？", "target_word": "全同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全同三角形", "label": "复合"}], "register": "书面", "sense_fingerprint": "全同：完全相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全同", "is_correct": true, "explanation": "与听到的读音完全一致，意思是完全相同。"}, {"text": "全通", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是完全贯通。"}, {"text": "全图", "is_correct": false, "explanation": "tú（第二声）与 tóng 声母、声调相同，韵母不同（u 与 ong），意思是完整的图。"}, {"text": "全停", "is_correct": false, "explanation": "tíng（第二声）与 tóng 韵母不同（ing 与 ong），意思是完全停止。"}], "explanations": {"全同": "与听到的读音完全一致，意思是完全相同。", "全通": "tōng（第一声）与 tóng（第二声）声调不同，意思是完全贯通。", "全图": "tú（第二声）与 tóng 声母、声调相同，韵母不同（u 与 ong），意思是完整的图。", "全停": "tíng（第二声）与 tóng 韵母不同（ing 与 ong），意思是完全停止。"}, "sentence_index": null, "correct_answer": "全同"}, "level_3": {"options": [{"text": "全同", "is_correct": true, "explanation": "全同：指布置完全相同，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来形容房间的布置。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人的情绪或态度，不能用来形容布置。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”多形容气候、土地或皮肤，不能用来形容房间的布置。"}], "explanations": {"全同": "全同：指布置完全相同，符合句意。", "清脆": "语义：“清脆”形容声音，不能用来形容房间的布置。", "冷静": "语义：“冷静”形容人的情绪或态度，不能用来形容布置。", "湿润": "搭配：“湿润”多形容气候、土地或皮肤，不能用来形容房间的布置。"}, "sentence_index": 0, "correct_answer": "全同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个孩子长得很全同。", "explanation": "这里应该用〈像〉。全同表示完全相同，没有程度之分，不能用“很”修饰。"}, {"text": "两个朋友年纪大约全同。", "explanation": "这里应该用〈相仿〉。全同表示完全相同，不能与“大约”搭配；说年纪接近时要用“相仿”。"}, {"text": "他们全同地回答了问题。", "explanation": "这里应该用〈一起〉。全同描述事物每一点都一样，不表示动作的方式；说大家同时回答要用“一起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全同", "is_correct": true, "explanation": "全同：指意见每一点都一样，与“并不”搭配，符合句意。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”多形容气候、土地或皮肤，不能用来形容意见。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”多形容颜色，不能用来形容意见。"}, {"text": "松软", "is_correct": false, "explanation": "体貌：“松软”形容质地柔软、蓬松的物体，不适用于意见。"}], "explanations": {"全同": "全同：指意见每一点都一样，与“并不”搭配，符合句意。", "湿润": "搭配：“湿润”多形容气候、土地或皮肤，不能用来形容意见。", "鲜艳": "搭配：“鲜艳”多形容颜色，不能用来形容意见。", "松软": "体貌：“松软”形容质地柔软、蓬松的物体，不适用于意见。"}, "sentence_index": 6, "correct_answer": "全同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个句子的意思很全同。", "explanation": "这里应该用〈相近〉。全同表示完全相同，没有程度之分，不能用“很”修饰。"}, {"text": "两人全同地点了头。", "explanation": "这里应该用〈一起〉。全同描述事物每一点都一样，不表示动作的方式；两人同时点头要用“一起”。"}, {"text": "这两个句子的意思有点全同。", "explanation": "这里应该用〈相似〉。全同表示完全相同，不能用“有点”修饰；只表示有几分相似时才用“相似”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个盒子的大小不并全同。", "corrected_sentence": "这两个盒子的大小并不全同。", "error_description": "错误形式是“不并全同”，正确形式是“并不全同”。“并”是副词，要放在否定词“不”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两张表的字迹写全同。", "corrected_sentence": "这两张表的字迹写得全同。", "error_description": "错误形式是“写全同”，正确形式是“写得全同”。动词后面带形容词作补语，要用“得”连接，漏掉“得”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
