INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "各个国家。", "primary_collocate": null, "pronunciation": "gè guó", "ipa": "kɤ˥˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "各国的天气都不一样。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的老师来这里开会。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国都有自己的节日。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界杯让各国的人看同一场比赛。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的钱不一样。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国都想让孩子上好学校。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了各国的故事。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的运动员都到了。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一张画着各国的地图。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的飞机都在这个机场停。", "target_word": "各国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "各个国家的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "正确。“各国”指各个国家，修饰“天气”，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以“不一样”的天气，“声音的天气”说不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”与“天气”无关，句子说不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不说“天气”，不能说“作业的天气”。"}], "explanations": {"各国": "正确。“各国”指各个国家，修饰“天气”，符合句意。", "声音": "语义：“声音”不是可以“不一样”的天气，“声音的天气”说不通。", "学费": "语义：“学费”与“天气”无关，句子说不通。", "作业": "搭配：“作业”不说“天气”，不能说“作业的天气”。"}, "sentence_index": 0, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都喝各国。", "explanation": "这里应该用〈牛奶〉。“各国”是泛指所有国家的词，不是饮料，不能用“喝”来搭配。"}, {"text": "我叫各国。", "explanation": "这里应该用〈小明〉这样的人名。“各国”是泛指所有国家的词，不能当作人的名字。"}, {"text": "那里来了一位各国的朋友。", "explanation": "这里应该用〈外国〉。“各国”指所有国家，不能和“一位”连用来指某一个国家来的朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "正确。“各国”指各个国家，修饰“故事”，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”与“故事”无关，“写了体重的故事”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的数值，不能用来修饰“故事”。"}, {"text": "数量", "is_correct": false, "explanation": "语义：“数量”是抽象的数目，不能作“写了……的故事”的对象。"}], "explanations": {"各国": "正确。“各国”指各个国家，修饰“故事”，符合句意。", "体重": "语义：“体重”与“故事”无关，“写了体重的故事”说不通。", "体温": "语义：“体温”是身体的数值，不能用来修饰“故事”。", "数量": "语义：“数量”是抽象的数目，不能作“写了……的故事”的对象。"}, "sentence_index": 6, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她嫁给了各国。", "explanation": "这里应该用〈外国人〉。“各国”是国家的总称，不是人，不能作结婚的对象。"}, {"text": "我的电脑里有各国。", "explanation": "这里应该用〈文件〉。“各国”是泛指所有国家的词，不能像文件那样存放在电脑里。"}, {"text": "这所学校的各国很大。", "explanation": "这里应该用〈操场〉。“各国”是泛指所有国家的词，不是学校的一部分，不能说“学校的各国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国们的饮食习惯都不一样。", "corrected_sentence": "各国的饮食习惯都不一样。", "error_description": "“各国”已经表示多个国家，后面不能再加“们”。应说“各国的饮食习惯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来自各国地运动员都到了。", "corrected_sentence": "来自各国的运动员都到了。", "error_description": "“的”和“地”用错了。“来自各国”修饰名词“运动员”，中间应用“的”，不能用“地”（“地”用于修饰动词或形容词）。应说“来自各国的运动员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
