INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用来（做某事）。", "primary_collocate": null, "pronunciation": "yòng yǐ", "ipa": "jʊŋ⁵¹ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "厨房里放着一个小秤，用以称量面粉。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带了一本笔记，用以记录每天的变化。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打了一口井，用以解决村里的用水问题。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一个网站，用以通知家长。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把长尺用以测量桌子的大小。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封信，用以感谢帮助过她的人。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里种了很多树，用以挡住大风。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间用以存放旧书。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人养了几只鸡，用以补贴家用。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府拿出一笔钱，用以修路。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "用来做某事（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：小秤被扔掉就不能再用来称量面粉，与“放着一个小秤”的语境矛盾。"}, {"text": "用以", "is_correct": true, "explanation": "正确：“用以”表示用来做某事，后接动词“称量”。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”后接的是器物，不能接“称量面粉”这样的动作。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”说的是修好东西，不能表示用秤来称量。"}], "explanations": {"扔掉": "语义：小秤被扔掉就不能再用来称量面粉，与“放着一个小秤”的语境矛盾。", "用以": "正确：“用以”表示用来做某事，后接动词“称量”。", "打碎": "搭配：“打碎”后接的是器物，不能接“称量面粉”这样的动作。", "修理": "语义：“修理”说的是修好东西，不能表示用秤来称量。"}, "sentence_index": 0, "correct_answer": "用以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走路时很小心，用以摔倒。", "explanation": "这里应该用〈以免〉。“用以”表示有意达到的目的，“以免”表示为了避免某种不好的结果；“用以摔倒”把摔倒说成了目的，不合常理。"}, {"text": "天气变热，用以冰箱里的东西坏了。", "explanation": "“用以”表示人有意达到的目的，不能用来说明天气造成的结果。"}, {"text": "他没来上课，用以生病了。", "explanation": "这里应该用〈因为〉。“用以”表示目的，不能表示原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砍掉", "is_correct": false, "explanation": "语义：树被砍掉就挡不住风了，与“种了很多树”的目的矛盾。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能接“挡住大风”。"}, {"text": "拔掉", "is_correct": false, "explanation": "语义：树被拔掉就不能挡住大风，句子前后矛盾。"}, {"text": "用以", "is_correct": true, "explanation": "正确：“用以”表示目的，后接动词“挡住”。"}], "explanations": {"砍掉": "语义：树被砍掉就挡不住风了，与“种了很多树”的目的矛盾。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能接“挡住大风”。", "拔掉": "语义：树被拔掉就不能挡住大风，句子前后矛盾。", "用以": "正确：“用以”表示目的，后接动词“挡住”。"}, "sentence_index": 6, "correct_answer": "用以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用以担心考试，晚上睡不着。", "explanation": "“用以”表示有意达到的目的，“担心”是心理状态，不能作为有意达到的目的，这里应直接说“她担心考试”。"}, {"text": "妈妈用以生气，没有说话。", "explanation": "“用以”表示有意达到的目的，“生气”是情绪反应，不能作为有意的目的，这里应直接说“妈妈生气了”。"}, {"text": "我用以知道答案，所以没问老师。", "explanation": "“用以”表示有意达到的目的，“知道”是认知状态，不能作为目的，这里应去掉“用以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书桌上放着一把尺子，用以着量纸的长度。", "corrected_sentence": "书桌上放着一把尺子，用以量纸的长度。", "error_description": "错误：“用以”后面加了“着”。“用以”后接动词时不带“着”，应去掉“着”，改为“用以量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校修了一道围墙，用以了挡住外面的噪音。", "corrected_sentence": "学校修了一道围墙，用以挡住外面的噪音。", "error_description": "错误：“用以”后面加了“了”。“用以”后接动词时不带“了”，应去掉“了”，改为“用以挡住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平安", "is_correct": true, "explanation": "与“出事”相反，指没有发生意外。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容人多声响大，与“出事”的意思无关。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，与“出事”的意思无关。"}, {"text": "大方", "is_correct": false, "explanation": "大方形容不拘小节，与“出事”的意思无关。"}], "correct_answer": "平安", "explanations": {"平安": "与“出事”相反，指没有发生意外。", "热闹": "热闹形容人多声响大，与“出事”的意思无关。", "整齐": "整齐形容排列有序，与“出事”的意思无关。", "大方": "大方形容不拘小节，与“出事”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平安", "is_correct": true, "explanation": "与“出事”相反，指平平安安，没有意外。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容不紧张、不费力，与“出事”的意思无关。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃形容态度认真庄重，与“出事”的意思无关。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨形容大方给予，与“出事”的意思无关。"}], "correct_answer": "平安", "explanations": {"平安": "与“出事”相反，指平平安安，没有意外。", "轻松": "轻松形容不紧张、不费力，与“出事”的意思无关。", "严肃": "严肃形容态度认真庄重，与“出事”的意思无关。", "慷慨": "慷慨形容大方给予，与“出事”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出事是发生了不好的事情。", "primary_collocate": null, "pronunciation": "chū shì", "ipa": "tʂʰu˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司出事了，老板很着急。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你脸色不好，家里出事了吗？", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家出事后，朋友都来帮忙。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直不接电话，我担心她出事。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出事那天，我正好不在家。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里出事了，老师叫我们回去。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近总是不说话，是不是出事了？", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别告诉妈妈，免得她以为我出事了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里出事的时候，大家都去帮忙。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚出事以后，他一夜没睡。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了事", "label": "体标（了）"}, {"form": "出过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "发生了不好的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出事", "is_correct": true, "explanation": "出事：发生了不好的事情，是正确答案。"}, {"text": "初识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是初次认识。"}, {"text": "厨师", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）、shī（第一声）与 shì（第四声）声调不同，意思是做饭的人。"}, {"text": "诸事", "is_correct": false, "explanation": "zhū（第一声）与 chū 声母不同（zh 与 ch），意思是各种事情。"}], "explanations": {"出事": "出事：发生了不好的事情，是正确答案。", "初识": "shí（第二声）与 shì（第四声）声调不同，意思是初次认识。", "厨师": "chú（第二声）与 chū（第一声）、shī（第一声）与 shì（第四声）声调不同，意思是做饭的人。", "诸事": "zhū（第一声）与 chū 声母不同（zh 与 ch），意思是各种事情。"}, "sentence_index": null, "correct_answer": "出事"}, "level_3": {"options": [{"text": "出事", "is_correct": true, "explanation": "句子说公司发生了不好的事，老板才着急，只有出事符合语境。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：开学用于学校，公司不能开学。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：结婚的主语要是人，公司不能结婚。"}, {"text": "退休", "is_correct": false, "explanation": "配价：退休的主语要是人，公司不能退休。"}], "explanations": {"出事": "句子说公司发生了不好的事，老板才着急，只有出事符合语境。", "开学": "搭配：开学用于学校，公司不能开学。", "结婚": "配价：结婚的主语要是人，公司不能结婚。", "退休": "配价：退休的主语要是人，公司不能退休。"}, "sentence_index": 0, "correct_answer": "出事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说去年出事了，现在很多书店都有卖。", "explanation": "这里应该用〈出版〉。出事表示发生不好的事，书的出版要说出版。"}, {"text": "他的新歌出事了，现在每个人都在唱。", "explanation": "这里应该用〈走红〉。出事表示发生不好的事，歌曲受欢迎应说走红。"}, {"text": "她明天要出事旅游。", "explanation": "这里应该用〈出国〉。出事指发生意外或事故，出境旅游要说出国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出事", "is_correct": true, "explanation": "出事：发生了不好的事情，是正确答案。"}, {"text": "处事", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处理事务。"}, {"text": "初始", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是最开始的。"}, {"text": "出使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是出国担任使节。"}], "explanations": {"出事": "出事：发生了不好的事情，是正确答案。", "处事": "chǔ（第三声）与 chū（第一声）声调不同，意思是处理事务。", "初始": "shǐ（第三声）与 shì（第四声）声调不同，意思是最开始的。", "出使": "shǐ（第三声）与 shì（第四声）声调不同，意思是出国担任使节。"}, "sentence_index": null, "correct_answer": "出事"}, "level_3": {"options": [{"text": "出事", "is_correct": true, "explanation": "句子问他是不是遇到了不好的事，只有出事符合语境。"}, {"text": "出版", "is_correct": false, "explanation": "配价：出版需要带宾语，“他出版”不成立。"}, {"text": "闭幕", "is_correct": false, "explanation": "配价：闭幕的主语是会议、展览等活动，不能用于人。"}, {"text": "通车", "is_correct": false, "explanation": "配价：通车的主语是道路、线路，不能用于人。"}], "explanations": {"出事": "句子问他是不是遇到了不好的事，只有出事符合语境。", "出版": "配价：出版需要带宾语，“他出版”不成立。", "闭幕": "配价：闭幕的主语是会议、展览等活动，不能用于人。", "通车": "配价：通车的主语是道路、线路，不能用于人。"}, "sentence_index": 6, "correct_answer": "出事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我明天要出事去广州。", "explanation": "这里应该用〈出差〉。出事表示发生意外，不能表示为公事动身去外地。"}, {"text": "这首歌去年出事了，现在很多人都在唱。", "explanation": "这里应该用〈流行〉。出事表示发生不好的事，歌曲受欢迎应说流行。"}, {"text": "他终于可以出事回家了。", "explanation": "这里应该用〈出院〉。出事指发生意外或事故，病人离开医院回家要说出院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里被出事了，老师很生气。", "corrected_sentence": "班里出事了，老师很生气。", "error_description": "“出事”是不及物动词，不能用“被”字句，应说“班里出事了”，不说“班里被出事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他三年前在山上出事过，现在很小心。", "corrected_sentence": "他三年前在山上出过事，现在很小心。", "error_description": "“出事”的体标“过”应放在“出”和“事”之间，说“出过事”，不说“出事过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
