INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发生意外或事故。", "primary_collocate": null, "pronunciation": "chū shì", "ipa": "tʂʰu˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "前面路口出事了，车都停着。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车太快，差点出事。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你家附近出事了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥昨天出事，路封了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地上出事，大家都很着急。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机睡着了，车就出事了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈听说我出事，马上赶来了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上下雪，爬山容易出事。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边游泳出事了。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车一定要小心，别出事。", "target_word": "出事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了事", "label": "体标（了）"}, {"form": "出过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "发生意外或事故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88376, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出事", "is_correct": true, "explanation": "出事：发生意外或事故，是正确答案。"}, {"text": "处事", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处理事务。"}, {"text": "初始", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是最开始的。"}, {"text": "厨师", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）、shī（第一声）与 shì（第四声）声调不同，意思是做饭的人。"}], "explanations": {"出事": "出事：发生意外或事故，是正确答案。", "处事": "chǔ（第三声）与 chū（第一声）声调不同，意思是处理事务。", "初始": "shǐ（第三声）与 shì（第四声）声调不同，意思是最开始的。", "厨师": "chú（第二声）与 chū（第一声）、shī（第一声）与 shì（第四声）声调不同，意思是做饭的人。"}, "sentence_index": null, "correct_answer": "出事"}, "level_3": {"options": [{"text": "出事", "is_correct": true, "explanation": "句子说路口发生了意外，所以车都停着，只有出事符合语境。"}, {"text": "闭幕", "is_correct": false, "explanation": "搭配：闭幕用于会议、展览等活动，不能用于路口。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：结婚的主语要是人，路口不能结婚。"}, {"text": "放假", "is_correct": false, "explanation": "搭配：放假用于学校、单位等，路口不能放假。"}], "explanations": {"出事": "句子说路口发生了意外，所以车都停着，只有出事符合语境。", "闭幕": "搭配：闭幕用于会议、展览等活动，不能用于路口。", "结婚": "配价：结婚的主语要是人，路口不能结婚。", "放假": "搭配：放假用于学校、单位等，路口不能放假。"}, "sentence_index": 0, "correct_answer": "出事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是1990年出事的，属马。", "explanation": "这里应该用〈出生〉。出事指发生意外或事故，不能用来说人的出生。"}, {"text": "他跑完步，全身出事。", "explanation": "这里应该用〈出汗〉。出事指发生意外或事故，身体出汗是生理现象，要说出汗。"}, {"text": "他下周要出事去上海开会。", "explanation": "这里应该用〈出差〉。出事表示发生意外，不能表示为公事动身去外地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88376, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出事", "is_correct": true, "explanation": "出事：发生意外或事故，是正确答案。"}, {"text": "诸事", "is_correct": false, "explanation": "zhū（第一声）与 chū 声母不同（zh 与 ch），意思是各种事情。"}, {"text": "初识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是初次认识。"}, {"text": "出使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是出国担任使节。"}], "explanations": {"出事": "出事：发生意外或事故，是正确答案。", "诸事": "zhū（第一声）与 chū 声母不同（zh 与 ch），意思是各种事情。", "初识": "shí（第二声）与 shì（第四声）声调不同，意思是初次认识。", "出使": "shǐ（第三声）与 shì（第四声）声调不同，意思是出国担任使节。"}, "sentence_index": null, "correct_answer": "出事"}, "level_3": {"options": [{"text": "出事", "is_correct": true, "explanation": "句子说我遇到了意外，妈妈才赶来，只有出事符合语境。"}, {"text": "出版", "is_correct": false, "explanation": "配价：出版需要带宾语，“我出版”不成立。"}, {"text": "闭幕", "is_correct": false, "explanation": "配价：闭幕的主语是会议、展览等活动，不能用于人。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：睡着与“马上赶来”的紧急情境不符。"}], "explanations": {"出事": "句子说我遇到了意外，妈妈才赶来，只有出事符合语境。", "出版": "配价：出版需要带宾语，“我出版”不成立。", "闭幕": "配价：闭幕的主语是会议、展览等活动，不能用于人。", "睡着": "语义：睡着与“马上赶来”的紧急情境不符。"}, "sentence_index": 6, "correct_answer": "出事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本词典去年出事，现在书店里到处都能买到。", "explanation": "这里应该用〈出版〉。出事指发生意外，书印出来发行要说出版。"}, {"text": "我们明天早上七点出事去爬山。", "explanation": "这里应该用〈出发〉。出事指发生意外或事故，动身去某地要说出发。"}, {"text": "他的小说去年出事了，现在很多人都在读。", "explanation": "这里应该用〈出名〉。出事表示发生不好的意外，小说受欢迎应说出名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面的桥被出事了，我们只好绕路。", "corrected_sentence": "前面的桥出事了，我们只好绕路。", "error_description": "“出事”是不及物动词，不能用“被”字句，应说“前面的桥出事了”，不说“前面的桥被出事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年在工地出事过，所以很小心。", "corrected_sentence": "他去年在工地出过事，所以很小心。", "error_description": "“出事”的体标“过”应放在“出”和“事”之间，说“出过事”，不说“出事过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
