INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "各地就是每一个地方。", "primary_collocate": null, "pronunciation": "gè dì", "ipa": "kɤ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "雨季到了，各地都开始下雨。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的学校都在放假。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影在各地都很受欢迎。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，各地的花都开了。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从各地来到北京开会。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的小吃都很有名。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天各地有大雨，请注意安全。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走遍各地，找到了那本旧书。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻让各地的人都知道了。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的商店晚上九点关门。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；每一个地方，强调各处无一例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "名词，指每一个地方，与“雨季到了，都开始下雨”的全称义相合。"}, {"text": "某地", "is_correct": false, "explanation": "语义：“某地”指不确定的一处，与“都开始下雨”表示每一处的全称义冲突。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不指地方，不能作“都开始下雨”的主语。"}, {"text": "某个", "is_correct": false, "explanation": "语法：“某个”须接名词作定语，单独作主语不成立，无法承接“都”。"}], "explanations": {"各地": "名词，指每一个地方，与“雨季到了，都开始下雨”的全称义相合。", "某地": "语义：“某地”指不确定的一处，与“都开始下雨”表示每一处的全称义冲突。", "大家": "语义：“大家”指人，不指地方，不能作“都开始下雨”的主语。", "某个": "语法：“某个”须接名词作定语，单独作主语不成立，无法承接“都”。"}, "sentence_index": 0, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，这个各地的花都开了。", "explanation": "这里应该用〈某地〉。各地指每一个地方，不能与“这个”这样的单指词连用；指一处应说“某地”。"}, {"text": "春天到了，各地的花只在一处开。", "explanation": "这里应该用〈某地〉。各地指每一个地方，与“只在一处开”的单一地点相矛盾，应改用“某地”。"}, {"text": "春天到了，我和各地一起赏了花。", "explanation": "这里应该用〈大家〉。各地指地方，不能作为一起赏花的人，应说“大家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "名词，指每一个地方，与“明天有大雨”的全称范围相合。"}, {"text": "一切", "is_correct": false, "explanation": "语法：“一切”指所有事物，不能作“有大雨”的处所主语，句子不通。"}, {"text": "大家", "is_correct": false, "explanation": "语法：“大家”指人，不能作“有大雨”的处所主语，句子不通。"}, {"text": "每", "is_correct": false, "explanation": "语法：“每”须接量词或名词，不能单独作“有大雨”的主语。"}], "explanations": {"各地": "名词，指每一个地方，与“明天有大雨”的全称范围相合。", "一切": "语法：“一切”指所有事物，不能作“有大雨”的处所主语，句子不通。", "大家": "语法：“大家”指人，不能作“有大雨”的处所主语，句子不通。", "每": "语法：“每”须接量词或名词，不能单独作“有大雨”的主语。"}, "sentence_index": 6, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "各地的商店晚上九点和我们一起吃饭。", "explanation": "这里应该用〈大家〉。各地指地方，不能作为一起吃饭的人。"}, {"text": "这一个各地的商店晚上九点关门。", "explanation": "这里应该用〈本地〉。各地指每一个地方，不能与“这一个”这样的单指词连用。"}, {"text": "我家门口的那家商店在各地晚上九点关门。", "explanation": "这里应该用〈本地〉。一家商店只在一个地方，不能说它在“各地”关门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛的消息让各地们的球迷都兴奋起来了。", "corrected_sentence": "这场比赛的消息让各地的球迷都兴奋起来了。", "error_description": "错误形式：“各地们”；正确形式：“各地”。“各地”是处所词，不能加“们”表示复数，应说“各地的球迷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天各地有都大雨，请注意安全。", "corrected_sentence": "明天各地都有大雨，请注意安全。", "error_description": "错误形式：“有都大雨”；正确形式：“都有大雨”。“都”要放在动词“有”之前，表示每一处都如此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "当场是就在那个地方，那个时候。", "primary_collocate": null, "pronunciation": "dāng chǎng", "ipa": "tɑŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他听了这句话，当场就哭了。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察当场抓住了小偷。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当场给我们打了分。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当场答应了我们的要求。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西的时候，她当场就付了钱。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人当场说这个菜不好吃。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到成绩，当场高兴地跳了起来。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理当场决定请大家吃饭。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿到礼物，当场打开看了。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔倒了，医生当场帮他检查。", "target_word": "当场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "就在事情发生的那个地方、那个时候，马上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当场", "is_correct": true, "explanation": "正确。“当场”表示就在听到这句话的那一刻发生，与后面的“就哭了”衔接自然。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直以来或从未如此，与“听了这句话”这一次具体的反应矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定期地发生，不能描述听到这句话后马上出现的一次反应。"}, {"text": "永远", "is_correct": false, "explanation": "搭配：“永远”指持续不变，不能与“就哭了”这种已经完成的一次性动作搭配。"}], "explanations": {"当场": "正确。“当场”表示就在听到这句话的那一刻发生，与后面的“就哭了”衔接自然。", "从来": "语义：“从来”表示一直以来或从未如此，与“听了这句话”这一次具体的反应矛盾。", "偶尔": "语义：“偶尔”表示不定期地发生，不能描述听到这句话后马上出现的一次反应。", "永远": "搭配：“永远”指持续不变，不能与“就哭了”这种已经完成的一次性动作搭配。"}, "sentence_index": 0, "correct_answer": "当场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当场我还很年轻。", "explanation": "这里应该用〈当时〉。“当场”只指事情发生的那一刻和地点，不能表示一段过去的时间。"}, {"text": "我每天当场起床。", "explanation": "这里应该用〈按时〉。“当场”指就在某一时刻、某一地点发生的一次性事件，不能描述每天重复的习惯。"}, {"text": "这间房子当场很大。", "explanation": "这里应该用〈确实〉。“当场”只修饰就在某一时刻发生的动作，不能描写“很大”这类状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当场", "is_correct": true, "explanation": "正确。“当场”表示看到成绩的那一刻就高兴地跳了起来，与句子的叙述一致。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定了“高兴”，与看到成绩后“高兴地跳了起来”的情绪相矛盾。"}, {"text": "未必", "is_correct": false, "explanation": "语义：“未必”表示不一定，与句中已经发生的事实“跳了起来”相矛盾。"}, {"text": "悄悄", "is_correct": false, "explanation": "搭配：“悄悄”表示无声无息，不能与“高兴地跳了起来”这种外露的动作搭配。"}], "explanations": {"当场": "正确。“当场”表示看到成绩的那一刻就高兴地跳了起来，与句子的叙述一致。", "不": "语义：“不”否定了“高兴”，与看到成绩后“高兴地跳了起来”的情绪相矛盾。", "未必": "语义：“未必”表示不一定，与句中已经发生的事实“跳了起来”相矛盾。", "悄悄": "搭配：“悄悄”表示无声无息，不能与“高兴地跳了起来”这种外露的动作搭配。"}, "sentence_index": 6, "correct_answer": "当场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听说了这件事，当场搬到了外地。", "explanation": "这里应该用〈立即〉。“当场”指就在原地、此刻发生的事，而“搬到外地”要离开原地，两者不能搭配。"}, {"text": "我明天当场去医院。", "explanation": "这里应删去“当场”，直接说“我明天去医院”。“当场”指此刻就地发生的事，不能用于“明天”这样的将来时间。"}, {"text": "这份工作，他当场做了十年。", "explanation": "这里应该用〈一直〉。“当场”指就在某一时刻、某一地点发生的事，不能与表示长时间的“做了十年”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很当场同意了这个方案。", "corrected_sentence": "老板当场同意了这个方案。", "error_description": "错误：“当场”是表示时间和地点的副词，不能受程度副词“很”修饰。应去掉“很”：老板当场同意了这个方案。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的当场拒绝了那个提议。", "corrected_sentence": "她当场拒绝了那个提议。", "error_description": "错误：“当场”是副词，只能作状语，不能加“的”变成定语。应说“当场拒绝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
