INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "列举是把东西一个一个说出来。", "primary_collocate": null, "pronunciation": "liè jǔ", "ipa": "lie̯˥˩ tɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "请你列举三个你喜欢的水果。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们列举常见的动物。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他列举了很多例子来说明这个问题。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能列举几种不同的交通工具吗？", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把买菜要买的东西都列举出来了。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友列举了去北京要看的地方。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气列举了十个国家的名字。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请列举你每天做的三件事。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次考试的失误一条一条列举出来。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有列举过自己的缺点。", "target_word": "列举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列举了", "label": "体标"}, {"form": "列举着", "label": "体标"}, {"form": "列举过", "label": "体标"}, {"form": "列舉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把事物一个一个说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88383, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列举", "is_correct": true, "explanation": "正确答案。列举是把东西一个一个说出来。"}, {"text": "猎具", "is_correct": false, "explanation": "jù（第四声）与 jǔ（第三声）声调不同，猎具指打猎用的工具。"}, {"text": "猎取", "is_correct": false, "explanation": "qǔ 与 jǔ 声母不同（q 与 j），猎取指努力去获取。"}, {"text": "烈酒", "is_correct": false, "explanation": "jiǔ 与 jǔ 韵母不同（iou 与 ü），烈酒指度数高的酒。"}], "explanations": {"列举": "正确答案。列举是把东西一个一个说出来。", "猎具": "jù（第四声）与 jǔ（第三声）声调不同，猎具指打猎用的工具。", "猎取": "qǔ 与 jǔ 声母不同（q 与 j），猎取指努力去获取。", "烈酒": "jiǔ 与 jǔ 韵母不同（iou 与 ü），烈酒指度数高的酒。"}, "sentence_index": null, "correct_answer": "列举"}, "level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于“水果”。"}, {"text": "列举", "is_correct": true, "explanation": "正确。“列举”是一个一个说出来，可以带“三个你喜欢的水果”作宾语。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”是不及物动词，不能带“三个你喜欢的水果”作宾语。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”针对车辆等交通工具，不能用于“水果”。"}], "explanations": {"修理": "搭配：“修理”针对器物，不能用于“水果”。", "列举": "正确。“列举”是一个一个说出来，可以带“三个你喜欢的水果”作宾语。", "游泳": "搭配：“游泳”是不及物动词，不能带“三个你喜欢的水果”作宾语。", "驾驶": "搭配：“驾驶”针对车辆等交通工具，不能用于“水果”。"}, "sentence_index": 0, "correct_answer": "列举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "货架上列举着各种饮料。", "explanation": "这里应该用〈罗列〉。列举指一项项说出或写出，不能用于把实物摆放在某处；摆在货架上的东西要用罗列。"}, {"text": "他列举了一碗热汤。", "explanation": "这里应该用〈端〉。列举指一项项说出或写出，不指端起东西；一碗汤是整体，无法一项项列举。"}, {"text": "博物馆里列举着很多古老的陶器。", "explanation": "这里应该用〈陈列〉。列举指一项项说出，不指把展品摆出来供人观看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
